INSERT INTO `Competency` (`id`, `code`, `name`, `short`, `categoryId`, `departmentId`, `importance`, `requiredLevel`, `skillAreas`, `active`) VALUES
(1, 'rb1', 'Research Design & Methodology', 'Research Design', 1, 3, 4, 5.00, '["Research Proposal Development","Survey Design","Sampling Techniques","Field Data Collection","Research Ethics"]', 1),
(2, 'rb2', 'Data Analysis & Statistical Modelling', 'Data Analysis', 1, 3, 4, 5.00, '["Use of Data Analysis Tools (STATA/SPSS etc.)","Data Visualization","Predictive Analytics","Regression Analysis","Database Management"]', 1),
(3, 'rb3', 'Business Development & Partnerships', 'Business Dev.', 1, 3, 4, 5.00, '["Stakeholder Engagement","Fundable Proposal Development","Partnership Negotiation","Market Research","Revenue Generation Strategies","Business Intelligence"]', 1),
(4, 'rb4', 'Project Management', 'Project Mgmt', 1, 3, 4, 5.00, '["Project Scheduling","Budget Management","Risk Management","Monitoring and Evaluation","Team Coordination"]', 1),
(5, 'rb5', 'Innovation & Strategic Foresight', 'Innovation', 1, 3, 4, 5.00, '["Scenario Planning","Design Thinking","Trend Analysis","Digital Transformation Planning","Change Management"]', 1),
(6, 'rb6', 'Report Writing & Knowledge Management', 'Report Writing', 1, 3, 4, 5.00, '["Technical Report Writing","Editing and Proofreading","Knowledge Sharing","Presentation Development","Documentation Management"]', 1),
(7, 'rb7', 'Data Commercialization and Services', 'Data Commercial.', 1, 3, 4, 5.00, '["Data Monetization","Business Intelligence Services","Service Pricing","Client Management","Data Governance"]', 1),
(8, 'rb8', 'Climate Change and Sustainable Mobility', 'Climate & Mobility', 1, 3, 4, 5.00, '["Climate Policy Analysis","Sustainable Transport Planning","EV Ecosystem Knowledge","Carbon Emissions Reporting","Environmental Impact Assessment"]', 1),
(9, 'hr1_1', 'Job Analysis & Role Profiling', 'Job Analysis', 2, 2, 4, 5.00, NULL, 1),
(10, 'hr1_2', 'Sourcing Strategies', 'Sourcing', 2, 2, 4, 5.00, NULL, 1),
(11, 'hr1_3', 'Candidate Assessment & Interviewing Techniques', 'Interviewing', 2, 2, 4, 5.00, NULL, 1),
(12, 'hr1_4', 'Employer Branding & Candidate Experience Management', 'Employer Branding', 2, 2, 4, 5.00, NULL, 1),
(13, 'hr1_5', 'Selection Tools & Psychometric Testing', 'Psychometrics', 2, 2, 4, 5.00, NULL, 1),
(14, 'hr1_6', 'Diversity, Equity & Inclusion (DEI) Hiring Practices', 'DEI Hiring', 2, 2, 4, 5.00, NULL, 1),
(15, 'hr2_1', 'Training Needs Analysis (TNA)', 'TNA', 3, 2, 4, 5.00, NULL, 1),
(16, 'hr2_2', 'Instructional Design & Curriculum Development', 'Instructional Design', 3, 2, 4, 5.00, NULL, 1),
(17, 'hr2_3', 'Learning Program Delivery & Facilitation', 'Facilitation', 3, 2, 4, 5.00, NULL, 1),
(18, 'hr2_4', 'E-learning & Digital Learning Platform Management', 'E-learning', 3, 2, 4, 5.00, NULL, 1),
