INSERT INTO `AssessmentVersion` (`id`, `assessmentId`, `versionNo`, `status`, `scoringConfigId`, `approvedById`, `approvedAt`, `publishedById`, `publishedAt`)
VALUES (1, 1, 1, 'PUBLISHED', 1, 1, CURRENT_TIMESTAMP(3), 1, CURRENT_TIMESTAMP(3))
ON DUPLICATE KEY UPDATE `status` = 'PUBLISHED';

INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(1, 1, 1, 'SINGLE_CHOICE', 'An Assistant Officer is tasked with assembling the appendices and literature logs for an upcoming DVLA road safety study proposal. While cross-referencing citations, they find conflicting publication dates for a key transport policy document. What should the officer do FIRST?', 'Research Proposal Development', 1.00),
(2, 1, 2, 'SINGLE_CHOICE', 'Why must an Assistant Officer strictly follow the background formatting and structural guidelines outlined in an approved research brief during proposal drafting?', 'Research Proposal Development', 1.00),
(3, 1, 3, 'SINGLE_CHOICE', 'While pre-testing a digital survey questionnaire meant for commercial drivers at a DVLA district office, an Assistant Officer notes that respondents consistently skip a question regarding annual insurance costs. What is the most appropriate initial action?', 'Survey Design', 1.00),
(4, 1, 4, 'SINGLE_CHOICE', 'What is the primary purpose of executing a pilot test of a survey instrument before full-scale deployment?', 'Survey Design', 1.00),
(5, 1, 5, 'SINGLE_CHOICE', 'A sampling plan requires an Assistant Officer to select every 10th vehicle entering a DVLA facility for a brief interview. On Tuesday morning, a massive convoy of heavy-duty trucks enters together, filling slots 10 through 40. How should the officer handle this?', 'Sampling Techniques', 1.00),
(6, 1, 6, 'SINGLE_CHOICE', 'In a simple random sampling exercise of registered vehicle owners, what needs to be done regarding the sampling frame?', 'Sampling Techniques', 1.00),
(7, 1, 7, 'SINGLE_CHOICE', 'During a roadside data collection exercise on emissions awareness, a driver becomes hostile and refuses to complete the questionnaire. What is the Assistant Officer''s correct course of action?', 'Field Data Collection', 1.00),
(8, 1, 8, 'SINGLE_CHOICE', 'Which tool is best suited for an Assistant Officer to track daily submissions and monitor target progress during a large-scale field data collection exercise?', 'Field Data Collection', 1.00),
(9, 1, 9, 'SINGLE_CHOICE', 'A participant completing a DVLA customer satisfaction survey asks an Assistant Officer if their personal identity and passport details will be visible to district licensing managers. What should the officer state?', 'Research Ethics', 1.00),
(10, 1, 10, 'SINGLE_CHOICE', 'Before starting an interview regarding driver medical histories, what must an Assistant Officer obtain from a respondent?', 'Research Ethics', 1.00),
(11, 1, 11, 'SINGLE_CHOICE', 'An Assistant Officer needs to import a raw .csv survey data file containing vehicle safety logs into SPSS or STATA. During import, several numeric columns display text errors due to missing value codes written as "NULL". What should the officer do FIRST?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(12, 1, 12, 'SINGLE_CHOICE', 'In data analysis software, what is the main objective of running a basic frequency distribution check on a newly imported data variable like "Driver Age"?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(13, 1, 13, 'SINGLE_CHOICE', 'An Assistant Officer is asked to present the percentage distribution of different vehicle categories (Saloons, SUVs, Heavy Trucks, Motorbikes) registered in Q1. Which visualization type is most appropriate for showing these parts of a whole?', 'Data Visualization', 1.00),
(14, 1, 14, 'SINGLE_CHOICE', 'When designing a bar chart to compare customer wait times across five DVLA offices, what formatting practice should an Assistant Officer follow to avoid misleading readers?', 'Data Visualization', 1.00),
(15, 1, 15, 'SINGLE_CHOICE', 'An Assistant Officer is cleaning historical data models used to forecast driver license application volumes. They encounter a variable column with multiple missing blocks. Why is accurate data cleaning vital for predictive models?', 'Predictive Analytics', 1.00),
(16, 1, 16, 'SINGLE_CHOICE', 'What baseline metric does an Assistant Officer look at to determine the historical linear direction between vehicle age and annual mileage?', 'Predictive Analytics', 1.00),
(17, 1, 17, 'SINGLE_CHOICE', 'While preparing a dataset for a linear regression model testing factors that influence processing speeds, an Assistant Officer identifies two duplicate records for the same vehicle license application. What is the standard practice?', 'Regression Analysis', 1.00),
(18, 1, 18, 'SINGLE_CHOICE', 'What is the fundamental responsibility of an Assistant Officer when setting up variables for regression models?', 'Regression Analysis', 1.00),
(19, 1, 19, 'SINGLE_CHOICE', 'An Assistant Officer is updating driver compliance logs in a temporary database table. They realize they accidentally ran an update query without a filter, modifying incorrect rows. What should they do FIRST?', 'Database Management', 1.00),
(20, 1, 20, 'SINGLE_CHOICE', 'Why is the use of a unique primary identifier (such as a unique Vehicle Identification Number) critical when an Assistant Officer enters records into a relational database?', 'Database Management', 1.00),
(21, 1, 21, 'SINGLE_CHOICE', 'An Assistant Officer is managing the sign-in logs and feedback sheets at a stakeholder workshop for transport operators. A participant leaves without providing contact details on their feedback form. How should the officer respond?', 'Stakeholder Engagement', 1.00),
(22, 1, 22, 'SINGLE_CHOICE', 'What is the primary role of an Assistant Officer during a strategic stakeholder consultation meeting?', 'Stakeholder Engagement', 1.00),
(23, 1, 23, 'SINGLE_CHOICE', 'While gathering cost profiles for a grant proposal supporting new driver training software, an Assistant Officer notices that local supplier quotes vary widely. How should this budget data be structured?', 'Fundable Proposal Development', 1.00),
(24, 1, 24, 'SINGLE_CHOICE', 'In a grant application process, what section is an Assistant Officer typically responsible for compiling under senior supervision?', 'Fundable Proposal Development', 1.00),
(25, 1, 25, 'SINGLE_CHOICE', 'A representative from an external tech firm calls an Assistant Officer asking for early details on the DVLA''s negotiating position regarding a data-sharing partnership. How should the officer handle this request?', 'Partnership Negotiation', 1.00),
(26, 1, 26, 'SINGLE_CHOICE', 'Why is it vital for an Assistant Officer to maintain organized files of all preliminary letters and meeting notes during a partnership exploration phase?', 'Partnership Negotiation', 1.00),
(27, 1, 27, 'SINGLE_CHOICE', 'An Assistant Officer is tasked with gathering competitive pricing information on digital driving simulators from five public web portals. They discover two portals do not list their prices online. What is the best step?', 'Market Research', 1.00),
(28, 1, 28, 'SINGLE_CHOICE', 'What is the main objective of primary market data tracking at the Assistant Officer level?', 'Market Research', 1.00),
(29, 1, 29, 'SINGLE_CHOICE', 'While tracking weekly revenue collections from premium licensing services, an Assistant Officer spots an unexplained 15% drop in transaction volume at a specific terminal. What should they do FIRST?', 'Revenue Generation Strategies', 1.00),
(30, 1, 30, 'SINGLE_CHOICE', 'Which metric is an Assistant Officer most likely to track daily when monitoring the rollout of a new fee-based service option?', 'Revenue Generation Strategies', 1.00),
(31, 1, 31, 'SINGLE_CHOICE', 'An Assistant Officer is compiling a public report on commercial fleet expansion trends. They extract a table from a reliable industry source but realize the metrics use different units than the DVLA standard. What is the correct protocol?', 'Business Intelligence', 1.00),
(32, 1, 32, 'SINGLE_CHOICE', 'What is the fundamental focus of an Assistant Officer when collecting business intelligence data?', 'Business Intelligence', 1.00),
(33, 1, 33, 'SINGLE_CHOICE', 'An Assistant Officer is updating a project progress chart and notices a specific task is three days behind schedule. How should they record this development on the team tracking sheet?', 'Project Scheduling', 1.00),
(34, 1, 34, 'SINGLE_CHOICE', 'In project schedule management, what does a milestone represent to an Assistant Officer?', 'Project Scheduling', 1.00),
(35, 1, 35, 'SINGLE_CHOICE', 'While reviewing expense receipts from a regional field research trip, an Assistant Officer finds a receipt that lacks a valid vendor stamp and description. What is the correct initial action?', 'Budget Management', 1.00),
(36, 1, 36, 'SINGLE_CHOICE', 'Why is careful tracking of small office supply costs important for an Assistant Officer managing a project''s petty cash log?', 'Budget Management', 1.00),
(37, 1, 37, 'SINGLE_CHOICE', 'During a field deployment planning session, an Assistant Officer notices the weather forecast predicts heavy rain during scheduled outdoor vehicle intercept interviews. What should they do FIRST?', 'Risk Management', 1.00),
(38, 1, 38, 'SINGLE_CHOICE', 'What is the role of an Assistant Officer regarding the project risk register?', 'Risk Management', 1.00),
(39, 1, 39, 'SINGLE_CHOICE', 'An Assistant Officer is entering monthly performance metrics into an M&E spreadsheet. They notice that a field office reported "95%" for driver data completeness, but the raw logs show only 60%. What is the correct action?', 'Monitoring and Evaluation', 1.00),
(40, 1, 40, 'SINGLE_CHOICE', 'What is the main purpose of a performance indicator tracking sheet for an Assistant Officer?', 'Monitoring and Evaluation', 1.00),
(41, 1, 41, 'SINGLE_CHOICE', 'An Assistant Officer is assigned to coordinate meeting times for a 5-member research team. Two members fail to respond to three consecutive calendar invitations. What should the officer do?', 'Team Coordination', 1.00),
(42, 1, 42, 'SINGLE_CHOICE', 'Which communication tool is most appropriate for an Assistant Officer to share daily updates within an active project group?', 'Team Coordination', 1.00),
(43, 1, 43, 'SINGLE_CHOICE', 'An Assistant Officer is helping compile data tables showing how ride-hailing app usage might grow over the next 5 years. They find three different growth projections. How should they organize this data?', 'Scenario Planning', 1.00),
(44, 1, 44, 'SINGLE_CHOICE', 'In scenario planning tasks, what is the primary role of an Assistant Officer?', 'Scenario Planning', 1.00),
(45, 1, 45, 'SINGLE_CHOICE', 'During a focus group session focused on improving the driver license collection room, a customer complains that the directional signs are confusing. What should the Assistant Officer do?', 'Design Thinking', 1.00),
(46, 1, 46, 'SINGLE_CHOICE', 'What does the "Empathize" phase of Design Thinking mean for an Assistant Officer working on a service process improvement project?', 'Design Thinking', 1.00),
(47, 1, 47, 'SINGLE_CHOICE', 'An Assistant Officer is tracking internet connectivity levels among drivers across several districts. They discover data from one rural district has not been updated since 2021. How should they present this trend line?', 'Trend Analysis', 1.00),
(48, 1, 48, 'SINGLE_CHOICE', 'Why is it important for an Assistant Officer to track historical technology adoption rates over time?', 'Trend Analysis', 1.00),
(49, 1, 49, 'SINGLE_CHOICE', 'While testing a new online portal for license renewals, an Assistant Officer finds that the system crashes whenever a user uploads a file larger than 2MB. What should they do FIRST?', 'Digital Transformation Planning', 1.00),
(50, 1, 50, 'SINGLE_CHOICE', 'What is the main operational focus of an Assistant Officer during the digital transformation of an old paper filing system?', 'Digital Transformation Planning', 1.00),
(51, 1, 51, 'SINGLE_CHOICE', 'The department is moving from a legacy database system to a modern web- based tool. Several staff members are unhappy and complain about the new layout. How should the Assistant Officer handle this?', 'Change Management', 1.00),
(52, 1, 52, 'SINGLE_CHOICE', 'Why is clear user documentation and basic tracking helpful during a corporate system transition?', 'Change Management', 1.00),
(53, 1, 53, 'SINGLE_CHOICE', 'An Assistant Officer is assembling a statistical appendix for a quarterly research report. They find that three data tables use different numbering formats. What is the best step?', 'Technical Report Writing', 1.00),
(54, 1, 54, 'SINGLE_CHOICE', 'What should an Assistant Officer prioritize when writing the descriptive findings section of an operational research summary?', 'Technical Report Writing', 1.00),
(55, 1, 55, 'SINGLE_CHOICE', 'While proofreading a draft policy document, an Assistant Officer notices that the term "Authority" is spelled incorrectly in multiple places across several pages. What is the correct action?', 'Editing and Proofreading', 1.00),
(56, 1, 56, 'SINGLE_CHOICE', 'What is an Assistant Officer''s primary objective when conducting a basic editing check on a data report draft?', 'Editing and Proofreading', 1.00),
(57, 1, 57, 'SINGLE_CHOICE', 'An Assistant Officer returns from an advanced training course on data collection software. What should they do with the training materials and user guides they received?', 'Knowledge Sharing', 1.00),
(58, 1, 58, 'SINGLE_CHOICE', 'How does an organized internal knowledge sharing process help an Assistant Officer within the RBDI team?', 'Knowledge Sharing', 1.00),
(59, 1, 59, 'SINGLE_CHOICE', 'An Assistant Officer is building slide visuals for a manager''s presentation to a transport board. The slide contains 15 lines of tiny text, making it hard to read. How should this be fixed?', 'Presentation Development', 1.00),
(60, 1, 60, 'SINGLE_CHOICE', 'What design rule should an Assistant Officer follow to ensure a slide deck looks professional?', 'Presentation Development', 1.00),
(61, 1, 61, 'SINGLE_CHOICE', 'An Assistant Officer is archiving final project folders on the shared network drive. What file naming style should they use to ensure files are easy to find later?', 'Documentation Management', 1.00),
(62, 1, 62, 'SINGLE_CHOICE', 'Why is proper file version control helpful when multiple team members are working on a report draft?', 'Documentation Management', 1.00),
(63, 1, 63, 'SINGLE_CHOICE', 'A private logistics firm requests a standard public data catalog from an Assistant Officer. The officer notices the firm''s contact email is missing from the request sheet. What should they do FIRST?', 'Data Monetization', 1.00),
(64, 1, 64, 'SINGLE_CHOICE', 'What is the role of an Assistant Officer in the data monetization program at the DVLA?', 'Data Monetization', 1.00),
(65, 1, 65, 'SINGLE_CHOICE', 'An Assistant Officer is updating a regular business intelligence dashboard used by commercial fleet operators. They find a broken link that stops users from downloading data summary files. What is the correct step?', 'Business Intelligence Services', 1.00),
(66, 1, 66, 'SINGLE_CHOICE', 'What type of information does an Assistant Officer typically organize for commercial data dashboards?', 'Business Intelligence Services', 1.00),
(67, 1, 67, 'SINGLE_CHOICE', 'A commercial user asks an Assistant Officer for a custom data extract and claims a manager promised them a 50% discount. No discount code or approval letter is on file. What should the officer do?', 'Service Pricing', 1.00),
(68, 1, 68, 'SINGLE_CHOICE', 'Why must an Assistant Officer understand the current official DVLA service fees schedule?', 'Service Pricing', 1.00),
(69, 1, 69, 'SINGLE_CHOICE', 'A data subscriber calls an Assistant Officer to complain that their monthly report file was delivered late and was formatted incorrectly. How should the officer handle the call?', 'Client Management', 1.00),
(70, 1, 70, 'SINGLE_CHOICE', 'What is the primary client management task of an Assistant Officer handling commercial data accounts?', 'Client Management', 1.00),
(71, 1, 71, 'SINGLE_CHOICE', 'While reviewing a vehicle data sheet intended for an external researcher, an Assistant Officer notices that three columns contain clear details like personal phone numbers and home addresses. What is the correct action?', 'Data Governance', 1.00),
(72, 1, 72, 'SINGLE_CHOICE', 'What basic principle of data governance must an Assistant Officer follow when handling public vehicle records?', 'Data Governance', 1.00),
(73, 1, 73, 'SINGLE_CHOICE', 'An Assistant Officer is organizing reference papers on green transport policies for a senior analyst. They find a mix of international treaties and local guidelines. How should they arrange them?', 'Climate Policy Analysis', 1.00),
(74, 1, 74, 'SINGLE_CHOICE', 'What is the main duty of an Assistant Officer when supporting environmental policy research within the RBDI department?', 'Climate Policy Analysis', 1.00),
(75, 1, 75, 'SINGLE_CHOICE', 'An Assistant Officer is logging vehicle type counts from a pilot bus-rapid- transit corridor study. They spot an entry that lists a commercial vehicle passenger capacity as "900" instead of "90." What should they do FIRST?', 'Sustainable Transport Planning', 1.00),
(76, 1, 76, 'SINGLE_CHOICE', 'Why do Assistant Officers collect daily passenger volume counts on public transport routes?', 'Sustainable Transport Planning', 1.00),
(77, 1, 77, 'SINGLE_CHOICE', 'An electric vehicle importer asks an Assistant Officer for the official technical checklist required to register a new electric car model. The officer cannot find the document on their desk. What should they do?', 'EV Ecosystem Knowledge', 1.00),
(78, 1, 78, 'SINGLE_CHOICE', 'Which technical detail does an Assistant Officer focus on when entering data for a newly registered electric vehicle into the tracking system?', 'EV Ecosystem Knowledge', 1.00),
(79, 1, 79, 'SINGLE_CHOICE', 'An Assistant Officer is copying exhaust testing numbers from a regional depot sheet into a central carbon database. They notice that the measurement units on one sheet are different from the central database layout. What is the correct step?', 'Carbon Emissions Reporting', 1.00),
(80, 1, 80, 'SINGLE_CHOICE', 'What is the primary purpose of a carbon emissions tracking sheet for an Assistant Officer?', 'Carbon Emissions Reporting', 1.00),
(81, 1, 81, 'SINGLE_CHOICE', 'During an environmental survey near a busy vehicle testing center, an Assistant Officer notes that the air quality monitoring tool shows an error code. What is the correct initial action?', 'Environmental Impact Assessment', 1.00),
(82, 1, 82, 'SINGLE_CHOICE', 'What is the main responsibility of an Assistant Officer during a regional environmental impact survey of DVLA operations?', 'Environmental Impact Assessment', 1.00)
