INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(83, 2, 1, 'SINGLE_CHOICE', 'An Officer is reviewing research proposals focused on upgrading driver testing centers. They notice the scope statement lacks clear boundaries regarding geographical coverage. What should be done FIRST?', 'Research Proposal Development', 1.00),
(84, 2, 2, 'SINGLE_CHOICE', 'Which practice best demonstrates research proposal proficiency at the Officer level?', 'Research Proposal Development', 1.00),
(85, 2, 3, 'SINGLE_CHOICE', 'While analyzing a customer feedback survey script, An Officer notices several leading questions that favor the current driver licensing workflow. What is the most appropriate action?', 'Survey Design', 1.00),
(86, 2, 4, 'SINGLE_CHOICE', 'When selecting a scale structure for a survey tracking customer wait times, what design choice provides the cleanest data for analysis?', 'Survey Design', 1.00),
(87, 2, 5, 'SINGLE_CHOICE', 'An optimization study requires a representative sample of registered vehicle owners across regions with varying registration volumes. Which approach should the Officer apply?', 'Sampling Techniques', 1.00),
(88, 2, 6, 'SINGLE_CHOICE', 'How should An Officer address a high non-response rate discovered in a stratified sample during an active field survey?', 'Sampling Techniques', 1.00),
(89, 2, 7, 'SINGLE_CHOICE', 'An Officer leading a field data collection team discovers that two digital data collection tablets are uploading corrupted files to the central server. What should be done FIRST?', 'Field Data Collection', 1.00),
(90, 2, 8, 'SINGLE_CHOICE', 'Which methodology best ensures high-quality data entry during large- scale field interviews?', 'Field Data Collection', 1.00),
(91, 2, 9, 'SINGLE_CHOICE', 'A research institute asks An Officer for access to raw vehicle licensing records that include customer ID numbers and home addresses. What is the correct protocol?', 'Research Ethics', 1.00),
(92, 2, 10, 'SINGLE_CHOICE', 'How does An Officer protect research ethics when working with vulnerable research subjects, such as drivers involved in severe traffic accidents?', 'Research Ethics', 1.00),
(93, 2, 11, 'SINGLE_CHOICE', 'A dataset containing vehicle inspection metrics shows skewed distribution patterns. What action should An Officer take before running parametric tests in STATA or SPSS?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(94, 2, 12, 'SINGLE_CHOICE', 'What does An Officer use syntax or script files (such as .do files in STATA or .sps in SPSS) for during data analysis?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(95, 2, 13, 'SINGLE_CHOICE', 'An Officer needs to show the structural relationship between engine displacement size and actual carbon output across 500 tested vehicles. Which chart type is best?', 'Data Visualization', 1.00),
(96, 2, 14, 'SINGLE_CHOICE', 'When designing an administrative dashboard for executive leadership, what visualization strategy should An Officer apply?', 'Data Visualization', 1.00),
(97, 2, 15, 'SINGLE_CHOICE', 'An Officer is building a time-series model to predict vehicle registration volumes for the next 24 months. What is a critical requirement for this data analysis?', 'Predictive Analytics', 1.00),
(98, 2, 16, 'SINGLE_CHOICE', 'What does a high Mean Absolute Percentage Error (MAPE) score indicate to An Officer evaluating a predictive model?', 'Predictive Analytics', 1.00),
(99, 2, 17, 'SINGLE_CHOICE', 'A multiple linear regression model evaluating driver test scores shows an overall of 0.75, but the residual analysis displays heteroscedasticity. How should the Officer address this?', 'Regression Analysis', 1.00),
(100, 2, 18, 'SINGLE_CHOICE', 'What is the correct interpretation of a multiple regression coefficient of for a variable measuring "wait time at desk" against a "customer satisfaction score"?', 'Regression Analysis', 1.00),
(101, 2, 19, 'SINGLE_CHOICE', 'An Officer needs to combine quarterly vehicle inspection data from a regional table with a central vehicle registration index. Which SQL operation is most appropriate?', 'Database Management', 1.00),
(102, 2, 20, 'SINGLE_CHOICE', 'Why is enforcing referential integrity critical within a DVLA database management system?', 'Database Management', 1.00),
(103, 2, 21, 'SINGLE_CHOICE', 'During a consultation with transport unions regarding digital logbooks, several union leaders express deep concern about data tracking costs. How should the Officer respond?', 'Stakeholder Engagement', 1.00),
(104, 2, 22, 'SINGLE_CHOICE', 'How should An Officer evaluate stakeholder interest and influence levels before launching a new partnership initiative?', 'Stakeholder Engagement', 1.00),
(105, 2, 23, 'SINGLE_CHOICE', 'An Officer is drafting a project proposal for an international grant focused on eco-friendly transport systems. The grant guidelines require a clear theory of change. What should the officer ensure?', 'Fundable Proposal Development', 1.00),
(106, 2, 24, 'SINGLE_CHOICE', 'In a commercial proposal, how should An Officer present the financial sustainability plan for a new co-branded service?', 'Fundable Proposal Development', 1.00),
(107, 2, 25, 'SINGLE_CHOICE', 'During negotiations with a commercial bank to co-locate driver registration points, the bank demands exclusive access to driver email lists. How should the Officer address this?', 'Partnership Negotiation', 1.00),
(108, 2, 26, 'SINGLE_CHOICE', 'What is a key responsibility of An Officer when evaluating draft terms in a Memorandum of Understanding (MoU)?', 'Partnership Negotiation', 1.00),
(109, 2, 27, 'SINGLE_CHOICE', 'An Officer is reviewing a market feasibility report on premium on- demand license plate services. They notice the survey data was collected only from one high-income community. What analysis should they make?', 'Market Research', 1.00),
(110, 2, 28, 'SINGLE_CHOICE', 'How should An Officer use competitor analysis data when designing a new paid business intelligence service line?', 'Market Research', 1.00),
(111, 2, 29, 'SINGLE_CHOICE', 'An Officer is evaluating the performance of a dynamic service pricing model implemented at high-volume district offices. The data shows revenue grew, but customer complaints increased by 40%. What is the best analytical response?', 'Revenue Generation Strategies', 1.00),
(112, 2, 30, 'SINGLE_CHOICE', 'Which metric provides An Officer with the best insight into the financial health of a newly introduced revenue service line?', 'Revenue Generation Strategies', 1.00),
(113, 2, 31, 'SINGLE_CHOICE', 'An Officer is producing a business intelligence brief on commercial transport electrification. They find conflicting market growth figures from two global analytics firms. How should they handle this?', 'Business Intelligence', 1.00),
(114, 2, 32, 'SINGLE_CHOICE', 'How should An Officer structure an executive business intelligence report for departmental leadership?', 'Business Intelligence', 1.00),
(115, 2, 33, 'SINGLE_CHOICE', 'A project schedule has a tight timeline, and a key software module integration task is on the critical path. The developer reports a 5-day delay due to API errors. What is the Officer''s correct response?', 'Project Scheduling', 1.00),
(116, 2, 34, 'SINGLE_CHOICE', 'When using project management software (like MS Project or Asana), what is the main value of mapping out task dependencies for An Officer?', 'Project Scheduling', 1.00),
(117, 2, 35, 'SINGLE_CHOICE', 'An Officer notes that mid-year expenditures for a vehicle safety field study have reached 75% of the total annual budget allocation, while only 30% of field tasks are done. What action should they take?', 'Budget Management', 1.00),
(118, 2, 36, 'SINGLE_CHOICE', 'In project accounting, what does a negative Cost Variance (CV) indicate to An Officer?', 'Budget Management', 1.00),
(119, 2, 37, 'SINGLE_CHOICE', 'A risk assessment for a new mobile application rollout identifies a "High Probability, High Impact" risk related to user data leaks. What risk response should the Officer recommend?', 'Risk Management', 1.00),
(120, 2, 38, 'SINGLE_CHOICE', 'How should An Officer maintain and use a project risk register during project execution?', 'Risk Management', 1.00),
(121, 2, 39, 'SINGLE_CHOICE', 'An Officer is leading an M&E review of a new digital queue management system. The system reports an average wait time of 12 minutes, but on-site observations reveal actual wait times of 45 minutes. How should they resolve this?', 'Monitoring and Evaluation', 1.00),
(122, 2, 40, 'SINGLE_CHOICE', 'What is the key difference between an output indicator and an outcome indicator for An Officer running an M&E framework?', 'Monitoring and Evaluation', 1.00),
(123, 2, 41, 'SINGLE_CHOICE', 'Two technical specialists within a research project team are locked in a deep disagreement over data weighting models, slowing down progress. How should the Officer handle the conflict?', 'Team Coordination', 1.00),
(124, 2, 42, 'SINGLE_CHOICE', 'When managing a cross-functional team project, what is the best way for An Officer to ensure accountability for assigned tasks?', 'Team Coordination', 1.00),
(125, 2, 43, 'SINGLE_CHOICE', 'An Officer is designing structural scenarios for the future of vehicle licensing over a 10-year horizon. Which methodology should they use to select key scenario drivers?', 'Scenario Planning', 1.00),
(126, 2, 44, 'SINGLE_CHOICE', 'How should An Officer present alternative scenario options to management to support resilient strategy development?', 'Scenario Planning', 1.00),
(127, 2, 45, 'SINGLE_CHOICE', 'An Officer is leading a design thinking project to reduce licensing dropouts among commercial motorbike riders. In the "Ideate" phase, the team generates several unorthodox ideas. How should the officer manage this?', 'Design Thinking', 1.00),
(128, 2, 46, 'SINGLE_CHOICE', 'What is the value of creating a minimum viable product (MVP) prototype during a service redesign project at the DVLA?', 'Design Thinking', 1.00),
(129, 2, 47, 'SINGLE_CHOICE', 'While evaluating a 5-year trend analysis of vehicle emissions failures, An Officer notes a sudden drop in failure rates in 2024, followed by a sharp return to high failure rates in 2025. What analytical step is required?', 'Trend Analysis', 1.00),
(130, 2, 48, 'SINGLE_CHOICE', 'How does An Officer distinguish between a short-term operational fad and a long-term structural trend in the transport industry?', 'Trend Analysis', 1.00),
(131, 2, 49, 'SINGLE_CHOICE', 'An Officer is designing the workflow transformation for an automated digital driver testing platform. They need to ensure legacy paper scores migrate cleanly into the new system architecture. What should they do?', 'Digital Transformation Planning', 1.00),
(132, 2, 50, 'SINGLE_CHOICE', 'What critical factor must An Officer prioritize when evaluating a new software tool for digital vehicle registration?', 'Digital Transformation Planning', 1.00),
(133, 2, 51, 'SINGLE_CHOICE', 'A new enterprise resource tool is being launched in the RBDI department, and senior staff are actively resisting the transition, choosing to use legacy files. What change management step should the Officer take?', 'Change Management', 1.00),
(134, 2, 52, 'SINGLE_CHOICE', 'According to established change management frameworks (e.g., ADKAR), what is the first element An Officer must build when introducing a process change?', 'Change Management', 1.00),
(135, 2, 53, 'SINGLE_CHOICE', 'An Officer is finalizing a comprehensive research report on regional revenue leaking points. The report contains complex statistical tables and qualitative audit logs. How should this be structured?', 'Technical Report Writing', 1.00),
(136, 2, 54, 'SINGLE_CHOICE', 'How does An Officer ensure that their data report conclusions are technically sound and ready for leadership review?', 'Technical Report Writing', 1.00),
(137, 2, 55, 'SINGLE_CHOICE', 'An Officer is proofing a critical policy brief intended for the Ministry. They find that several complex statistical metrics contradict figures in the executive summary. What is the correct action?', 'Editing and Proofreading', 1.00),
(138, 2, 56, 'SINGLE_CHOICE', 'What formatting checks must An Officer enforce when reviewing a draft report against the official institutional style guide?', 'Editing and Proofreading', 1.00),
(139, 2, 57, 'SINGLE_CHOICE', 'The RBDI department has completed a landmark study on urban traffic data patterns. How should the Officer manage this asset to optimize internal knowledge sharing?', 'Knowledge Sharing', 1.00),
(140, 2, 58, 'SINGLE_CHOICE', 'What is the primary purpose of a post-project lesson-learned review session led by An Officer?', 'Knowledge Sharing', 1.00),
(141, 2, 59, 'SINGLE_CHOICE', 'An Officer is developing a presentation deck for the Board regarding a proposed data licensing framework. The Board has only a 15-minute window. How should the deck be structured?', 'Presentation Development', 1.00),
(142, 2, 60, 'SINGLE_CHOICE', 'When presenting complex regression model outputs to a non- technical corporate audience, what strategy should An Officer employ?', 'Presentation Development', 1.00),
(143, 2, 61, 'SINGLE_CHOICE', 'An Officer is organizing the repository folder for a multi-year national licensing system review. They find files spread across several personal folders with overlapping file names. What is the correct step?', 'Documentation Management', 1.00),
(144, 2, 62, 'SINGLE_CHOICE', 'Why is a strict document data access policy important within a research department?', 'Documentation Management', 1.00),
(145, 2, 63, 'SINGLE_CHOICE', 'A private vehicle analytics vendor wants to buy monthly raw tracking data models. An Officer notes that the data extraction script inadvertently includes driver names. What is the correct step?', 'Data Monetization', 1.00),
(146, 2, 64, 'SINGLE_CHOICE', 'How should An Officer evaluate the financial viability of a new data monetization product line?', 'Data Monetization', 1.00),
(147, 2, 65, 'SINGLE_CHOICE', 'A corporate client complains that the weekly commercial vehicle volume report they purchase from the DVLA contains mismatched numbers in the regional tables. How should the Officer handle this?', 'Business Intelligence Services', 1.00),
(148, 2, 66, 'SINGLE_CHOICE', 'When designing a new subscription-based business intelligence service for logistics companies, what design principle should An Officer prioritize?', 'Business Intelligence Services', 1.00),
(149, 2, 67, 'SINGLE_CHOICE', 'An Officer is analyzing a proposed pricing matrix for premium vehicle data lookups. The analysis shows that setting the price too high will reduce total data volume transactions by 60%. What recommendation should they make?', 'Service Pricing', 1.00),
(150, 2, 68, 'SINGLE_CHOICE', 'What cost factors must An Officer incorporate when calculating the floor price of a custom data extraction service?', 'Service Pricing', 1.00),
(151, 2, 69, 'SINGLE_CHOICE', 'A high-value corporate client requests a custom data validation API configuration that falls outside standard service protocols. How should the Officer proceed?', 'Client Management', 1.00),
(152, 2, 70, 'SINGLE_CHOICE', 'To maintain high retention rates among commercial data subscribers, what practice should An Officer establish?', 'Client Management', 1.00),
(153, 2, 71, 'SINGLE_CHOICE', 'An internal department wants to share vehicle safety inspection records with an international research group. The Officer finds no formal Data Sharing Agreement (DSA) is on file. What is the correct protocol?', 'Data Governance', 1.00),
(154, 2, 72, 'SINGLE_CHOICE', 'What is the role of An Officer when an audit reveals that an internal system user is downloading unusually high volumes of owner records?', 'Data Governance', 1.00),
(155, 2, 73, 'SINGLE_CHOICE', 'An Officer is writing an evaluation brief on how Ghana''s National E- Mobility Policy impacts future vehicle registration trends. What analytical framework should they apply?', 'Climate Policy Analysis', 1.00),
(156, 2, 74, 'SINGLE_CHOICE', 'When evaluating an international treaty on transport carbon reductions, what must An Officer analyze regarding DVLA data operations?', 'Climate Policy Analysis', 1.00),
(157, 2, 75, 'SINGLE_CHOICE', 'A data model tracking urban electric bus operations reveals a severe drop in battery efficiency during peak operational hours. What action should the Officer prioritize?', 'Sustainable Transport Planning', 1.00),
(158, 2, 76, 'SINGLE_CHOICE', 'How should An Officer design an evaluation plan for a newly introduced low-emission vehicle transit lane?', 'Sustainable Transport Planning', 1.00),
(159, 2, 77, 'SINGLE_CHOICE', 'The authority is updating its vehicle classification framework to include hybrid, plug-in hybrid (PHEV), and battery electric vehicles (BEVs). What structural task must the Officer manage?', 'EV Ecosystem Knowledge', 1.00),
(160, 2, 78, 'SINGLE_CHOICE', 'When analyzing charging infrastructure data to evaluate EV readiness, what metric should An Officer look at?', 'EV Ecosystem Knowledge', 1.00),
(161, 2, 79, 'SINGLE_CHOICE', 'An Officer is compiling the annual National Vehicle Fleet Carbon Emissions Report. They find that three regional offices have failed to submit their exhaust smoke testing metrics. What is the correct step?', 'Carbon Emissions Reporting', 1.00),
(162, 2, 80, 'SINGLE_CHOICE', 'Which metric provides An Officer with the best insight into the real- world impact of vehicle emissions testing programs?', 'Carbon Emissions Reporting', 1.00),
(163, 2, 81, 'SINGLE_CHOICE', 'An Environmental Impact Assessment (EIA) draft for a new regional DVLA mega-center shows that construction will impact local groundwater drainage paths. How should the Officer handle this?', 'Environmental Impact Assessment', 1.00),
(164, 2, 82, 'SINGLE_CHOICE', 'What is the key responsibility of An Officer when reviewing the environmental compliance profile of a third-party vehicle testing supplier?', 'Environmental Impact Assessment', 1.00)
