INSERT INTO `AnswerOption` (`id`, `questionId`, `order`, `text`, `isCorrect`) VALUES
(329, 83, 1, 'Approve the proposal immediately to prevent any project launch delays.', 0),
(330, 83, 2, 'Refine the scope section by mapping out specific, high-priority urban and rural testing centers based on target metrics.', 1),
(331, 83, 3, 'Delete the geographical section completely and focus only on software budgets.', 0),
(332, 83, 4, 'Ask the junior staff to rewrite the entire study background narrative from memory.', 0),
(333, 84, 1, 'Keeping project schedules vague to allow for execution flexibility.', 0),
(334, 84, 2, 'Aligning literature reviews, research methodologies, and budget frameworks directly with specific operational needs.', 1),
(335, 84, 3, 'Relying strictly on older, historical transport data to save design time.', 0),
(336, 84, 4, 'Avoiding stakeholder input during the early design phases of the proposal.', 0),
(337, 85, 1, 'Keep the leading questions to ensure the department receives positive reviews.', 0),
(338, 85, 2, 'Rewrite the questions into a neutral, balanced format to get honest, accurate data.', 1),
(339, 85, 3, 'Delete the customer feedback section entirely from the research project.', 0),
(340, 85, 4, 'Launch the survey without changes, but filter out negative responses later.', 0),
(341, 86, 1, 'A highly descriptive open-text field where users can write long comments.', 0),
(342, 86, 2, 'A structured, clearly anchored Likert scale or numerical duration bracket.', 1),
(343, 86, 3, 'An uncaptioned color scale without any written instructions.', 0),
(344, 86, 4, 'A simple yes/no question regarding whether the user felt frustrated.', 0),
(345, 87, 1, 'A standard convenience sample pulling records from the largest central office.', 0),
(346, 87, 2, 'Stratified random sampling using regional registration volumes as sorting tiers.', 1),
(347, 87, 3, 'A random selection from the first fifty vehicles that enter the facility on a single Monday.', 0),
(348, 87, 4, 'Purposive sampling focused only on premium luxury fleet operations.', 0),
(349, 88, 1, 'Distribute alternative surveys to arbitrary bystanders outside the target group.0', 0),
(350, 88, 2, 'Evaluate the non-response pattern, implement fallback rules, and document any bias.', 1),
(351, 88, 3, 'Fabricate baseline responses for missing entries to keep the sample size balanced.', 0),
(352, 88, 4, 'Cancel the sampling plan and switch to an unscientific guessing model.', 0),
(353, 89, 1, 'Order the team to switch to unformatted paper notes without notifying management.', 0),
(354, 89, 2, 'Stop uploads from the affected devices, check code formats, fix errors, and re-upload.', 1),
(355, 89, 3, 'Delete all data collected by those field workers over the entire week.', 0),
(356, 89, 4, 'Ignore the error logs and try to fix the files manually after the project concludes.', 0),
(357, 90, 1, 'Relying entirely on memory for the first three days and typing it up later.', 0),
(358, 90, 2, 'Using mobile data capture forms with built-in validation checks and field limits.', 1),
(359, 90, 3, 'Permitting field workers to skip data fields whenever they are in a rush.', 0),
(360, 90, 4, 'Writing all field data on unindexed index cards without dates or times.', 0),
(361, 91, 1, 'Provide the raw data files immediately to build institutional goodwill.', 0),
(362, 91, 2, 'Strip all personally identifiable information (PII) from the data export to protect privacy rules.', 1),
(363, 91, 3, 'Charge the institute an informal data access fee and share the raw files.', 0),
