INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(165, 3, 1, 'SINGLE_CHOICE', 'A research proposal development cycle is lagging because the internal data team and field logistics team cannot agree on timelines. What should the Manager do FIRST?', 'Research Proposal Development', 1.00),
(166, 3, 2, 'SINGLE_CHOICE', 'Why is proactive managerial oversight critical during the development of an institutional research proposal?', 'Research Proposal Development', 1.00),
(167, 3, 3, 'SINGLE_CHOICE', 'A newly launched customer service survey shows a high abandonment rate within the first three days of digital deployment. What is the Manager''s correct initial response?', 'Survey Design', 1.00),
(168, 3, 4, 'SINGLE_CHOICE', 'How should a Manager ensure the operational validity of a survey instrument before it is deployed to all 16 regions of Ghana?', 'Survey Design', 1.00),
(169, 3, 5, 'SINGLE_CHOICE', 'An external audit shows that a completed regional survey applied a non-probability convenience sampling model instead of the randomized approach required by the project brief. How should the Manager handle this?', 'Sampling Techniques', 1.00),
(170, 3, 6, 'SINGLE_CHOICE', 'When managing sample allocations across multiple districts with highly unequal driver populations, what is a Manager''s primary responsibility?', 'Sampling Techniques', 1.00),
(171, 3, 7, 'SINGLE_CHOICE', 'A field data collection team reports they cannot access a selected transport terminal due to local union resistance. What should management do FIRST?', 'Field Data Collection', 1.00),
(172, 3, 8, 'SINGLE_CHOICE', 'How should a Manager monitor the quality of data being captured by field teams in real-time?', 'Field Data Collection', 1.00),
(173, 3, 9, 'SINGLE_CHOICE', 'A Manager discovers that a junior researcher has stored a master file containing unencrypted driver phone numbers and medical logs on an unsecure public cloud link. What is the Manager''s immediate action?', 'Research Ethics', 1.00),
(174, 3, 10, 'SINGLE_CHOICE', 'Why must a Manager establish a formal research review protocol within the department?', 'Research Ethics', 1.00),
(175, 3, 11, 'SINGLE_CHOICE', 'An analysis team reports that an outdated software license is causing severe delays when running advanced multi-variable models in STATA. How should the Manager respond?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(176, 3, 12, 'SINGLE_CHOICE', 'When evaluating a statistical output report from a junior analyst, what should a Manager look for to verify model reliability?', 'Use of Data Analysis Tools (STATA/SPSS etc.)', 1.00),
(177, 3, 13, 'SINGLE_CHOICE', 'A senior management team finds a quarterly trend report too complex and difficult to interpret due to cluttered charts. What directive should the Manager issue?', 'Data Visualization', 1.00),
(178, 3, 14, 'SINGLE_CHOICE', 'What is a Manager''s primary focus when designing an interactive operational data dashboard for district offices?', 'Data Visualization', 1.00),
(179, 3, 15, 'SINGLE_CHOICE', 'A predictive model used to estimate future vehicle license plate revenues displays high volatility and wide margins of error. What management action is required?', 'Predictive Analytics', 1.00),
(180, 3, 16, 'SINGLE_CHOICE', 'Why is it important for a Manager to understand the concepts of "overfitting" and "underfitting" in predictive models?', 'Predictive Analytics', 1.00),
(181, 3, 17, 'SINGLE_CHOICE', 'A team presents a multiple linear regression model that purports to prove that a new office layout caused a surge in licensing volume, but the model lacks control variables. What should the Manager do?', 'Regression Analysis', 1.00),
(182, 3, 18, 'SINGLE_CHOICE', 'What does a Manager look at to determine if individual independent variables in an executive regression model are statistically meaningful?', 'Regression Analysis', 1.00),
(183, 3, 19, 'SINGLE_CHOICE', 'A database migration project experiences data loss, resulting in broken links between driver profiles and vehicle records. What should the Manager do FIRST?', 'Database Management', 1.00),
(184, 3, 20, 'SINGLE_CHOICE', 'When managing database infrastructure for the RBDI department, what security design should a Manager enforce?', 'Database Management', 1.00),
(185, 3, 21, 'SINGLE_CHOICE', 'A critical data-sharing partnership with corporate transport operators is stalling due to a complete breakdown in communications. What management step is required FIRST?', 'Stakeholder Engagement', 1.00),
(186, 3, 22, 'SINGLE_CHOICE', 'How should a Manager ensure long-term stakeholder buy-in for an innovative service model update?', 'Stakeholder Engagement', 1.00),
(187, 3, 23, 'SINGLE_CHOICE', 'A comprehensive grant proposal for a sustainable transport initiative fails to win funding due to a poorly structured risk mitigation framework. How should the Manager address this?', 'Fundable Proposal Development', 1.00),
(188, 3, 24, 'SINGLE_CHOICE', 'What is a Manager''s primary responsibility when coordinating the budget architecture of a commercial business proposal?', 'Fundable Proposal Development', 1.00),
(189, 3, 25, 'SINGLE_CHOICE', 'During formal contract negotiations, a private technology partner demands a larger share of transaction fees than authorized by the DVLA board guidelines. How should the Manager respond?', 'Partnership Negotiation', 1.00),
(190, 3, 26, 'SINGLE_CHOICE', 'What critical management check must be executed before a partnership contract is passed to the Deputy Director for final signature?', 'Partnership Negotiation', 1.00),
(191, 3, 27, 'SINGLE_CHOICE', 'A new market survey report shows conflicting consumer demand patterns for digital vehicle licensing upgrades. How should the Manager proceed?', 'Market Research', 1.00),
(192, 3, 28, 'SINGLE_CHOICE', 'How should a Manager use market research insights to position a new value-added fleet analysis product?', 'Market Research', 1.00),
(193, 3, 29, 'SINGLE_CHOICE', 'A newly deployed digital advertising platform on DVLA kiosks is generating 50% less revenue than projected in the quarterly business plan. What management action is required?', 'Revenue Generation Strategies', 1.00),
(194, 3, 30, 'SINGLE_CHOICE', 'What key metric must a Manager present to executive leadership to justify the expansion of a commercial service line?', 'Revenue Generation Strategies', 1.00),
(195, 3, 31, 'SINGLE_CHOICE', 'A critical competitor intelligence report indicates that external software platforms are starting to replicate DVLA data features. What strategy should the Manager prioritize?', 'Business Intelligence', 1.00),
(196, 3, 32, 'SINGLE_CHOICE', 'How should a Manager build institutional value using corporate business intelligence tools?', 'Business Intelligence', 1.00),
(197, 3, 33, 'SINGLE_CHOICE', 'A major system rollout milestone is threatened by a severe bottleneck in the quality assurance testing phase. What should the Manager do FIRST?', 'Project Scheduling', 1.00),
(198, 3, 34, 'SINGLE_CHOICE', 'In project schedule governance, what is the primary objective of a Manager tracking the "Critical Path"?', 'Project Scheduling', 1.00),
(199, 3, 35, 'SINGLE_CHOICE', 'A monthly project financial tracking report reveals an unexpected 20% budget overrun in infrastructure installation lines. What management action is required?', 'Budget Management', 1.00),
(200, 3, 36, 'SINGLE_CHOICE', 'When using Earned Value Management (EVM) frameworks, what does a Schedule Performance Index (SPI) of 0.82 mean to a Manager?', 'Budget Management', 1.00),
(201, 3, 37, 'SINGLE_CHOICE', 'An active risk event occurs: a key third-party API provider experiences a major system crash, halting validation tasks. What is the Manager''s correct initial response?', 'Risk Management', 1.00),
(202, 3, 38, 'SINGLE_CHOICE', 'How should a Manager foster risk awareness within a project team environment?', 'Risk Management', 1.00),
(203, 3, 39, 'SINGLE_CHOICE', 'A mid-term M&E evaluation report shows that an automated driving license upgrade system has failed to meet its target adoption rate by 50%. How should the Manager respond?', 'Monitoring and Evaluation', 1.00),
(204, 3, 40, 'SINGLE_CHOICE', 'When developing an institutional M&E framework, what design criteria must a Manager enforce for all KPIs?', 'Monitoring and Evaluation', 1.00),
(205, 3, 41, 'SINGLE_CHOICE', 'Interdepartmental friction between the RBDI team and the core IT division is causing critical delays in rolling out a data product. What is the Manager''s correct step?', 'Team Coordination', 1.00),
(206, 3, 42, 'SINGLE_CHOICE', 'To ensure balanced workload distribution across a 10-member research project team, what tool or practice should a Manager utilize?', 'Team Coordination', 1.00),
(207, 3, 43, 'SINGLE_CHOICE', 'A corporate scenario analysis exercise reveals a potential future risk where private autonomous fleets disrupt traditional vehicle registration lines. What management action should be taken?', 'Scenario Planning', 1.00),
(208, 3, 44, 'SINGLE_CHOICE', 'How does a Manager validate the quality and strategic utility of a completed scenario planning document?', 'Scenario Planning', 1.00),
(209, 3, 45, 'SINGLE_CHOICE', 'A user-experience testing phase reveals that elderly drivers find the new digital license renewal kiosk interface frustrating and hard to navigate. How should the Manager respond?', 'Design Thinking', 1.00),
(210, 3, 46, 'SINGLE_CHOICE', 'What is a Manager''s primary responsibility during the "Prototype" phase of a design thinking service innovation track?', 'Design Thinking', 1.00),
(211, 3, 47, 'SINGLE_CHOICE', 'A statistical trend analysis indicates a clear, accelerating decline in individual driver license applications among youth over three consecutive years. What strategic directive should the Manager issue?', 'Trend Analysis', 1.00),
(212, 3, 48, 'SINGLE_CHOICE', 'Why is structural trend analysis vital for a Manager overseeing capital innovation investments within the DVLA?', 'Trend Analysis', 1.00),
(213, 3, 49, 'SINGLE_CHOICE', 'During the deployment of an enterprise data management system, a severe system integration bug stops real-time sync with regional office nodes. What should the Manager do FIRST?', 'Digital Transformation Planning', 1.00),
(214, 3, 50, 'SINGLE_CHOICE', 'How should a Manager balance the introduction of automated digital transformation systems with institutional operational continuity?', 'Digital Transformation Planning', 1.00),
(215, 3, 51, 'SINGLE_CHOICE', 'A comprehensive audit shows that a newly launched digital workflow is facing silent sabotage from middle managers who bypass it using offline methods. What is the Manager''s correct step?', 'Change Management', 1.00),
(216, 3, 52, 'SINGLE_CHOICE', 'In John Kotter''s 8-Step Change Model, what management action should a Manager take to lock in a new process update?', 'Change Management', 1.00),
(217, 3, 53, 'SINGLE_CHOICE', 'A high-priority technical research report on vehicle safety features lacks a clear link between its statistical models and policy recommendations. What should the Manager direct?', 'Technical Report Writing', 1.00),
(218, 3, 54, 'SINGLE_CHOICE', 'How does a Manager ensure the technical integrity of all research publications issued by their department?', 'Technical Report Writing', 1.00),
(219, 3, 55, 'SINGLE_CHOICE', 'A draft institutional document contains several inconsistent data metrics across different chapters due to poor team coordination. What management step is required?', 'Editing and Proofreading', 1.00),
(220, 3, 56, 'SINGLE_CHOICE', 'What primary quality threshold must a Manager enforce when proofreading an executive policy brief?', 'Editing and Proofreading', 1.00),
(221, 3, 57, 'SINGLE_CHOICE', 'The department is experiencing high operational knowledge loss when senior researchers resign or retire. What strategic fix should the Manager deploy?', 'Knowledge Sharing', 1.00),
(222, 3, 58, 'SINGLE_CHOICE', 'How should a Manager build a proactive knowledge sharing culture within a multidisciplinary research division?', 'Knowledge Sharing', 1.00),
(223, 3, 59, 'SINGLE_CHOICE', 'A presentation deck built by a team for a ministerial budget review is visually cluttered, text-heavy, and over time budget limits. What management directive is required?', 'Presentation Development', 1.00),
(224, 3, 60, 'SINGLE_CHOICE', 'What design parameter should a Manager enforce to guarantee that an administrative presentation looks professional to external institutional investors?', 'Presentation Development', 1.00),
(225, 3, 61, 'SINGLE_CHOICE', 'A departmental audit reveals that vital project source data from historical driver behavior studies is completely missing from the central drive. What strategy should the Manager implement?', 'Documentation Management', 1.00),
(226, 3, 62, 'SINGLE_CHOICE', 'Why is an automated document version control infrastructure vital for a Manager overseeing large-scale policy drafting groups?', 'Documentation Management', 1.00),
(227, 3, 63, 'SINGLE_CHOICE', 'A proposed data monetization deal with an international research firm is flagged by legal counsel due to ambiguous data sovereign boundaries. How should the Manager respond?', 'Data Monetization', 1.00),
(228, 3, 64, 'SINGLE_CHOICE', 'What methodology should a Manager apply to measure the true economic value of an internal database asset considered for commercial release?', 'Data Monetization', 1.00),
(229, 3, 65, 'SINGLE_CHOICE', 'A major commercial subscriber threatens to cancel their subscription because the DVLA business intelligence API experiences frequent downtime during peak business hours. What is the Manager''s correct step?', 'Business Intelligence Services', 1.00),
(230, 3, 66, 'SINGLE_CHOICE', 'How should a Manager optimize the product design of a commercial business intelligence catalog for vehicle importers?', 'Business Intelligence Services', 1.00),
(231, 3, 67, 'SINGLE_CHOICE', 'The finance division reports that the current fee structure for custom commercial data sets is failing to recover developer overhead costs. How should the Manager respond?', 'Service Pricing', 1.00),
(232, 3, 68, 'SINGLE_CHOICE', 'When managing the pricing architecture of public data services, how should a Manager balance commercial returns with public-good mandates?', 'Service Pricing', 1.00),
(233, 3, 69, 'SINGLE_CHOICE', 'An internal audit reveals that three corporate data accounts have been accessing premium validation portals despite having overdue balances. What management action is required?', 'Client Management', 1.00),
(234, 3, 70, 'SINGLE_CHOICE', 'What practice should a Manager establish to handle systemic client onboarding issues for new data subscribers?', 'Client Management', 1.00),
(235, 3, 71, 'SINGLE_CHOICE', 'A data compliance audit identifies several instances where unauthorized internal staff accessed sensitive customer registration logs. How should the Manager address this breakdown?', 'Data Governance', 1.00),
(236, 3, 72, 'SINGLE_CHOICE', 'What is a Manager''s primary operational focus during an enterprise data governance alignment initiative?', 'Data Governance', 1.00),
(237, 3, 73, 'SINGLE_CHOICE', 'A management brief focused on integrating regional transport guidelines with national carbon targets is rejected by the director for lacking structural depth. What correction should the Manager execute?', 'Climate Policy Analysis', 1.00),
(238, 3, 74, 'SINGLE_CHOICE', 'How should a Manager ensure their team stays updated on evolving international green mobility standards?', 'Climate Policy Analysis', 1.00),
(239, 3, 75, 'SINGLE_CHOICE', 'A pilot program tracking public electric transit routes shows low vehicle utilization rates across three major metropolitan corridors. How should the Manager respond?', 'Sustainable Transport Planning', 1.00),
(240, 3, 76, 'SINGLE_CHOICE', 'What is a Manager''s primary responsibility when coordinating the data metrics for a sustainable urban transport masterplan?', 'Sustainable Transport Planning', 1.00),
(241, 3, 77, 'SINGLE_CHOICE', 'The technical inspection division is rejecting electric commercial vehicles because the standard testing bay layout only supports internal combustion emission checks. How should the Manager resolve this?', 'EV Ecosystem Knowledge', 1.00),
(242, 3, 78, 'SINGLE_CHOICE', 'When managing data collection structures for national electric vehicle tracking, what data classification should a Manager enforce?', 'EV Ecosystem Knowledge', 1.00),
(243, 3, 79, 'SINGLE_CHOICE', 'The Environmental Protection Agency flags the DVLA''s vehicle carbon emissions dataset for containing severe data gaps in heavy commercial vehicle columns. How should the Manager respond?', 'Carbon Emissions Reporting', 1.00),
(244, 3, 80, 'SINGLE_CHOICE', 'How should a Manager evaluate the operational efficacy of a city- wide vehicle emissions screening framework?', 'Carbon Emissions Reporting', 1.00),
(245, 3, 81, 'SINGLE_CHOICE', 'A third-party audit shows that a new regional vehicle testing center project is operating without a valid Environmental Impact Assessment (EIA) clearance certificate. What is the Manager''s correct immediate action?', 'Environmental Impact Assessment', 1.00),
(246, 3, 82, 'SINGLE_CHOICE', 'What is a Manager''s primary focus when reviewing the environmental sustainability footprint of the authority''s administrative centers?', 'Environmental Impact Assessment', 1.00)
