INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(329, 5, 1, 'SINGLE_CHOICE', 'An Assistant HR Officer at DVLA is updating a job description for a Frontline Licensing Officer. The current description lists "process vehicle registration applications" as the only duty. The Officer observes that incumbents also spend 40% of their time answering public inquiries by phone and resolving data mismatches with the central system. What should the Officer do first?', '1.1 Job Analysis & Role Profiling', 1.00),
(330, 5, 2, 'SINGLE_CHOICE', 'A hiring manager at DVLA''s Northern Regional office requests a job description for a new "Enforcement Assistant" role. The manager provides a list of 20 duties, including "assist with vehicle inspections," "manage office supplies inventory," and "schedule staff meetings." The Assistant HR Officer notes that some duties appear administrative while others are enforcement related. What is the most appropriate action?', '1.1 Job Analysis & Role Profiling', 1.00),
(331, 5, 3, 'SINGLE_CHOICE', 'An Assistant Officer is reviewing a job description for a Regional Licensing Manager that was last updated eight years ago. The description includes "supervise 5 staff" but the current incumbent supervises 12 staff across three locations. The manager says the description should not be changed because "the core functions are the same." What is the best response?', '1.1 Job Analysis & Role Profiling', 1.00),
(332, 5, 4, 'SINGLE_CHOICE', 'A job analysis for a Data Verification Officer role reveals that successful incumbents share one common trait: they previously worked in customer service before joining DVLA. The hiring manager wants to add "prior customer service experience" as a mandatory requirement. What is the most appropriate response?', '1.1 Job Analysis & Role Profiling', 1.00),
(333, 5, 5, 'SINGLE_CHOICE', 'An Assistant Officer is asked to create a job description for a role that does not yet exist: "Digital Transformation Coordinator." No incumbents are available to interview. Which method is most appropriate for identifying the duties and qualifications for this role?', '1.1 Job Analysis & Role Profiling', 1.00),
(334, 5, 6, 'SINGLE_CHOICE', 'An Assistant HR Officer at DVLA''s Accra headquarters is building a Boolean search string to find a Database Administrator who knows Oracle or SQL Server but has no MySQL experience. The Officer writes: Oracle OR SQL Server NOT MySQL. The search returns candidates who have Oracle experience but also includes candidates who have SQL Server experience. However, some results include candidates who have MySQL experience if they also have Oracle. What is the error in the search string?', '1.2 Sourcing Strategies', 1.00),
(335, 5, 7, 'SINGLE_CHOICE', 'An Assistant Officer is tasked with sourcing candidates for a Vehicle Inspector role in the Volta Region. The Officer posts the vacancy on the DVLA website and receives zero applications after two weeks. The Officer then posts the same vacancy on a national job board and receives 200 applications, but only 5 are from candidates willing to work in the Volta Region. What is the most likely explanation for this outcome?', '1.2 Sourcing Strategies', 1.00),
(336, 5, 8, 'SINGLE_CHOICE', 'An Assistant Officer discovers a promising candidate profile on LinkedIn for a specialized engineering role at DVLA. The candidate has not worked for 18 months, with the gap showing as "personal sabbatical." The hiring manager tells the Officer to "reject anyone with unexplained gaps; they are probably unemployable." What should the Assistant Officer do?', '1.2 Sourcing Strategies', 1.00),
(337, 5, 9, 'SINGLE_CHOICE', 'An Assistant Officer sends LinkedIn InMail messages to 50 passive candidates for a technical role using a template that reads: "DVLA has an urgent vacancy. Please send your CV to the address below if interested." Only three candidates respond. A Senior Officer suggests that the low response rate is due to the message content, not the candidate pool. What is the most likely specific weakness in the message?', '1.2 Sourcing Strategies', 1.00),
(338, 5, 10, 'SINGLE_CHOICE', 'An Assistant Officer is building a talent pipeline for future Driver Testing Officer vacancies across all 16 regions. The Officer has a limited budget of GHS 5,000 for sourcing activities. Which combination of channels is most likely to yield qualified candidates within this budget?', '1.2 Sourcing Strategies', 1.00),
(339, 5, 11, 'SINGLE_CHOICE', 'An Assistant HR Officer is observing an interview panel for a Customer Service Officer role. The panel chair asks each candidate different questions based on their CV . One candidate is asked about their experience with complaints handling. Another candidate is asked about their typing speed. The Officer notes that the panel is struggling to compare candidates after the interviews. What is the most likely cause of this difficulty?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(340, 5, 12, 'SINGLE_CHOICE', 'An Assistant Officer is evaluating a candidate''s response to a behavioral interview question. The candidate says: "In my previous role, a customer was angry about a delayed registration. I listened to their concern, apologized, and escalated the issue to my supervisor. The customer left satisfied." The candidate''s response lacks which component of the STAR method?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(341, 5, 13, 'SINGLE_CHOICE', 'An Assistant Officer is training hiring managers on how to avoid common interview biases. The Officer presents a scenario: a candidate arrives late due to traffic, apologizes, and then performs well throughout the interview. After the interview, the panel chair says: "The late arrival shows poor planning. I cannot recommend this candidate." What bias is the panel chair most likely demonstrating?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(342, 5, 14, 'SINGLE_CHOICE', 'A candidate for a community relations role at DVLA''s Northern Regional office asks: "May I answer the next question in Dagbani? I can express myself more clearly in my local language when explaining complex community engagement scenarios." The interview panel is fluent in English only. The role requires regular communication with local chiefs and community members in predominantly Dagbani-speaking areas. What should the Assistant Officer advise the panel?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(343, 5, 15, 'SINGLE_CHOICE', 'An Assistant Officer is preparing a structured interview guide for a Data Entry Clerk role. The Officer writes a question: "How do you ensure accuracy when entering large volumes of data?" The hiring manager suggests changing it to: "Describe a specific time when you discovered an error in your data entry. What caused the error, how did you correct it, and what did you do to prevent similar errors in the future?" Which statement best describes the difference between these two questions?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(344, 5, 16, 'SINGLE_CHOICE', 'An Assistant HR Officer is reviewing DVLA''s "Careers" webpage on a mobile phone. The page takes 45 seconds to load, requires zooming to read text, and the " Apply Now" button is hidden below a large header image. The Officer checks analytics and finds that 70% of visitors leave the page without applying. What is the most cost-effective first improvement?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(345, 5, 17, 'SINGLE_CHOICE', 'An HR Officer sends automated acknowledgment emails to candidates who submit applications. The current email reads: "Thank you for your application. We will contact you if you are selected." A candidate complains that they never heard back after three months. The Officer checks the recruitment system and finds the candidate was rejected in week two but never received notification. What is the most critical missing element from the acknowledgment email?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(346, 5, 18, 'SINGLE_CHOICE', 'An Assistant Officer is preparing interview logistics for a candidate who is traveling from a rural region to DVLA''s Accra headquarters. The candidate has never visited Accra before. Which action will have the most direct positive impact on the candidate''s experience before the interview?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(347, 5, 19, 'SINGLE_CHOICE', 'An Assistant Officer notices that multiple online reviews on Glassdoor complain that rejected applicants "never heard back after the final interview." One review states: "I spent two days on interviews, met with six people, and then complete silence." The Officer brings this to the attention of the Senior HR Officer. What is the most appropriate immediate action?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(348, 5, 20, 'SINGLE_CHOICE', 'An Assistant Officer is asked to send post-rejection feedback surveys to candidates who were not selected for a Vehicle Inspector role. The hiring manager argues that "rejected candidates are not our concern; we should focus on the ones we hired." What is the Assistant Officer''s best response?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(349, 5, 21, 'SINGLE_CHOICE', 'An Assistant HR Officer is administering a general cognitive ability test to candidates for a Data Verification Officer role. The test instructions state that candidates have 30 minutes to complete 50 questions. Five minutes before the end, a candidate raises their hand and says: "I have a visual impairment that makes it difficult to read the screen quickly. I did not request an accommodation because I did not want to be treated differently." The candidate has answered only 20 questions. What is the most appropriate action?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(350, 5, 22, 'SINGLE_CHOICE', 'An Assistant Officer is explaining psychometric test results to a hiring manager. The test vendor''s report shows a "reliability coefficient ( ) of 0.92" for the cognitive ability test. The α hiring manager asks: "Does that mean the test is accurate?" What is the most accurate explanation of reliability?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(351, 5, 23, 'SINGLE_CHOICE', 'An Assistant Officer is setting up a personality assessment for internal candidates applying for a supervisory role. The test vendor provides the results in a report that categorizes candidates into "red, yellow, green" based on their fit with a "leadership profile." The Officer notices that the report does not provide any scientific validation data. What is the most appropriate action?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(352, 5, 24, 'SINGLE_CHOICE', 'An Assistant Officer is asked to select a personality assessment for frontline customer service roles. The Officer has three options: (1) a free online test with no validation data, (2) a proprietary test with validation data from a similar public sector agency, and (3) a well- researched Big Five assessment that has been validated in multiple contexts but is more expensive. Which selection is most defensible?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(353, 5, 25, 'SINGLE_CHOICE', 'An Assistant Officer is preparing a testing room for a psychometric assessment. The test is timed and requires concentration. The only available room has a large window facing a busy street with traffic noise. The Officer closes the window, but noise persists. What is the most appropriate action?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(354, 5, 26, 'SINGLE_CHOICE', 'An Assistant HR Officer is screening CVs for a Vehicle Inspector vacancy. The Officer notices that they consistently favor applicants who graduated from the same university they attended. When reviewing the last 20 CVs, the Officer shortlisted 8 applicants. All 8 are alumni of their alma mater, even though the university has only a 10% representation in the overall applicant pool. What type of bias is the Officer most likely demonstrating?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(355, 5, 27, 'SINGLE_CHOICE', 'An Assistant HR Officer is formatting a job advertisement for a Senior Licensing Officer role. The current draft reads: "The successful candidate will manage his team of enforcement officers. He will report to the Regional Director. He must be willing to travel extensively." Which single change would most improve the inclusivity of the advertisement?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(356, 5, 28, 'SINGLE_CHOICE', 'An Assistant Officer is setting up an interview for a candidate who uses a wheelchair. The interview is scheduled to take place in a meeting room on the third floor. The building has an elevator, but the candidate must navigate two heavy fire doors to reach the elevator. The officer assigned to meet the candidate at the entrance is not aware of the candidate''s mobility needs. What is the most appropriate action?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(357, 5, 29, 'SINGLE_CHOICE', 'An Assistant HR Officer is asked to review job descriptions for potential inclusive language barriers. One description for a Data Entry Clerk includes: "Must have a valid driver''s license and reliable personal vehicle." The role is entirely desk-based with no travel requirements. The hiring manager explains: "We want employees who are responsible and reliable. Having a car shows responsibility." What is the most appropriate action?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(358, 5, 30, 'SINGLE_CHOICE', 'An Assistant HR Officer is preparing a panel interview. The panel consists of three senior male managers from the enforcement division. The role is for a customer service officer. The Officer notes that the panel has no gender diversity and no representation from customer service backgrounds. The hiring manager says: "These are the only managers available. We need to fill the role quickly." What is the most appropriate action?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(359, 5, 31, 'SINGLE_CHOICE', 'An Assistant HR Officer is asked to conduct a Training Needs Analysis for frontline licensing officers. The department manager says: "Everyone needs customer service training. I have received three complaints this month, so the whole team must be trained." What should the Assistant Officer do first?', '2.1 Training Needs Analysis (TNA)', 1.00),
(360, 5, 32, 'SINGLE_CHOICE', 'An Assistant Officer is collecting TNA data and must choose a method. The Officer has a budget of GHS 2,000, a timeline of two weeks, and needs to gather input from 500 employees across 16 regions. Which method is most appropriate given these constraints?', '2.1 Training Needs Analysis (TNA)', 1.00),
(361, 5, 33, 'SINGLE_CHOICE', 'An Assistant Officer is reviewing a TNA report from the previous year. The report recommended a GHS 500,000 leadership development program. The program was implemented, but follow-up data shows no improvement in leadership effectiveness scores. The Officer notices that the TNA was based solely on interviews with senior managers, not with the target audience (mid-level supervisors). What is the most likely flaw in the original TNA?', '2.1 Training Needs Analysis (TNA)', 1.00),
(362, 5, 34, 'SINGLE_CHOICE', 'An Assistant Officer is asked to identify training needs for a new digital driver''s license system that will launch in six months. No employees currently have experience with the system. Which TNA approach is most appropriate for this situation?', '2.1 Training Needs Analysis (TNA)', 1.00),
(363, 5, 35, 'SINGLE_CHOICE', 'An Assistant Officer is analyzing TNA data. The data shows that 80% of employees in the Northern Region report low confidence in using the vehicle inspection database, while only 20% in the Southern Region report the same. The Northern Region manager argues that the solution is mandatory training for all Northern Region staff. The Southern Region manager argues that no training is needed. What is the most appropriate recommendation?', '2.1 Training Needs Analysis (TNA)', 1.00),
(364, 5, 36, 'SINGLE_CHOICE', 'An Assistant Officer is writing a learning objective for a customer service training. Which objective follows the SMART criteria correctly?', '2.2 Instructional Design & Curriculum Development', 1.00),
(365, 5, 37, 'SINGLE_CHOICE', 'An Assistant Officer is selecting training materials for a vehicle inspection course. Which source is most reliable and legally defensible?', '2.2 Instructional Design & Curriculum Development', 1.00),
(366, 5, 38, 'SINGLE_CHOICE', 'An Assistant Officer is designing a training session on a new software system. What is the purpose of a pilot test before full rollout?', '2.2 Instructional Design & Curriculum Development', 1.00),
(367, 5, 39, 'SINGLE_CHOICE', 'An Assistant Officer is reviewing a training curriculum that includes only lectures and written exams. What is the most significant limitation of this approach?', '2.2 Instructional Design & Curriculum Development', 1.00),
(368, 5, 40, 'SINGLE_CHOICE', 'An Assistant Officer is asked to develop a training program for new enforcement officers. Which sequence follows best practice for skill development?', '2.2 Instructional Design & Curriculum Development', 1.00),
(369, 5, 41, 'SINGLE_CHOICE', 'During a training session, a participant asks a question you cannot answer. What is the best professional response?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(370, 5, 42, 'SINGLE_CHOICE', 'One participant is dominating all discussions during a training session. What is the most appropriate facilitation technique?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(371, 5, 43, 'SINGLE_CHOICE', 'Which seating arrangement best supports group discussion and interaction in a training room?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(372, 5, 44, 'SINGLE_CHOICE', 'An Assistant Officer is preparing a training room. Which environmental factor most directly affects participant attention?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(373, 5, 45, 'SINGLE_CHOICE', 'A participant is visibly frustrated and disagrees with the training content. What is the facilitator''s best first step?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(374, 5, 46, 'SINGLE_CHOICE', 'An Assistant Officer is asked to upload a training video to the LMS. The video file is 2 GB. The LMS has a 500 MB file size limit. What is the most appropriate action?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(375, 5, 47, 'SINGLE_CHOICE', 'An Assistant Officer is setting up an e-learning course. The course includes a video, a quiz, and a downloadable job aid. Which should be the first element in the course?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(376, 5, 48, 'SINGLE_CHOICE', 'A learner reports they cannot access their e-learning course. The Assistant Officer checks and finds the learner has a valid account. What is the next troubleshooting step?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(377, 5, 49, 'SINGLE_CHOICE', 'An Assistant Officer is asked to choose between synchronous and asynchronous e-learning for a team of 50 staff. The team works different shifts. Which factor favors asynchronous learning?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(378, 5, 50, 'SINGLE_CHOICE', 'An Assistant Officer is asked to run a completion report for a mandatory safety course. Where should this data be found?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(379, 5, 51, 'SINGLE_CHOICE', 'According to Kirkpatrick''s model, what does Level 1 evaluation measure?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(380, 5, 52, 'SINGLE_CHOICE', 'An Assistant Officer is asked to evaluate a training program. Which is a Level 2 evaluation method?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(381, 5, 53, 'SINGLE_CHOICE', 'A participant rates a training session as "excellent" on the feedback form. According to Kirkpatrick, what does this tell you?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(382, 5, 54, 'SINGLE_CHOICE', 'An Assistant Officer is calculating training completion rates. Which Kirkpatrick level does this activity relate to?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(383, 5, 55, 'SINGLE_CHOICE', 'An Assistant Officer is asked to measure whether customer service training changed how staff interact with the public. Which Kirkpatrick level is this?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(384, 5, 56, 'SINGLE_CHOICE', 'What is the primary purpose of succession planning?', '2.6 Leadership Development & Succession Planning', 1.00),
(385, 5, 57, 'SINGLE_CHOICE', 'An Assistant Officer is asked to maintain a succession planning database. What data is most important to track?', '2.6 Leadership Development & Succession Planning', 1.00),
(386, 5, 58, 'SINGLE_CHOICE', 'What is a "9-box grid" used for in talent management?', '2.6 Leadership Development & Succession Planning', 1.00),
(387, 5, 59, 'SINGLE_CHOICE', 'An Assistant Officer is scheduling a leadership development workshop for first-line supervisors. Which topic is most appropriate for this audience?', '2.6 Leadership Development & Succession Planning', 1.00),
(388, 5, 60, 'SINGLE_CHOICE', 'What is an "Individual Development Plan" (IDP) in the context of leadership development?', '2.6 Leadership Development & Succession Planning', 1.00),
(389, 5, 61, 'SINGLE_CHOICE', 'What is the primary difference between coaching and mentoring?', '2.7 Coaching and Mentoring Program Design', 1.00),
(390, 5, 62, 'SINGLE_CHOICE', 'An Assistant Officer is asked to match mentors and mentees. Which matching factor is most likely to lead to a successful relationship?', '2.7 Coaching and Mentoring Program Design', 1.00),
(391, 5, 63, 'SINGLE_CHOICE', 'What is a "coaching agreement" or "contract"?', '2.7 Coaching and Mentoring Program Design', 1.00),
(392, 5, 64, 'SINGLE_CHOICE', 'An Assistant Officer is scheduling coaching sessions for new supervisors. What is the recommended minimum frequency for effective coaching?', '2.7 Coaching and Mentoring Program Design', 1.00),
(393, 5, 65, 'SINGLE_CHOICE', 'Which of the following is a coaching question designed to promote reflection?', '2.7 Coaching and Mentoring Program Design', 1.00)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

INSERT INTO `AnswerOption` (`id`, `questionId`, `order`, `text`, `isCorrect`) VALUES
(1313, 329, 1, 'Add "answer public inquiries by phone" and "resolve data mismatches" to the duties section of the job description.', 0),
(1314, 329, 2, 'Ask the manager to confirm whether the observed phone and data resolution tasks are expected duties or temporary workarounds.', 1),
(1315, 329, 3, 'Remove "process vehicle registration applications" because it is no longer the majority of the role.', 0),
(1316, 329, 4, 'Recommend reclassifying the role as a customer service position rather than a licensing officer role.', 0),
(1317, 330, 1, 'Create a single job description with all 20 duties as written by the manager.', 0),
(1318, 330, 2, 'Separate the duties into two distinct roles: Enforcement Assistant and Administrative Assistant.', 1),
(1319, 330, 3, 'Remove the administrative duties and focus only on enforcement-related tasks.', 0),
(1320, 330, 4, 'Keep all duties but add a note that administrative tasks are "as needed" only.', 0),
(1321, 331, 1, '"We should keep the description as is to maintain consistency with historical records."', 0),
(1322, 331, 2, '"The description should be updated to reflect the current span of control for accurate performance expectations and classification."', 1),
(1323, 331, 3, '"Only the Public Services Commission can approve changes to supervisory ratios in job descriptions."', 0),
(1324, 331, 4, '"We should remove the number of staff entirely from the job description to avoid future discrepancies."', 0),
(1325, 332, 1, 'Approve the mandatory requirement; the data is clear about what predicts success.', 0),
(1326, 332, 2, 'List prior customer service experience as preferred, not mandatory, to avoid excluding candidates with equivalent skills from other backgrounds.', 1),
(1327, 332, 3, 'Reject the requirement entirely because customer service experience is irrelevant to data verification.', 0),
(1328, 332, 4, 'Require a formal validation study before adding any experience-based requirement to the job description.', 0),
(1329, 333, 1, 'Interview current DVLA managers about what they believe the role should do.', 0),
(1330, 333, 2, 'Use a job description template from a private sector technology company and adapt it to DVLA.', 0),
(1331, 333, 3, 'Review job postings for similar roles from other transport regulatory authorities and synthesize key themes.', 1),
(1332, 333, 4, 'Defer creating the job description until someone is hired and can describe their own duties.', 0),
(1333, 334, 1, 'The OR operator should be replaced with AND to narrow the results.', 0),
(1334, 334, 2, 'The NOT operator should be placed before Oracle to exclude all database experience.', 0),
(1335, 334, 3, 'The search terms should be enclosed in parentheses to group the OR logic before applying NOT .', 1),
(1336, 334, 4, 'Quotation marks should be added around each term to make the search case-sensitive.', 0),
(1337, 335, 1, 'The Volta Region has a smaller population of qualified vehicle inspectors than other regions.', 0),
(1338, 335, 2, 'The job board attracts national applicants who are unwilling to relocate to rural areas.', 1),
(1339, 335, 3, 'The DVLA website is not properly configured to accept applications for regional roles.', 0),
(1340, 335, 4, 'The job posting on the DVLA website contained errors that discouraged applicants.', 0),
(1341, 336, 1, 'Reject the candidate as instructed and document the manager''s directive in the recruitment file.', 0),
(1342, 336, 2, 'Contact the candidate to ask for an explanation of the gap before making any decision.', 1),
(1343, 336, 3, 'Remove the candidate from consideration but do not document the reason to avoid creating a record.', 0),
(1344, 336, 4, 'Flag the candidate for the manager''s attention without providing any recommendation.', 0),
(1345, 337, 1, 'The message asks candidates to take an action (send CV) without first building interest or providing context about the role.', 1),
(1346, 337, 2, 'The message uses the word "urgent," which may imply that the role has high turnover or poor working conditions.', 0),
(1347, 337, 3, 'The message does not include a salary range, which passive candidates expect before responding.', 0),
(1348, 337, 4, 'The message was sent on a Monday morning when candidates are less likely to check LinkedIn.', 0),
(1349, 338, 1, 'Paid advertisements on three national job boards and billboards in Accra.', 0),
(1350, 338, 2, 'Free postings on the DVLA website, partnerships with regional driving schools, and targeted social media posts in local community groups.', 1),
(1351, 338, 3, 'An external recruitment agency specializing in driver testing roles nationwide.', 0),
(1352, 338, 4, 'A career fair at the University of Ghana and sponsored LinkedIn InMail campaigns.', 0),
(1353, 339, 1, 'The panel members have different levels of experience in customer service roles.', 0),
(1354, 339, 2, 'The interview lacks structure; asking different questions prevents valid comparison of candidates.', 1),
(1355, 339, 3, 'The candidates had different levels of preparation before the interview.', 0),
(1356, 339, 4, 'The panel chair did not provide enough time for discussion after each interview.', 0),
(1357, 340, 1, 'Situation - the candidate described the context.', 0),
(1358, 340, 2, 'Task - the candidate implied what needed to be done.', 0),
(1359, 340, 3, 'Action - the candidate described what they did.', 0),
(1360, 340, 4, 'Result - the candidate did not specify a measurable outcome or what they learned.', 1),
(1361, 341, 1, 'Halo effect - allowing one positive trait to influence all ratings.', 0),
(1362, 341, 2, 'Recency bias - focusing only on the most recent event.', 0),
(1363, 341, 3, 'Horns effect - allowing one negative trait (tardiness) to overshadow the candidate''s otherwise strong performance.', 1),
(1364, 341, 4, 'Affinity bias - favoring candidates who share similar characteristics with the panel chair.', 0),
(1365, 342, 1, 'Deny the request; all interviews must be conducted in English to ensure consistency across candidates.', 0),
(1366, 342, 2, 'Deny the request but offer to provide a written translation of the candidate''s answers after the interview.', 0),
(1367, 342, 3, 'Grant the request and have a staff member who speaks Dagbani co-facilitate or interpret for the panel.', 1),
(1368, 342, 4, 'Grant the request but inform the candidate that their answers will be rated lower because the panel cannot understand them directly.', 0),
(1369, 343, 1, 'The first question is a behavioral question; the second is a hypothetical question.', 0),
(1370, 343, 2, 'The first question is a hypothetical question; the second is a behavioral question.', 1),
(1371, 343, 3, 'Both questions are behavioral; they ask about past experiences.', 0),
(1372, 343, 4, 'Both questions are hypothetical; they ask about future intentions.', 0),
(1373, 344, 1, 'Reduce the size of the header image and simplify the page layout for mobile viewing.', 1),
(1374, 344, 2, 'Remove the online application entirely and direct all candidates to submit paper applications.', 0),
(1375, 344, 3, 'Add a pop-up message asking visitors to use a desktop computer for the best experience.', 0),
(1376, 344, 4, 'Increase the font size on the page without changing the layout or image sizes.', 0),
(1377, 345, 1, 'The name and phone number of the hiring manager for follow-up.', 0),
(1378, 345, 2, 'A statement that only shortlisted candidates will be contacted.', 0),
(1379, 345, 3, 'A clear timeline of the recruitment process and a commitment to notify all candidates of their status.', 1),
(1380, 345, 4, 'A request for the candidate to provide references immediately.', 0),
(1381, 346, 1, 'Send the candidate a list of recommended hotels in Accra at various price points.', 0),
(1382, 346, 2, 'Provide clear written directions, parking information, security gate protocols, and a contact person''s phone number.', 1),
(1383, 346, 3, 'Offer to reimburse the candidate for their travel expenses after the interview.', 0),
(1384, 346, 4, 'Schedule the interview for 8:00 AM so the candidate can leave early for their return journey.', 0),
(1385, 347, 1, 'Delete DVLA''s Glassdoor profile to prevent further negative reviews.', 0),
(1386, 347, 2, 'Post a public response apologizing for the experience and stating that DVLA is reviewing its candidate communication process.', 1),
(1387, 347, 3, 'Ignore the reviews; candidates who complain are usually not a good fit anyway.', 0),
(1388, 347, 4, 'Send a message to each reviewer individually asking them to remove their negative comments.', 0),
(1389, 348, 1, '"You are correct; I will cancel the survey to save time and resources."', 0),
(1390, 348, 2, '"Feedback surveys help us identify problems in our recruitment process that may also affect candidates we want to attract in the future."', 1),
(1391, 348, 3, '"The Public Services Commission requires us to survey all rejected candidates by law."', 0),
(1392, 348, 4, '"I will send the survey only to candidates who reached the final interview stage, not all rejected candidates."', 0),
(1393, 349, 1, 'Allow the candidate to continue the test beyond the 30-minute limit to finish all 50 questions.', 0),
(1394, 349, 2, 'Score the test based only on the 20 questions answered, with no adjustment.', 0),
(1395, 349, 3, 'Document the situation and recommend that future testing include a standard accommodation notice for all candidates to request accommodations in advance.', 1),
(1396, 349, 4, 'Invalidate the candidate''s test and offer a retake with extra time as an accommodation, noting the need for advance requests in the future.', 0),
(1397, 350, 1, '" A reliability of 0.92 means the test predicts job performance with 92% accuracy."', 0),
(1398, 350, 2, '"Reliability measures consistency. A score of 0.92 means the test produces stable, repeatable results for the same individual under similar conditions."', 1),
(1399, 350, 3, '"Reliability measures how well candidates like the test. A score of 0.92 means 92% of candidates found it fair."', 0),
(1400, 350, 4, '"Reliability measures the cost of the test relative to its accuracy."', 0),
(1401, 351, 1, 'Use the report as provided; the vendor is a reputable company with many clients.', 0),
(1402, 351, 2, 'Request the vendor to provide documentation of the test''s reliability, validity, and any adverse impact data before using it for selection decisions.', 1),
(1403, 351, 3, 'Use the report but inform candidates that the results are for development only, not for selection.', 0),
(1404, 351, 4, 'Discard the personality assessment entirely and rely only on interviews.', 0),
(1405, 352, 1, 'The free online test; cost savings justify the risk.', 0),
(1406, 352, 2, 'The proprietary test with validation from a similar agency; it balances cost and validity.', 0),
(1407, 352, 3, 'The Big Five assessment; it has the strongest scientific backing and is defensible even if more expensive.', 1),
(1408, 352, 4, 'No personality assessment; personality is not relevant to customer service performance.', 0),
(1409, 353, 1, 'Proceed with the test; candidates should be able to concentrate despite noise.', 0),
(1410, 353, 2, 'Move the test to a quieter location, even if it means delaying the start time by 30 minutes.', 1),
(1411, 353, 3, 'Provide earplugs to all candidates and document the accommodation.', 0),
(1412, 353, 4, 'Add 5 minutes to the test time to compensate for the noise distraction.', 0),
(1413, 354, 1, 'Confirmation bias - seeking evidence that confirms existing beliefs.', 0),
(1414, 354, 2, 'Recency bias - favoring candidates who applied most recently.', 0),
(1415, 354, 3, 'Halo effect - allowing one positive trait to influence overall rating.', 0),
(1416, 354, 4, 'Affinity bias - favoring candidates who share similar background characteristics.', 1),
(1417, 355, 1, 'Add a statement: "Female candidates are encouraged to apply."', 0),
(1418, 355, 2, 'Change all instances of "he" and "his" to gender-neutral language such as "they" and "their" or restructure sentences.', 1),
(1419, 355, 3, 'Remove the travel requirement; it may discourage candidates with family responsibilities.', 0),
(1420, 355, 4, 'Add a photo of a diverse team to the advertisement.', 0),
(1421, 356, 1, 'Inform the candidate that the interview will be moved to the ground floor and ensure the officer meets them at the accessible entrance.', 1),
(1422, 356, 2, 'Proceed with the third-floor interview; the elevator is available, and the candidate can manage the doors.', 0),
(1423, 356, 3, 'Cancel the in-person interview and conduct it by phone instead.', 0),
(1424, 356, 4, 'Ask the candidate to bring someone to assist them through the building.', 0),
(1425, 357, 1, 'Keep the requirement; the manager''s rationale about responsibility is valid.', 0),
(1426, 357, 2, 'Remove the driver''s license and vehicle requirement because it is not job-related and may exclude qualified candidates without transportation.', 1),
(1427, 357, 3, 'Change the requirement to "must have reliable transportation" to be more inclusive.', 0),
(1428, 357, 4, 'Keep the requirement but add "or reliable transportation" as an alternative.', 0),
(1429, 358, 1, 'Proceed with the panel as assembled; any panel is better than delaying the hire.', 0),
(1430, 358, 2, 'Request that at least one woman and one person with customer service experience be added to the panel, even if it delays the interview by a few days.', 1),
(1431, 358, 3, 'Ask the three managers to complete unconscious bias training before the interviews.', 0),
(1432, 358, 4, 'Remove the panel entirely and conduct the interview by yourself.', 0),
(1433, 359, 1, 'Approve the training for the entire team immediately to address the manager''s concern.', 0),
(1434, 359, 2, 'Request specific data on which employees received complaints and under what circumstances before designing any training.', 1),
(1435, 359, 3, 'Recommend terminating the employees who received complaints instead of training.', 0),
(1436, 359, 4, 'Suggest that the manager handle complaints personally to avoid training costs.', 0),
(1437, 360, 1, 'One-on-one interviews with all 500 employees (would exceed budget and timeline).', 0),
(1438, 360, 2, 'A statistically valid sample survey distributed electronically, supplemented by focus groups in selected regions.', 1),
(1439, 360, 3, 'Observation of each employee for one full day (would require 500 days).', 0),
(1440, 360, 4, 'Relying solely on manager opinions to avoid data collection costs.', 0),
(1441, 361, 1, 'The budget was too low to implement an effective program.', 0),
(1442, 361, 2, 'The TNA did not include input from the actual training recipients, so the identified needs may not have reflected reality.', 1),
(1443, 361, 3, 'The training program was too short to produce measurable results.', 0),
(1444, 361, 4, 'The follow-up data was collected too soon after the training.', 0),
(1445, 362, 1, 'Observe employees performing their current duties to infer future needs.', 0),
(1446, 362, 2, 'Conduct a survey asking employees what training they think they will need.', 0),
(1447, 362, 3, 'Consult the system vendor''s training recommendations, review similar implementations in other agencies, and involve a small group of pilot users.', 1),
(1448, 362, 4, 'Defer all training until after the system launches and identify needs based on live performance gaps.', 0),
(1449, 363, 1, 'Train all Northern Region staff as requested, and exempt Southern Region staff.', 0),
(1450, 363, 2, 'Conduct a focused TNA in the Northern Region to determine the root cause (lack of training, system access issues, or other factors) before designing any training.', 1),
(1451, 363, 3, 'Train all employees nationwide to ensure consistency across regions.', 0),
(1452, 363, 4, 'Assume the Northern Region staff are less capable and recommend performance management instead of training.', 0),
(1453, 364, 1, 'Participants will understand customer service principles by end of day.', 0),
(1454, 364, 2, 'Participants will process a complaint call within 4 minutes using the DVLA script.', 1),
(1455, 364, 3, 'Participants will feel confident handling difficult customer situations.', 0),
(1456, 364, 4, 'Participants will attend the training and listen to all presentations.', 0),
(1457, 365, 1, 'A YouTube tutorial from an anonymous mechanic with 10,000 views.', 0),
(1458, 365, 2, 'A blog post written by a retired DVLA officer describing inspection tips.', 0),
(1459, 365, 3, 'The DVLA-approved inspection manual and manufacturer technical documentation.', 1),
(1460, 365, 4, 'A training video from a private driving school in another country.', 0),
(1461, 366, 1, 'To train the most senior employees first as a reward for their service.', 0),
(1462, 366, 2, 'To deliver training to a small group and gather feedback for refinement.', 1),
(1463, 366, 3, 'To test employees'' ability to learn the software without any instruction.', 0),
(1464, 366, 4, 'To create promotional materials showcasing the training program''s success.', 0),
(1465, 367, 1, 'Lectures are more expensive than other training delivery methods.', 0),
(1466, 367, 2, 'Written exams are difficult for employees with reading challenges.', 0),
(1467, 367, 3, 'Passive learning may not develop practical skills needed on the job.', 1),
(1468, 367, 4, 'Lectures require more preparation time than interactive methods.', 0),
(1469, 368, 1, 'Lecture, written exam, role-play, on-the-job observation.', 1),
(1470, 368, 2, 'On-the-job observation, lecture, written exam, role-play.', 0),
(1471, 368, 3, 'Role-play, on-the-job observation, lecture, written exam.', 0),
(1472, 368, 4, 'Written exam, role-play, on-the-job observation, lecture.', 0),
(1473, 369, 1, 'Guess an answer to avoid appearing unprepared in front of the group.', 0),
(1474, 369, 2, 'Ignore the question and move to the next topic on your agenda.', 0),
(1475, 369, 3, 'Acknowledge honestly, offer to research, and follow up after session.', 1),
(1476, 369, 4, 'Tell the participant they should have learned this before attending.', 0),
(1477, 370, 1, 'Allow the participant to dominate; they are engaged and interested.', 0),
(1478, 370, 2, 'Publicly embarrass the participant to discourage future interruptions.', 0),
(1479, 370, 3, 'Ask security to remove the participant from the session entirely.', 0),
(1480, 370, 4, 'Use turn-taking, direct questions to quieter participants, or breakout groups.', 1),
