INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(394, 6, 1, 'SINGLE_CHOICE', 'A Senior Officer is reviewing job descriptions across DVLA''s 16 regional offices. The same role (Vehicle Inspector) has five different titles: "Vehicle Inspector," "Licensing Inspector," "Compliance Officer," "Roadworthiness Officer," and "Technical Examiner." What is the most significant operational risk of this inconsistency?', '1.1 Job Analysis & Role Profiling', 1.00),
(395, 6, 2, 'SINGLE_CHOICE', 'A Regional Manager requests that a job description for a Senior Enforcement Officer include "must be able to work 60 hours per week during peak seasons" as a mandatory requirement. The Senior Officer knows that the standard workweek under the Ghana Labour Act is 40 hours with overtime provisions. What is the most appropriate action?', '1.1 Job Analysis & Role Profiling', 1.00),
(396, 6, 3, 'SINGLE_CHOICE', 'A Senior Officer is conducting a job analysis for a role that has been vacant for six months. During the vacancy, duties have been redistributed across three other employees. The manager wants the new job description to include all duties that were redistributed, arguing that "the role has expanded." What is the most appropriate first step?', '1.1 Job Analysis & Role Profiling', 1.00),
(397, 6, 4, 'SINGLE_CHOICE', 'A job analysis survey is distributed to 100 enforcement officers. The response rate is only 30%. The manager says the non-respondents are "too busy" and suggests that HR should proceed with the 30 responses. What is the most appropriate action?', '1.1 Job Analysis & Role Profiling', 1.00),
(398, 6, 5, 'SINGLE_CHOICE', 'Under Section 10 of the Ghana Labour Act, 2003 (Act 651), an employee must be provided with a written job description at the time of engagement. A manager argues that a verbal discussion of duties is sufficient because "employees forget written documents anyway." What is the Senior Officer''s best response?', '1.1 Job Analysis & Role Profiling', 1.00),
(399, 6, 6, 'SINGLE_CHOICE', 'A Senior Officer is sourcing for a Cybersecurity Lead role. Traditional job postings have yielded zero qualified applicants after 60 days. The Officer proposes using advanced Boolean strings on GitHub and Stack Overflow to identify professionals who contribute to open-source security projects. The hiring manager is skeptical, arguing that "real cybersecurity professionals are not posting code on public websites." What is the Senior Officer''s best response?', '1.2 Sourcing Strategies', 1.00),
(400, 6, 7, 'SINGLE_CHOICE', 'A Senior Officer is conducting passive candidate outreach on LinkedIn for a Senior Vehicle Inspector role. The Officer sends a personalized message to a candidate highlighting their experience with heavy-duty vehicle inspections. The candidate responds: "I am interested, but my current employer has a strict policy prohibiting employees from speaking to competitors. I cannot risk my job." Under Section 11 of the Ghana Labour Act, 2003 (Act 651) regarding freedom of association, what is the most appropriate response?', '1.2 Sourcing Strategies', 1.00),
(401, 6, 8, 'SINGLE_CHOICE', 'A Senior Officer is analyzing sourcing channel effectiveness over the past 12 months. The data shows: Channel Applications Hires Cost per hire National job board 2,500 5 GHS 800 LinkedIn Recruiter 300 12 GHS 1,200 Employee referrals 80 15 GHS 200 DVLA website 400 3 GHS 50 The Officer must recommend how to allocate next year''s sourcing budget of GHS 100,000. Which recommendation is most data-driven?', '1.2 Sourcing Strategies', 1.00),
(402, 6, 9, 'SINGLE_CHOICE', 'A Senior Officer is building a talent scarcity map for specialized mechanical engineers in Ghana. The Officer collects data on competitor headcounts, average tenure, university graduation rates, and salary benchmarks. The hiring manager asks why this data is necessary, arguing that "we should just post the job and see who applies." What is the Senior Officer''s best explanation?', '1.2 Sourcing Strategies', 1.00),
(403, 6, 10, 'SINGLE_CHOICE', 'A Senior Officer is reviewing LinkedIn outreach messages sent by a junior officer. The messages all begin with: "DVLA has an immediate opening for a Software Engineer. The salary is fixed at Step 8 of the civil service pay scale. Please reply if interested." The response rate is 2%. What is the most likely reason for the low response rate?', '1.2 Sourcing Strategies', 1.00),
(404, 6, 11, 'SINGLE_CHOICE', 'A Senior Officer is observing an interview panel for a Senior Vehicle Inspector role. Two panel members disagree significantly on a candidate''s rating after the same response. Panel Member A gives a 5/5, stating: "The candidate gave a detailed technical answer." Panel Member B gives a 2/5, stating: "The candidate did not address safety protocols, which are critical for this role." The Senior Officer reviews the interview guide and finds that the question did not specify whether the answer should include safety protocols. What is the most likely root cause of the disagreement?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(405, 6, 12, 'SINGLE_CHOICE', 'A Senior Officer is designing a Situational Judgment Test (SJT) for Frontline Enforcement Officer candidates. The test presents a scenario: " A driver becomes verbally abusive and refuses to present their license. You have informed them of the legal requirement three times. What do you do next?" The Officer writes four response options. Which option is most appropriate to include as the "least effective" response in an SJT?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(406, 6, 13, 'SINGLE_CHOICE', 'A Senior Officer is training interview panel members on the concept of "inter-rater reliability." A panel member asks: "Why does it matter if we rate candidates differently? We are all professionals with our own judgment." What is the Senior Officer''s best explanation?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(407, 6, 14, 'SINGLE_CHOICE', 'A Senior Officer is reviewing interview notes from a panel that interviewed five candidates for a Licensing Officer role. One panel member wrote detailed behavioral examples for each candidate. Another panel member wrote only one-word summaries: "good," "weak," "maybe," "strong," "no." The Officer is concerned about the quality of documentation. What is the most significant risk of the second panel member''s approach?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(408, 6, 15, 'SINGLE_CHOICE', 'During an interview for a Senior Officer position, a panel member asks a female candidate: "This role requires extensive travel to remote regions, sometimes for two weeks at a time. How will your family responsibilities affect your ability to travel?" The Senior HR Officer present recognizes this as a potentially discriminatory question. What is the most appropriate immediate action?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(409, 6, 16, 'SINGLE_CHOICE', 'A Senior Officer is drafting an Employer Value Proposition (EVP) for DVLA. The Officer writes: "Competitive salary, job security, and a pension plan." The Director reviews the draft and says: "This sounds like every other government agency. We need something distinctive to attract technical talent." Which addition would most effectively differentiate DVLA''s EVP for technical professionals?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(410, 6, 17, 'SINGLE_CHOICE', 'A Senior Officer is analyzing candidate experience data. The candidate Net Promoter Score (cNPS) has dropped from +45 to +15 over six months. The Officer reviews interview feedback forms and finds that candidates consistently complain about long gaps between interview stages (10-15 days) without communication. The recruitment team is understaffed. What is the most effective intervention to improve cNPS within existing resources?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(411, 6, 18, 'SINGLE_CHOICE', 'A Senior Officer discovers that internal staff are posting negative comments on personal social media accounts about administrative delays at DVLA. Comments include: "Management promised a new system three years ago. Still waiting." "No one ever responds to internal queries." The Officer is concerned about employer branding. What is the most appropriate response?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(412, 6, 19, 'SINGLE_CHOICE', 'A Senior Officer is reviewing candidate communication templates. One template, used for screening rejection, includes the phrase: "We regret to inform you that you do not meet the minimum qualifications for this role." The Officer knows that many rejected candidates actually met the minimum qualifications but were screened out due to high volume. What is the most appropriate action?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(413, 6, 20, 'SINGLE_CHOICE', 'A Senior Officer is evaluating two psychometric tests for a critical audit role. Test X has a reliability coefficient of 0.90 but no documented validity for predicting auditing accuracy. Test Y has a reliability coefficient of 0.75 and has been validated in two studies showing a statistically significant correlation (r=0.45) with auditing performance. The tests cost the same. Which test should the Senior Officer recommend?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(414, 6, 21, 'SINGLE_CHOICE', 'A Senior Officer is using the Big Five personality framework to profile candidates for a frontline Enforcement Officer role. The role requires handling tense compliance disputes, enforcing traffic regulations, and maintaining professionalism under verbal abuse. Which combination of Big Five traits is most likely to predict success in this role?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(415, 6, 22, 'SINGLE_CHOICE', 'A Senior Officer discovers that a group of candidates have shared screenshots of the DVLA cognitive ability test questions in a private WhatsApp group. The screenshots include 15 of the 50 test questions. The test vendor confirms that these are active questions still in use. What is the most appropriate immediate response?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(416, 6, 23, 'SINGLE_CHOICE', 'A Senior Officer is explaining the concept of "construct validity" to an internal interview panel. A panel member asks: "If a test has construct validity, does that mean it predicts job performance?" What is the most accurate response?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(417, 6, 24, 'SINGLE_CHOICE', 'A Senior Officer is reviewing psychometric test results for a candidate who scored in the 95th percentile on cognitive ability but very low on conscientiousness. The hiring manager wants to reject the candidate, arguing that "conscientiousness is more important than intelligence for this role." The Officer has data showing that cognitive ability predicts training success (r=0.60) while conscientiousness predicts job retention (r=0.40). The role requires both quick learning and consistent follow-through. What is the most appropriate recommendation?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(418, 6, 25, 'SINGLE_CHOICE', 'A Senior Officer is conducting a "blinded CV review" process for a technical role. The Officer redacts candidate names, gender indicators, age, educational institution names, and photographs before sending CVs to the hiring manager. The hiring manager complains: "I need to see where candidates went to school. Certain universities produce better graduates." What is the Senior Officer''s best response?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(419, 6, 26, 'SINGLE_CHOICE', 'A Senior Officer is analyzing demographic data of DVLA''s talent pipeline. The data shows that women represent 45% of applicants for enforcement roles but only 10% of those selected for interview. The Officer interviews the screening team and discovers that they are using an "unwritten rule" that female candidates may not be physically capable of enforcement work, despite no evidence supporting this assumption. What is the most appropriate structural intervention?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(420, 6, 27, 'SINGLE_CHOICE', 'A Senior Officer is reviewing DVLA''s recruitment data for the past two years. The analysis shows that candidates from remote rural regions are 50% less likely to be shortlisted than candidates from urban regions with similar qualifications. The Officer investigates and finds that the application system requires high-speed internet and a laptop computer. Many rural applicants are applying via mobile phones with limited connectivity. What is the most appropriate intervention?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(421, 6, 28, 'SINGLE_CHOICE', 'A Senior Officer is training interview panel members on fair hiring practices. A panel member asks: "If two candidates have identical qualifications, can I choose the one who seems like a better cultural fit?" What is the Senior Officer''s best response?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(422, 6, 29, 'SINGLE_CHOICE', 'Under Section 46 of the Ghana Labour Act, 2003 (Act 651) regarding employment of persons with disabilities, a Senior Officer is designing a selection process for a call centre role. A candidate with a speech disability applies. The candidate communicates clearly via typing and text-to-speech software. The role requires answering phone calls. What is the most appropriate action under the Act?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(423, 6, 30, 'SINGLE_CHOICE', 'A Senior Officer is conducting a TNA for enforcement officers. The data shows that officers make frequent errors in completing vehicle inspection forms. The training manager recommends a course on "attention to detail." The Senior Officer investigates further and discovers that the inspection form has 47 fields, but only 12 are relevant to most inspections, and there is no guidance on which fields are mandatory. What is the most appropriate conclusion?', '2.1 Training Needs Analysis (TNA)', 1.00),
(424, 6, 31, 'SINGLE_CHOICE', 'Under Section 15 of the Ghana Labour Act, 2003 (Act 651) regarding vocational training, a Senior Officer is advising a manager who wants to make a GHS 20,000 external training course mandatory for all team members. The manager wants employees to sign a bond requiring them to repay the cost if they leave within two years. What is the most appropriate guidance?', '2.1 Training Needs Analysis (TNA)', 1.00),
(425, 6, 32, 'SINGLE_CHOICE', 'A Senior Officer is reviewing TNA data from multiple sources. The data reveals conflicting findings: employee surveys indicate a need for "better communication skills," while performance data shows that communication-related errors are rare. Customer satisfaction scores are high. What is the most appropriate interpretation?', '2.1 Training Needs Analysis (TNA)', 1.00),
(426, 6, 33, 'SINGLE_CHOICE', 'A Senior Officer is designing a TNA process for a department with high turnover. The manager wants to conduct training needs interviews with departing employees during their exit interviews. The Legal Advisor warns that departing employees may not provide honest feedback about training gaps. What is the most appropriate complementary method to validate exit interview findings?', '2.1 Training Needs Analysis (TNA)', 1.00),
(427, 6, 34, 'SINGLE_CHOICE', 'A Senior Officer is prioritizing training needs identified through TNA. The Officer has identified four needs: (1) mandatory safety training required by regulation (GHS 50,000), (2) leadership development for high-potential staff (GHS 200,000), (3) customer service skills (GHS 30,000), and (4) new software training for an upcoming rollout (GHS 100,000). The total budget is GHS 150,000. Which prioritization framework is most appropriate?', '2.1 Training Needs Analysis (TNA)', 1.00),
(428, 6, 35, 'SINGLE_CHOICE', 'A Senior Officer is adapting an international driver safety curriculum for Ghana. The original includes examples of snow, left-hand driving, and four-way stops. What is the most appropriate adaptation?', '2.2 Instructional Design & Curriculum Development', 1.00),
(429, 6, 36, 'SINGLE_CHOICE', 'A Senior Officer is designing a blended learning curriculum for a software rollout. Which combination is most likely to maximize learning transfer?', '2.2 Instructional Design & Curriculum Development', 1.00),
(430, 6, 37, 'SINGLE_CHOICE', 'Under ISO 29993:2017 (learning services standard), which element must be included in a formal curriculum document?', '2.2 Instructional Design & Curriculum Development', 1.00),
(431, 6, 38, 'SINGLE_CHOICE', 'A Senior Officer is reviewing training materials written by a subject matter expert. The materials are technically accurate but too complex for the target audience. What is the most appropriate action?', '2.2 Instructional Design & Curriculum Development', 1.00),
(432, 6, 39, 'SINGLE_CHOICE', 'A Senior Officer is evaluating a training curriculum that uses only multiple-choice assessments. What is the most significant limitation of this approach?', '2.2 Instructional Design & Curriculum Development', 1.00),
(433, 6, 40, 'SINGLE_CHOICE', 'A Senior Officer is facilitating a virtual training session. Several participants have cameras off and are not responding. What is the best practice?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(434, 6, 41, 'SINGLE_CHOICE', 'A manager is training their team on a new process. During the session, the manager criticizes specific team members by name for past errors. What is the most significant problem with this approach?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(435, 6, 42, 'SINGLE_CHOICE', 'A training session is running 30 minutes behind schedule. The facilitator has 60 minutes of content remaining but only 30 minutes left. What is the most appropriate action?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(436, 6, 43, 'SINGLE_CHOICE', 'A Senior Officer is training enforcement officers on conflict de-escalation techniques. Which delivery method is most effective for this interpersonal skill?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(437, 6, 44, 'SINGLE_CHOICE', 'A participant arrives 45 minutes late to a 4-hour training session. What is the most appropriate facilitator response?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(438, 6, 45, 'SINGLE_CHOICE', 'A Senior Officer is evaluating e-learning completion data. Completion rates are 95%, but assessment scores average only 55%. What is the most likely explanation?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(439, 6, 46, 'SINGLE_CHOICE', 'Under the Data Protection Act, 2012 (Act 843), what must a Senior Officer ensure regarding learner data stored in the LMS?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(440, 6, 47, 'SINGLE_CHOICE', 'A Senior Officer is selecting an authoring tool for e-learning content. Which feature is essential for accessibility compliance?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(441, 6, 48, 'SINGLE_CHOICE', 'A Senior Officer discovers that an e-learning module takes 4 hours to complete online but the same content takes 2 hours in a classroom. What is the most appropriate action?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(442, 6, 49, 'SINGLE_CHOICE', 'A Senior Officer is designing an e-learning module for a mobile workforce. Which design principle is most critical for this audience?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(443, 6, 50, 'SINGLE_CHOICE', 'A Senior Officer designs a post-training observation checklist for enforcement officers. What must be in place for this to be valid?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(444, 6, 51, 'SINGLE_CHOICE', 'Under the Phillips ROI Methodology, what additional level extends Kirkpatrick''s four-level model?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(445, 6, 52, 'SINGLE_CHOICE', 'A Senior Officer is calculating the ROI of a driver safety program. The program cost GHS 50,000. It reduced accident-related costs by GHS 200,000. What is the ROI percentage?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(446, 6, 53, 'SINGLE_CHOICE', 'A Senior Officer finds that post-training assessment scores improved, but supervisor observations show no behavior change. What is the most likely explanation?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(447, 6, 54, 'SINGLE_CHOICE', 'A Senior Officer is designing a Level 4 evaluation for a leadership program. Which metric would be most appropriate for this level?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(448, 6, 55, 'SINGLE_CHOICE', 'A Senior Officer is reviewing the succession pipeline for a critical role. There is one "ready now" candidate, two "ready in 1-2 years," and zero "ready in 3-5 years." What risk does this present?', '2.6 Leadership Development & Succession Planning', 1.00),
(449, 6, 56, 'SINGLE_CHOICE', 'Under Section 15 of the Ghana Labour Act regarding training, can an employer require a leadership program participant to sign a bond?', '2.6 Leadership Development & Succession Planning', 1.00),
(450, 6, 57, 'SINGLE_CHOICE', 'A Senior Officer is designing a rotational assignment for a high-potential employee. What is the primary learning objective of such an assignment?', '2.6 Leadership Development & Succession Planning', 1.00),
(451, 6, 58, 'SINGLE_CHOICE', 'A Senior Officer notices that only candidates from Accra are being considered for leadership programs. What action should be taken?', '2.6 Leadership Development & Succession Planning', 1.00),
(452, 6, 59, 'SINGLE_CHOICE', 'What is the primary difference between a mentor and a coach in leadership development?', '2.6 Leadership Development & Succession Planning', 1.00),
(453, 6, 60, 'SINGLE_CHOICE', 'A Senior Officer is designing a peer coaching program for enforcement officers. What is a key success factor for peer coaching?', '2.7 Coaching and Mentoring Program Design', 1.00),
(454, 6, 61, 'SINGLE_CHOICE', 'Under Section 15 of the Ghana Labour Act regarding training, can coaching conversations be considered "training" for development obligations?', '2.7 Coaching and Mentoring Program Design', 1.00),
(455, 6, 62, 'SINGLE_CHOICE', 'A Senior Officer observes that a mentoring pair has met three times but no progress has been made. What is the most likely issue?', '2.7 Coaching and Mentoring Program Design', 1.00),
(456, 6, 63, 'SINGLE_CHOICE', 'A Senior Officer is asked to evaluate the effectiveness of a coaching program. Which metric is most meaningful at the program level?', '2.7 Coaching and Mentoring Program Design', 1.00),
(457, 6, 64, 'SINGLE_CHOICE', 'A Senior Officer is designing a "speed mentoring" event. What is the appropriate format for this activity?', '2.7 Coaching and Mentoring Program Design', 1.00)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

INSERT INTO `AnswerOption` (`id`, `questionId`, `order`, `text`, `isCorrect`) VALUES
(1573, 394, 1, 'Employees may feel that some titles are more prestigious than others, causing morale issues.', 0),
(1574, 394, 2, 'The Public Services Commission may require DVLA to standardize all titles immediately.', 0),
(1575, 394, 3, 'The organization cannot accurately compare performance or compensation across employees performing identical work in different regions.', 1),
(1576, 394, 4, 'External candidates will be confused about which role to apply for on the careers website.', 0),
(1577, 395, 1, 'Approve the requirement but add a note that overtime will be compensated.', 0),
(1578, 395, 2, 'Reject the requirement and remind the manager that the Labour Act sets maximum working hours.', 0),
(1579, 395, 3, 'Ask the manager to specify the business necessity for the 60-hour requirement and whether the workload can be redistributed across more staff.', 1),
(1580, 395, 4, 'Change the requirement to "must be willing to work additional hours as needed" to align with standard language.', 0),
(1581, 396, 1, 'Update the job description to include all redistributed duties as requested.', 0),
(1582, 396, 2, 'Interview the employees who temporarily performed the duties to determine which tasks were essential to the role versus temporary coverage.', 1),
(1583, 396, 3, 'Recommend hiring two employees instead of one because the workload has clearly increased.', 0),
(1584, 396, 4, 'Keep the original job description unchanged and assume the redistributed duties will return to the original role.', 0),
(1585, 397, 1, 'Proceed with the 30 responses; a sample of 30 is statistically sufficient for job analysis purposes.', 0),
(1586, 397, 2, 'Conduct follow-up reminders and extend the deadline to increase the response rate before proceeding.', 1),
(1587, 397, 3, 'Exclude the survey data entirely and rely solely on manager interviews.', 0),
(1588, 397, 4, 'Assume that non-respondents have no concerns about their job descriptions and proceed.', 0),
(1589, 398, 1, '" A verbal discussion is acceptable as long as the employee signs a confirmation form afterward."', 0),
(1590, 398, 2, '"The Labour Act requires written particulars; verbal discussions do not meet the legal standard."', 1),
(1591, 398, 3, '"You are correct; many organizations use verbal discussions successfully."', 0),
(1592, 398, 4, '"We can provide a written summary after the employee starts, as long as it is within the first month."', 0),
(1593, 399, 1, '"You are correct. Let us repost the job on traditional job boards with a higher salary range."', 0),
(1594, 399, 2, '"Public code repositories are where many technical professionals demonstrate their skills. We can find passive candidates who are not actively job searching."', 1),
(1595, 399, 3, '"I will remove GitHub and Stack Overflow from the sourcing plan and focus only on LinkedIn Recruiter."', 0),
(1596, 399, 4, '"Let us cancel the external search and ask the Ministry of Transport to assign an internal candidate."', 0),
(1597, 400, 1, '"I respect your employer''s policy. Please reach out to me if your situation changes in the future."', 0),
(1598, 400, 2, '"Your employer''s policy may not restrict your rights to explore career opportunities outside working hours. Our conversation can remain confidential."', 1),
(1599, 400, 3, '"I will contact your employer''s HR department to request formal permission for you to speak with us."', 0),
(1600, 400, 4, '"You should resign from your current position first, then contact us to discuss opportunities."', 0),
(1601, 401, 1, 'Shift the majority of the budget to the DVLA website because it has the lowest cost per hire.', 0),
(1602, 401, 2, 'Shift the majority of the budget to employee referrals because they have the highest hire-to- application ratio.', 0),
(1603, 401, 3, 'Allocate budget proportionally to each channel based on total applications received.', 0),
(1604, 401, 4, 'Increase investment in employee referrals and LinkedIn Recruiter while reducing spend on the national job board.', 1),
(1605, 402, 1, '"The Public Services Commission requires a talent scarcity map for all technical roles before recruitment can begin."', 0),
(1606, 402, 2, '"Understanding the market helps us set realistic timelines and expectations. If talent is scarce, we may need to adjust the sourcing strategy or timeline."', 1),
(1607, 402, 3, '"The data will be used to negotiate lower salaries with candidates who are less scarce in the market."', 0),
(1608, 402, 4, '"The map is primarily for HR reporting purposes and does not affect the actual recruitment process."', 0),
(1609, 403, 1, 'The messages were sent at the wrong time of day for technical professionals.', 0),
(1610, 403, 2, 'The messages focus on organizational constraints (pay scale, hierarchy) rather than appealing to technical professionals'' interests such as impact, technology stack, and autonomy.', 1),
(1611, 403, 3, 'The candidates on the list are not actually qualified for software engineering roles.', 0),
(1612, 403, 4, 'The junior officer used the wrong LinkedIn Recruiter license type for technical roles.', 0),
(1613, 404, 1, 'One panel member is biased against the candidate''s background.', 0),
(1614, 404, 2, 'The interview question lacks specificity, allowing each rater to interpret the desired response differently.', 1),
(1615, 404, 3, 'The candidate gave different answers to each panel member.', 0),
(1616, 404, 4, 'The panel members have different educational backgrounds.', 0),
(1617, 405, 1, '"Calmly explain the consequences of non-compliance, including potential fines and vehicle impoundment."', 0),
(1618, 405, 2, '"Request backup from a fellow enforcement officer before taking further action."', 0),
(1619, 405, 3, '"Walk away from the situation and report the driver''s license plate number to your supervisor later."', 1),
(1620, 405, 4, '"Stand your ground and repeat the legal requirement without raising your voice."', 0),
(1621, 406, 1, '"Inter-rater reliability is a technical metric required by the Public Services Commission; we do not need to understand it, just follow the process."', 0),
(1622, 406, 2, '"If raters disagree significantly, it suggests the interview process is not consistent or objective, which could lead to unfair hiring decisions and legal challenges."', 1),
(1623, 406, 3, '"Inter-rater reliability measures how quickly we complete interviews; faster interviews are more reliable."', 0),
(1624, 406, 4, '"Different ratings are actually desirable because they bring diverse perspectives to the hiring decision."', 0),
(1625, 407, 1, 'The panel member may have spent less time on the interviews than other panel members.', 0),
(1626, 407, 2, 'The lack of specific documentation makes it difficult to defend hiring decisions if challenged, and provides no basis for candidate feedback.', 1),
(1627, 407, 3, 'The panel member''s handwriting may be difficult for other staff to read.', 0),
(1628, 407, 4, 'The panel member may have favored candidates with certain personality types.', 0),
(1629, 408, 1, 'Allow the candidate to answer; the question is job-relevant because travel is a requirement.', 0),
(1630, 408, 2, 'Interrupt the line of questioning and remind the panel to focus on the candidate''s ability to meet the travel requirement, not personal or family circumstances.', 1),
(1631, 408, 3, 'Note the question in the candidate''s file for documentation purposes but take no other action.', 0),
(1632, 408, 4, 'Conclude the interview immediately and inform the panel chair that the interview must be rescheduled with different panel members.', 0),
(1633, 409, 1, '"Opportunity to work on Ghana''s largest vehicle registration database serving 5 million citizens."', 1),
(1634, 409, 2, '"Free parking and subsidized cafeteria meals for all employees."', 0),
(1635, 409, 3, '" Annual leave of 20 days plus public holidays."', 0),
(1636, 409, 4, '"Comprehensive health insurance for employees and their dependents."', 0),
(1637, 410, 1, 'Send automated status update emails at each stage, even if no decision has been made, to manage candidate expectations.', 1),
(1638, 410, 2, 'Reduce the number of interview stages from three to two to shorten the overall timeline.', 0),
(1639, 410, 3, 'Hire two additional recruitment coordinators to manage candidate communication.', 0),
(1640, 410, 4, 'Inform candidates at the outset that they should expect delays due to staffing constraints.', 0),
(1641, 411, 1, 'Issue a memo reminding staff that negative social media posts about DVLA are prohibited.', 0),
(1642, 411, 2, 'Investigate the root causes of the administrative delays and internal communication breakdowns before addressing external messaging.', 1),
(1643, 411, 3, 'Ask the Communications Department to post positive content on DVLA''s official social media accounts to counter the negative comments.', 0),
(1644, 411, 4, 'Disregard the comments; personal social media accounts do not represent DVLA''s official brand.', 0),
(1645, 412, 1, 'Keep the template as is; candidates expect honest feedback.', 0),
(1646, 412, 2, 'Change the template to a more generic message: "We have decided not to move forward with your application."', 1),
(1647, 412, 3, 'Remove all rejection communication; only contact candidates who are advancing.', 0),
(1648, 412, 4, 'Change the template to provide specific feedback based on the screening criteria, if resources allow.', 0),
(1649, 413, 1, 'Test X; higher reliability is more important than validity.', 0),
(1650, 413, 2, 'Test Y; validity matters more than reliability for predicting job performance, and 0.75 is acceptable.', 1),
(1651, 413, 3, 'Neither; both tests are insufficient; develop a work sample test instead.', 0),
(1652, 413, 4, 'Both tests; use Test X for initial screening and Test Y for final selection.', 0),
(1653, 414, 1, 'Low Openness and High Neuroticism (resistant to change, reactive to stress)', 0),
(1654, 414, 2, 'High Extraversion and Low Agreeableness (outgoing but confrontational)', 0),
(1655, 414, 3, 'High Conscientiousness, High Emotional Stability (Low Neuroticism), and Moderate Agreeableness (assertive but diplomatic)', 1),
(1656, 414, 4, 'High Agreeableness and High Openness (cooperative and creative)', 0),
(1657, 415, 1, 'Ignore the leak; cognitive ability questions cannot be effectively memorized.', 0),
(1658, 415, 2, 'Contact the WhatsApp group administrator and demand the screenshots be removed.', 0),
(1659, 415, 3, 'Disqualify the candidates who shared or accessed the screenshots, and request the vendor to replace the compromised questions before further testing.', 1),
(1660, 415, 4, 'Send a warning email to all candidates reminding them that sharing test content is prohibited, but proceed with the same test.', 0),
(1661, 416, 1, '"Yes, construct validity is the same as predictive validity."', 0),
(1662, 416, 2, '"No, construct validity means the test measures the underlying trait it claims to measure (e.g., leadership). Predictive validity measures whether it predicts job performance. A test needs both."', 1),
(1663, 416, 3, '"Construct validity is the only type of validity that matters for employment testing."', 0),
(1664, 416, 4, '"Construct validity is a statistical term that is not relevant to practical selection decisions."', 0),
(1665, 417, 1, 'Reject the candidate; low conscientiousness is a deal-breaker for retention.', 0),
(1666, 417, 2, 'Hire the candidate; cognitive ability at the 95th percentile is rare and valuable.', 0),
(1667, 417, 3, 'Recommend further assessment, such as a work sample or probationary period, to evaluate both competencies directly before making a final decision.', 1),
(1668, 417, 4, 'Average the two scores and compare to a composite threshold.', 0),
(1669, 418, 1, '"You are correct. I will restore the university names for you while keeping other information redacted."', 0),
(1670, 418, 2, '"Blinded reviews help us focus on skills and experience rather than assumptions about institutions. After we shortlist based on qualifications, you can review university backgrounds for the final candidates."', 1),
(1671, 418, 3, '"The Public Services Commission requires blinded reviews for all technical roles; I have no discretion."', 0),
(1672, 418, 4, '"If you are concerned about university quality, we can add a requirement for specific accreditation rather than naming institutions."', 0),
(1673, 419, 1, 'Remove all female applicants from the screening process to avoid bias accusations.', 0),
(1674, 419, 2, 'Replace the screening team with new staff who have not worked in enforcement.', 0),
(1675, 419, 3, 'Replace the subjective screening process with a standardized, job-relevant physical ability assessment administered to all candidates regardless of gender.', 1),
(1676, 419, 4, 'Add a note to the job description stating that "female candidates are strongly encouraged to apply."', 0),
(1677, 420, 1, 'Disregard the finding; candidates are responsible for having appropriate technology to apply.', 0),
(1678, 420, 2, 'Provide a paper-based application option and a mobile-optimized application form for rural applicants.', 1),
(1679, 420, 3, 'Remove all rural applicants from the data set to improve the statistics.', 0),
(1680, 420, 4, 'Require all applicants to submit applications in person at regional DVLA offices.', 0),
(1681, 421, 1, '"Yes, cultural fit is a valid reason to choose between equally qualified candidates."', 0),
(1682, 421, 2, '"Yes, but you must document the specific cultural traits you are assessing."', 0),
(1683, 421, 3, '"Be careful. ''Cultural fit'' can sometimes mask bias. Focus on job-relevant competencies and behaviors. If candidates are truly equal, any tie-breaking method must be non-discriminatory."', 1),
(1684, 421, 4, '"No, you must flip a coin or use another random method to avoid any appearance of bias."', 0),
(1685, 422, 1, 'Reject the candidate; the role requires verbal phone communication, which is an essential function.', 0),
(1686, 422, 2, 'Reject the candidate; but offer them a different role that does not require phone work.', 0),
(1687, 422, 3, 'Explore reasonable accommodations such as providing a text-to-speech system for phone calls or reassigning phone duties to another team member.', 1),
(1688, 422, 4, 'Hire the candidate and exempt them from phone duties without accommodation.', 0),
(1689, 423, 1, 'Officers need training on attention to detail as recommended.', 0),
(1690, 423, 2, 'The root cause is a poorly designed form, not a skill gap. Recommend form redesign before any training.', 1),
(1691, 423, 3, 'Officers are deliberately making errors and need disciplinary action.', 0),
(1692, 423, 4, 'The errors are within acceptable limits; no action is needed.', 0),
(1693, 424, 1, '"Training bonds are illegal under the Labour Act; you cannot require repayment."', 0),
(1694, 424, 2, '"Training bonds are permissible for significant external training costs if the employee agrees in writing and the bond is reasonable and proportionate to the training cost."', 1),
(1695, 424, 3, '"You should absorb all training costs; employees should never be asked to repay training expenses."', 0),
(1696, 424, 4, '"You should require employees to pay for the training upfront and reimburse them after two years of service."', 0),
(1697, 425, 1, 'Prioritize the employee survey data; employees know their own needs best.', 0),
(1698, 425, 2, 'Prioritize the performance data and customer satisfaction scores; they are objective measures of actual outcomes.', 0),
(1699, 425, 3, 'Conduct a follow-up investigation to understand why employees perceive a communication gap when objective data does not support it.', 1),
(1700, 425, 4, 'Implement communication skills training for all employees to address the perception regardless of objective data.', 0),
(1701, 426, 1, 'Rely only on exit interviews; departing employees are the most honest.', 0),
(1702, 426, 2, 'Conduct stay interviews with current high-performing employees to identify what training contributed to their success.', 1),
(1703, 426, 3, 'Cancel the TNA entirely; high turnover makes training irrelevant.', 0),
(1704, 426, 4, 'Survey only employees who have been with the organization for more than five years.', 0),
(1705, 427, 1, 'Prioritize the most expensive needs first to maximize budget utilization.', 0),
(1706, 427, 2, 'Prioritize the mandatory safety training (non-negotiable), then allocate remaining funds based on strategic impact and urgency of the software rollout.', 1),
(1707, 427, 3, 'Spread the budget equally across all four needs (GHS 37,500 each).', 0),
(1708, 427, 4, 'Prioritize leadership development because it has the highest long-term impact.', 0),
(1709, 428, 1, 'Use the international curriculum exactly as written; driving principles are universal.', 0),
(1710, 428, 2, 'Translate the curriculum into Twi but keep all examples unchanged.', 0),
(1711, 428, 3, 'Replace examples with Ghana-relevant scenarios while preserving core objectives.', 1),
(1712, 428, 4, 'Reject the international curriculum and develop an entirely new program.', 0),
(1713, 429, 1, 'Self-paced e-learning only, with no instructor interaction or practice.', 0),
(1714, 429, 2, 'Classroom lecture only, with no hands-on computer practice.', 0),
(1715, 429, 3, 'E-learning followed by in-person practice followed by job aids.', 1),
(1716, 429, 4, 'A single 8-hour lecture with no pre-work or post-training support.', 0),
(1717, 430, 1, 'The trainer''s photograph and biography for participant reference.', 0),
(1718, 430, 2, 'The names of all employees who previously failed the training.', 0),
(1719, 430, 3, 'Learning objectives, target audience, duration, and assessment methods.', 1),
(1720, 430, 4, 'The office cleaning schedule and lunch menu for training days.', 0),
(1721, 431, 1, 'Use the materials as written; technical accuracy is the priority.', 0),
(1722, 431, 2, 'Discard the materials and write new ones without the SME''s input.', 0),
(1723, 431, 3, 'Work with the SME to simplify language and add relevant examples.', 1),
(1724, 431, 4, 'Require the target audience to complete remedial prerequisites before training.', 0),
(1725, 432, 1, 'Multiple-choice questions are too expensive to produce for large groups.', 0),
(1726, 432, 2, 'Multiple-choice questions take longer for learners to complete than essays.', 0),
(1727, 432, 3, 'Multiple-choice questions may only measure recall, not practical application.', 1),
(1728, 432, 4, 'Multiple-choice questions are legally prohibited for public sector training.', 0),
(1729, 433, 1, 'Shout at participants to turn on cameras or be marked absent.', 0),
(1730, 433, 2, 'Continue teaching without acknowledging the lack of engagement.', 0),
(1731, 433, 3, 'End the session immediately and reschedule for another day.', 0),
(1732, 433, 4, 'Use polls, breakout rooms, and chat questions to increase engagement.', 1),
(1733, 434, 1, 'The manager is providing specific feedback, which is generally good practice.', 0),
(1734, 434, 2, 'The manager is saving time by addressing errors during group training.', 0),
(1735, 434, 3, 'The manager is demonstrating leadership by holding people accountable.', 0),
(1736, 434, 4, 'Public criticism can humiliate employees and discourage future learning.', 1),
(1737, 435, 1, 'Abruptly stop the session and tell participants to read remaining materials.', 0),
(1738, 435, 2, 'Rush through the remaining content at double speed without discussion.', 0),
(1739, 435, 3, 'Cut the lunch break to zero minutes to recover the lost training time.', 0),
(1740, 435, 4, 'Prioritize critical content, offer optional resources for skipped material.', 1),
(1741, 436, 1, 'A 200-slide PowerPoint presentation with no interactive components.', 0),
(1742, 436, 2, 'A written manual read aloud by the facilitator to the entire group.', 0),
(1743, 436, 3, 'A multiple-choice written exam testing knowledge of de-escalation steps.', 0),
(1744, 436, 4, 'Role-play scenarios with trained actors followed by structured feedback.', 1),
(1745, 437, 1, 'Publicly shame the participant for arriving late to the training session.', 0),
(1746, 437, 2, 'Spend 30 minutes re-teaching missed content for the late participant.', 0),
(1747, 437, 3, 'Refuse to provide any summary because the participant was late.', 0),
(1748, 437, 4, 'Quietly provide written missed content during a break and continue.', 1),
(1749, 438, 1, 'Learners are clicking through without genuine engagement or learning.', 1),
(1750, 438, 2, 'The assessment questions are too easy for the target audience.', 0),
(1751, 438, 3, 'The course content is too basic for experienced employees.', 0),
(1752, 438, 4, 'The LMS is incorrectly tracking completion status for learners.', 0),
(1753, 439, 1, 'Learner data can be shared publicly for research purposes.', 0),
(1754, 439, 2, 'Learner data can be sold to third-party training vendors.', 0),
(1755, 439, 3, 'Learner data must be collected with consent and stored securely.', 1),
(1756, 439, 4, 'Learner data does not require any protection or access controls.', 0),
(1757, 440, 1, 'The tool must have a modern, colorful user interface.', 0),
(1758, 440, 2, 'The tool must be compatible with only one operating system.', 0),
(1759, 440, 3, 'The tool must support closed captions and screen reader compatibility.', 1),
(1760, 440, 4, 'The tool must automatically translate content into multiple languages.', 0),
(1761, 441, 1, 'Ignore the discrepancy; online learning is always slower than classroom.', 0),
(1762, 441, 2, 'Convert all e-learning back to classroom delivery to save time.', 0),
(1763, 441, 3, 'Remove the e-learning module entirely and rely on job aids only.', 0),
(1764, 441, 4, 'Review the module for inefficient design and optimize navigation.', 1),
(1765, 442, 1, 'High-density text with small font size to fit more content.', 0),
(1766, 442, 2, '45-minute continuous video without any breaks or interactivity.', 0),
(1767, 442, 3, 'Content that requires a desktop computer and mouse to navigate.', 0),
(1768, 442, 4, 'Short modules and responsive design for mobile device viewing.', 1),
(1769, 443, 1, 'Observation must be conducted by the trainee''s friend or colleague.', 0),
(1770, 443, 2, 'Observation must be unannounced and without any bias mitigation.', 0),
(1771, 443, 3, 'Observation must be conducted only once immediately after training.', 0),
(1772, 443, 4, 'Clear behavioral rubric, trained observers, and baseline data for comparison.', 1),
(1773, 444, 1, 'Level 0 (Attendance) to measure who showed up for training.', 0),
(1774, 444, 2, 'Level 6 (Happiness) to measure participant emotional state.', 0),
(1775, 444, 3, 'Level 7 (Trainer Satisfaction) to measure instructor effectiveness.', 0),
(1776, 444, 4, 'Level 5 (Return on Investment) comparing monetary benefits to costs.', 1),
(1777, 445, 1, '25% (GHS 50,000 divided by GHS 200,000)', 0),
(1778, 445, 2, '200% (GHS 200,000 divided by GHS 100,000)', 0),
(1779, 445, 3, '250% (GHS 200,000 divided by GHS 80,000)', 0),
(1780, 445, 4, '300% (GHS 150,000 net benefit divided by GHS 50,000 cost)', 1),
(1781, 446, 1, 'The training content was completely irrelevant to the job.', 0),
(1782, 446, 2, 'The trainer was unqualified to deliver the training program.', 0),
(1783, 446, 3, 'The participants cheated on the post-training assessment.', 0),
(1784, 446, 4, 'The assessment measured knowledge, not application or transfer.', 1),
(1785, 447, 1, 'Participant smiles at the end of the leadership program.', 0),
(1786, 447, 2, 'Number of PowerPoint slides used in the program.', 0),
(1787, 447, 3, 'Trainer''s hourly rate for delivering the program.', 0),
(1788, 447, 4, 'Reduction in voluntary turnover among program participants'' teams.', 1),
(1789, 448, 1, 'No risk; one candidate is sufficient for any critical leadership role.', 0),
(1790, 448, 2, 'Low risk; two candidates in the pipeline provide adequate backup.', 0),
(1791, 448, 3, 'Moderate risk; three candidates total is acceptable coverage.', 0),
(1792, 448, 4, 'High risk if the ready-now candidate leaves or is not selected.', 1),
(1793, 449, 1, 'No, any training bond is automatically illegal under the Labour Act.', 0),
(1794, 449, 2, 'Yes, for any training regardless of cost or program purpose.', 0),
(1795, 449, 3, 'Yes, but only if the bond exceeds the employee''s annual salary.', 0),
(1796, 449, 4, 'Yes, for significant external programs if the bond is reasonable and documented.', 1),
(1797, 450, 1, 'To give the employee a paid break from regular work duties.', 0),
(1798, 450, 2, 'To reduce the employee''s overall workload permanently.', 0),
(1799, 450, 3, 'To allow the employee to avoid difficult or challenging tasks.', 0),
(1800, 450, 4, 'To expose the employee to different functions and build broader perspective.', 1),
(1801, 451, 1, 'Continue the practice; Accra has the best and brightest talent.', 0),
(1802, 451, 2, 'Eliminate all leadership programs to avoid the appearance of bias.', 0),
(1803, 451, 3, 'Only consider candidates from rural regions to balance representation.', 0),
(1804, 451, 4, 'Implement equitable selection criteria and source candidates from all regions.', 1),
(1805, 452, 1, 'There is no meaningful difference; the terms are identical in practice.', 0),
(1806, 452, 2, 'A mentor is always external; a coach is always internal to the organization.', 0),
(1807, 452, 3, 'A coach gives advice; a mentor only listens without providing guidance.', 0),
(1808, 452, 4, 'A coach focuses on specific skills; a mentor provides broader career guidance.', 1),
(1809, 453, 1, 'No training for participants; they should figure it out themselves.', 0),
(1810, 453, 2, 'Mandatory participation with no opt-out option for anyone.', 0),
(1811, 453, 3, 'Matching participants randomly without any input from either person.', 0),
(1812, 453, 4, 'Training participants on coaching skills and establishing clear program guidelines.', 1),
(1813, 454, 1, 'No; only formal classroom training counts toward development obligations.', 0),
(1814, 454, 2, 'Yes, but only if documented on official organization letterhead.', 0),
(1815, 454, 3, 'Yes, but only if delivered by an external certified consultant.', 0),
(1816, 454, 4, 'Yes, organizations should recognize coaching as a legitimate development activity.', 1),
(1817, 455, 1, 'The mentor is too experienced and intimidates the mentee.', 0),
(1818, 455, 2, 'The mentee is too motivated and wants to move too quickly.', 0),
(1819, 455, 3, 'The organization spends too much money on the mentoring program.', 0),
(1820, 455, 4, 'Lack of clear goals or structure; establish a mentoring action plan.', 1),
(1821, 456, 1, 'Number of coaching sessions that were completed on time.', 0),
(1822, 456, 2, 'Length of coaching sessions in minutes or hours.', 0),
(1823, 456, 3, 'Coach''s personal satisfaction with the program.', 0),
(1824, 456, 4, 'Coachee progress toward goals and observed behavior change.', 1),
(1825, 457, 1, 'A six-month one-on-one relationship with weekly hour-long meetings.', 0),
(1826, 457, 2, 'A 40-hour intensive workshop delivered over five consecutive days.', 0),
(1827, 457, 3, 'A written correspondence course delivered by postal mail.', 0),
(1828, 457, 4, 'A structured event with short, focused conversations between mentors and mentees.', 1)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

