INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(458, 7, 1, 'SINGLE_CHOICE', 'DVLA is implementing a new digital driver''s license system that will automate 60% of the duties currently performed by the Data Verification team. The HR Manager must decide how to handle the job descriptions for this team. The Director wants to keep all positions unchanged. The IT Director wants to retrain all staff on new systems. The Finance Director wants to eliminate half the positions immediately. Which approach aligns most strategically with workforce planning principles?', '1.1 Job Analysis & Role Profiling', 1.00),
(459, 7, 2, 'SINGLE_CHOICE', 'An HR Manager is reviewing job descriptions across DVLA and finds that 40% of descriptions include the phrase "any other duties as assigned by the supervisor." Legal counsel has advised that this phrase, if overused, can expose the organization to risk. The Manager must develop a policy. Which policy statement is most balanced and legally defensible?', '1.1 Job Analysis & Role Profiling', 1.00),
(460, 7, 3, 'SINGLE_CHOICE', 'DVLA has acquired new vehicle inspection technology that requires specialized technical knowledge. The current job description for Vehicle Inspector does not mention this technology. The Training Department wants to train all existing inspectors. The Recruitment Department wants to hire new inspectors with the required skills and redeploy existing staff. The Operations Director wants to delay the technology rollout until all inspectors are trained. As HR Manager, what is the most strategic recommendation?', '1.1 Job Analysis & Role Profiling', 1.00),
(461, 7, 4, 'SINGLE_CHOICE', 'A manager submits a job description for a new role that includes a requirement for "seven years of experience in vehicle inspection." The HR Manager notes that the current average tenure of successful inspectors in similar roles is three years. The manager argues that "we need to raise standards." What is the most appropriate response based on job analysis principles?', '1.1 Job Analysis & Role Profiling', 1.00),
(462, 7, 5, 'SINGLE_CHOICE', 'An HR Manager is leading a job analysis for a role that will be redesigned as part of a broader reorganization. The timeline is aggressive: the new job description must be finalized in two weeks to meet a Public Services Commission deadline. The Manager must choose between a rapid survey of incumbents (70% response rate achievable in one week) or a more thorough method including focus groups and observation (four weeks). What is the most appropriate decision?', '1.1 Job Analysis & Role Profiling', 1.00),
(463, 7, 6, 'SINGLE_CHOICE', 'DVLA is undergoing a digital transformation that requires hiring 15 specialized IT professionals over the next 18 months. The current public sector salary scale is 30% below market rate for these roles. The Public Services Commission has denied a request for a pay supplement. The HR Manager has a limited budget for sourcing activities. The Director of IT proposes using an external agency that specializes in public sector IT recruitment. The Finance Director proposes offering non-salary incentives such as additional leave and flexible work arrangements. The Head of Communications proposes a branding campaign to position DVLA as a "mission-driven" employer. Which combination of strategies is most likely to attract qualified candidates within the constraints?', '1.2 Sourcing Strategies', 1.00),
(464, 7, 7, 'SINGLE_CHOICE', 'An HR Manager is designing a passive talent pipeline policy for executive and technical tracks at DVLA. The Director wants to focus only on technical roles because "executives can be hired through board connections." The Deputy Director wants to focus only on executive roles because "technical staff are easier to find." The Manager has limited resources and can only build one pipeline this year. What is the most strategic recommendation?', '1.2 Sourcing Strategies', 1.00),
(465, 7, 8, 'SINGLE_CHOICE', 'DVLA needs to source multiple technical consultants for a nationwide digital vehicle registration upgrade. The Assistant HR Manager suggests using an "Exclusive Retained Search" agency. The Line Manager wants a "Contingent Agency" model. The Procurement Director prefers a competitive bidding process with multiple agencies. The project has a tight deadline of six months and requires specialized knowledge of vehicle registration systems. The budget allows for either one retained search or three contingent placements. What is the most appropriate decision based on the circumstances?', '1.2 Sourcing Strategies', 1.00),
(466, 7, 9, 'SINGLE_CHOICE', 'An HR Manager is evaluating the compliance of automated sourcing tools with the Ghana Data Protection Act, 2012 (Act 843). A vendor proposes a tool that scrapes candidate profiles from public websites and automatically enriches them with inferred data (e.g., predicting ethnicity, political affiliation, or health status). The vendor argues that this is legal because the data is "publicly available." The Legal Advisor is unavailable for consultation. The Manager must decide whether to proceed with the tool. What is the most appropriate decision?', '1.2 Sourcing Strategies', 1.00),
(467, 7, 10, 'SINGLE_CHOICE', 'The Director of DVLA requests a strategy to improve diversity of the talent pool for leadership roles within the enforcement division. The division currently has 85% male representation at the leadership level. The HR Manager has three proposals: (1) targeted outreach to women''s professional networks, (2) blind CV screening to reduce unconscious bias, and (3) requiring diverse interview panels. The Director asks which single intervention will have the greatest impact. The Manager has data showing that the current pipeline of female candidates at the application stage is 40%, but at the shortlist stage it drops to 10%. What should the Manager recommend as the priority intervention?', '1.2 Sourcing Strategies', 1.00),
(468, 7, 11, 'SINGLE_CHOICE', 'An HR Manager is designing a multi-stage assessment center for selecting Regional DVLA Directors. The assessment center will run for two days and include cognitive ability tests, a situational judgment test, a structured behavioral interview, and an in-basket simulation. The budget allows for 20 candidates to participate. The Operations Director argues that the assessment center is too expensive and proposes replacing it with a 30-minute unstructured interview. The Finance Director supports the Operations Director. The HR Manager has data showing that assessment centers have a predictive validity of 0.65 for managerial performance, compared to 0.20 for unstructured interviews. What is the HR Manager''s most effective response?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(469, 7, 12, 'SINGLE_CHOICE', 'The Assistant HR Manager recommends using "Stress Interview Techniques" (e.g., intentionally aggressive questioning, prolonged silence) to test the emotional stability of managerial candidates for the enforcement division. The Assistant Manager argues that "enforcement work is high-pressure, and we need to see how candidates react when challenged." The HR Manager is concerned about the validity and legality of stress interviewing. The Legal Advisor has no specific guidance on stress interviews under Ghanaian law. What is the HR Manager''s most appropriate policy directive?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(470, 7, 13, 'SINGLE_CHOICE', 'An HR Manager is writing an executive paper to reform DVLA''s panel interview process. Current practice allows any senior management official to sit on a panel without training. The Manager has data showing that untrained panel members are three times more likely to make hiring decisions based on "gut feel" rather than job-relevant criteria, and that these hires have a 40% higher turnover rate in the first year. The Director is concerned that mandatory training will delay the hiring process. What is the HR Manager''s best recommendation to balance quality and efficiency?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(471, 7, 14, 'SINGLE_CHOICE', 'An HR Manager is evaluating a work sample simulation test designed for an Assistant Finance Manager role. The test asks candidates to reconcile a sample ledger with 20 transactions. The hiring manager argues that the test is too easy and does not reflect the complexity of DVLA''s financial systems. The test vendor offers to create a more complex version for an additional fee. The Manager has limited budget. What is the most appropriate way to ensure "content validity" within budget constraints?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(472, 7, 15, 'SINGLE_CHOICE', 'An Assistant HR Manager discovers that an external psychometric test provider being considered for DVLA has never validated its assessment tools within a sub-Saharan African public sector context. The provider offers a discount if DVLA agrees to use the tools without validation. The provider argues that "cognitive ability is universal and does not require cultural adaptation." The HR Manager is not an expert in psychometrics but recognizes potential risks. What is the most appropriate action?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(473, 7, 16, 'SINGLE_CHOICE', 'An HR Manager is tasked with designing an authentic, data-driven Employer Value Proposition (EVP) for DVLA. The Manager has budget to conduct one research activity. The Director suggests using an external marketing agency to create aspirational messaging. The Communications Director suggests surveying current employees. The Finance Director suggests benchmarking against other public sector agencies. The Manager must choose the most effective starting point. Which option will provide the most authentic foundation for the EVP?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(474, 7, 17, 'SINGLE_CHOICE', 'The Assistant HR Manager notes that candidate experience is failing because line managers are routinely late to interviews (30-60 minutes) and act dismissively toward candidates. When the Assistant Manager raises this with line managers, they respond: "We are too busy with our operational work to prioritize interviews." The HR Manager must design a structural intervention. Which intervention is most likely to change line manager behavior?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(475, 7, 18, 'SINGLE_CHOICE', 'An HR Manager is designing a candidate journey map for specialized software developers. The current process requires: (1) online application, (2) phone screening, (3) in-person technical test in Accra, (4) in-person panel interview in Accra, (5) reference checks, (6) medical exam in Accra. The average candidate travels to Accra three times over six weeks. The Manager wants to reduce candidate effort. Which redesign will most improve the candidate experience while maintaining assessment quality?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(476, 7, 19, 'SINGLE_CHOICE', 'A Ghanaian tech influencer posts a viral thread on social media detailing their interview experience at DVLA. The thread describes: being kept waiting for two hours, being asked irrelevant questions about personal life, and receiving a rejection email addressed to the wrong candidate name. The post has been shared 5,000 times. The Communications Director wants to issue a public denial. The Legal Advisor wants to threaten legal action. The HR Manager wants to respond transparently. The Director must decide. What is the most appropriate employer brand response?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(477, 7, 20, 'SINGLE_CHOICE', 'An HR Manager is calculating the return on investment (ROI) of a candidate experience improvement initiative. The initiative cost GHS 200,000 to implement (new communication platform, interviewer training, candidate feedback system). One year after implementation, the following changes occurred: offer acceptance rate increased from 55% to 75%; time-to-fill decreased from 90 days to 60 days; external agency spend decreased by GHS 150,000 because more candidates accepted offers directly. What is the most appropriate way to present the ROI to the Director?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(478, 7, 21, 'SINGLE_CHOICE', 'An HR Manager is designing a selection matrix for specialized Software Engineers at DVLA. The Line Manager insists on using the Myers-Briggs Type Indicator (MBTI) to select candidates, arguing that "it is widely used and helps us understand how candidates think." The HR Manager has read research showing that MBTI has poor test-retest reliability and no predictive validity for job performance. The Line Manager is influential and has the support of the Director of Operations. The HR Manager must decide how to respond. What is the most appropriate approach?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(479, 7, 22, 'SINGLE_CHOICE', 'The Assistant HR Manager recommends setting the cut-off score for a cognitive selection test at 95% to "ensure we hire only the absolute best talent." The HR Manager reviews the distribution of test scores from a pilot group of current high-performing employees. The scores range from 65% to 95%, with an average of 82%. Only 5% of current high performers scored above 90%. What is the most likely consequence of setting the cut-off at 95%?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(480, 7, 23, 'SINGLE_CHOICE', 'An HR Manager is evaluating an external vendor offering " AI-driven Facial Expression Analysis" during video interviews to score candidate honesty and engagement. The vendor claims the tool is 85% accurate based on their internal validation study. The vendor''s validation study was conducted on a sample of 200 university students in North America. The Manager must decide whether to pilot the tool for DVLA''s customer service hires in Ghana. What is the most appropriate decision based on ethical and legal considerations?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(481, 7, 24, 'SINGLE_CHOICE', 'An HR Manager is designing a psychometric battery for promotional tracks to senior management at DVLA. The Manager wants to ensure the assessments measure "criterion content" - meaning they predict success in the target role. The Manager has access to a sample of 50 current senior managers whose performance ratings range from outstanding to poor. What is the most appropriate validation method?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(482, 7, 25, 'SINGLE_CHOICE', 'An Assistant HR Manager notes that several candidates have flagged that the English terminology used in an imported cognitive reasoning test includes cultural references unique to North America (e.g., baseball terms, American historical figures, idioms like "ballpark estimate"). The test vendor argues that these references do not affect the underlying cognitive measurement. The Manager must decide whether to continue using the test. What is the most appropriate decision?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(483, 7, 26, 'SINGLE_CHOICE', 'An HR Manager is designing a macro "Diversity, Equity, and Inclusion (DEI) Talent Acquisition Strategy" for DVLA. The Manager has three proposed initiatives: (1) targeted outreach to underrepresented communities, (2) blind CV screening, and (3) mandatory DEI training for all hiring managers. The budget allows for only one initiative this year. The Manager has data showing that the current applicant pool is diverse (45% women, 35% rural), but the shortlist stage shows significant drop-off for both groups (down to 15% each). Which initiative addresses the identified bottleneck most directly?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(484, 7, 27, 'SINGLE_CHOICE', 'The Assistant HR Manager presents a draft policy that establishes absolute, unchangeable demographic quotas for all technical appointments (e.g., "40% of all hires must be women, 30% must come from rural regions"). The Assistant Manager argues that quotas are necessary to address historical underrepresentation. The HR Manager is concerned about legal risks and unintended consequences. What is the most appropriate guidance?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(485, 7, 28, 'SINGLE_CHOICE', 'An HR Manager is reviewing regional hiring practices. The Eastern Regional office has a policy of "local hire first," prioritizing candidates from within the region. The result is that the office has no employees from other regions or ethnic backgrounds. The Regional Director argues that "local hire" serves the community better because staff understand local languages and customs. The Manager must decide whether to intervene. What is the most appropriate recommendation?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(486, 7, 29, 'SINGLE_CHOICE', 'During a post-interview debrief, a manager says about a candidate: "His qualifications are excellent, and he has strong technical skills. But I don''t think he will fit our team culture. He is older than the rest of the team, and I worry he won''t adapt to our fast-paced environment." The candidate is 52 years old. The team''s average age is 34. The HR Manager is present. What is the most appropriate response?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(487, 7, 30, 'SINGLE_CHOICE', 'An HR Manager is evaluating two external executive search firms to lead a diverse slate search for a Deputy Director role. Firm A has a strong track record of placing diverse candidates but charges 30% more. Firm B is cheaper but cannot provide any data on the diversity of their slates. The hiring manager prefers Firm B because "diversity is not my priority; I want the best person." The HR Manager must decide. What is the most appropriate decision?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(488, 7, 31, 'SINGLE_CHOICE', 'An HR Manager is designing a TNA framework for the entire DVLA. The Manager has three options: (1) a comprehensive annual TNA for all departments costing GHS 300,000, (2) a rolling TNA where each department is analyzed every three years costing GHS 100,000 annually, or (3) a reactive TNA conducted only when performance problems arise costing GHS 50,000 annually. The Director wants to minimize costs. The Operations Director wants to ensure critical roles are covered. The Manager must balance cost, coverage, and strategic value. Which approach is most appropriate?', '2.1 Training Needs Analysis (TNA)', 1.00),
(489, 7, 32, 'SINGLE_CHOICE', 'An HR Manager is reviewing TNA data over three years. Each year, the same gap appears: "customer service skills." Each year, the organization invests in customer service training. Each year, customer satisfaction scores remain unchanged. The Manager is concerned that training is not the solution. What is the most appropriate next step?', '2.1 Training Needs Analysis (TNA)', 1.00),
(490, 7, 33, 'SINGLE_CHOICE', 'An HR Manager is leading a TNA for a department that is resistant to change. The department head says: "We do not need a TNA. I have been managing this team for 15 years, and I know what training they need." The Manager has data from other departments showing that TNA reduced training waste by 40%. What is the most effective approach to gain the department head''s cooperation?', '2.1 Training Needs Analysis (TNA)', 1.00),
(491, 7, 34, 'SINGLE_CHOICE', 'An HR Manager is evaluating whether to conduct a TNA for a new leadership development program. The program is based on a corporate competency model from a multinational company. The Manager is concerned that the competency model may not reflect DVLA''s public sector context. What is the most appropriate action?', '2.1 Training Needs Analysis (TNA)', 1.00),
(492, 7, 35, 'SINGLE_CHOICE', 'An HR Manager is designing a TNA for a technical role that is changing rapidly due to new technology. The TNA conducted six months ago is already outdated. The Manager needs a more agile approach. Which TNA method is most appropriate for a rapidly changing environment?', '2.1 Training Needs Analysis (TNA)', 1.00),
(493, 7, 36, 'SINGLE_CHOICE', 'An HR Manager is designing a leadership curriculum for DVLA managers. The Manager must choose between a competency-based model (focused on specific skills) and an experiential model (focused on learning through assignments). The Director wants quick results. The Learning Director advocates for long-term behavior change. Research shows that experiential learning produces more durable behavior change but takes longer. What is the most appropriate design?', '2.2 Instructional Design & Curriculum Development', 1.00),
(494, 7, 37, 'SINGLE_CHOICE', 'An HR Manager is reviewing a training curriculum that includes examples featuring only male drivers and male enforcement officers. The Manager is concerned about inclusivity. The course developer argues that examples are not legally regulated content. What is the most appropriate action?', '2.2 Instructional Design & Curriculum Development', 1.00),
(495, 7, 38, 'SINGLE_CHOICE', 'An HR Manager is designing a curriculum for staff with widely varying levels of prior knowledge. The Manager has three options: (1) assume all learners are beginners, (2) assume all learners are experts, or (3) use a pre-assessment to differentiate. The budget allows for only one option. Which option is most effective?', '2.2 Instructional Design & Curriculum Development', 1.00),
(496, 7, 39, 'SINGLE_CHOICE', 'An HR Manager is selecting an external vendor to develop a technical training curriculum. Vendor A has extensive private sector experience but no public sector work. Vendor B has public sector experience but higher costs. Vendor C has no references but the lowest price. Which selection criterion should carry the most weight?', '2.2 Instructional Design & Curriculum Development', 1.00),
(497, 7, 40, 'SINGLE_CHOICE', 'An HR Manager is implementing a new curriculum for a mandatory compliance training. The training takes four hours to complete. Employees complain that the training is too long and irrelevant to their roles. The Manager reviews the curriculum and finds that 60% of the content applies only to two of the ten job families. What is the most appropriate action?', '2.2 Instructional Design & Curriculum Development', 1.00),
(498, 7, 41, 'SINGLE_CHOICE', 'An HR Manager is developing a "Train the Trainer" program for subject matter experts who will deliver technical training. Which component is most critical for success?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(499, 7, 42, 'SINGLE_CHOICE', 'A manager observes a trainer reading directly from slides without eye contact. How should the manager provide feedback to this trainer?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(500, 7, 43, 'SINGLE_CHOICE', 'An HR Manager is designing a facilitation guide for a 2-day leadership offsite. Which elements must the facilitator guide include?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(501, 7, 44, 'SINGLE_CHOICE', 'An HR Manager receives participant feedback that a facilitator was entertaining but did not cover the learning objectives. What is the most appropriate action?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(502, 7, 45, 'SINGLE_CHOICE', 'An HR Manager is selecting external facilitators for a senior leadership program. Which selection criterion should carry the most weight?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(503, 7, 46, 'SINGLE_CHOICE', 'An HR Manager is developing a business case to migrate from a basic LMS to an enterprise Learning Experience Platform (LXP). The Director asks: "What does an LXP do that our current LMS cannot?" What is the most compelling differentiator?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(504, 7, 47, 'SINGLE_CHOICE', 'An HR Manager is reviewing e-learning analytics and finds a module with 50% dropout at the 10-minute mark. What is the most appropriate action?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(505, 7, 48, 'SINGLE_CHOICE', 'An HR Manager is selecting an e-learning vendor. The vendor offers SCORM-compliant content. Why is SCORM compliance important?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(506, 7, 49, 'SINGLE_CHOICE', 'A manager observes that some regional offices lack reliable internet access. How should e- learning be deployed to these locations?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(507, 7, 50, 'SINGLE_CHOICE', 'An HR Manager is evaluating the ROI of DVLA''s e-learning investments. The Manager has data on course completion rates, assessment scores, and employee satisfaction. What additional data is most critical for calculating ROI?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(508, 7, 51, 'SINGLE_CHOICE', 'An HR Manager is evaluating a compliance training program. The training cost GHS 100,000. After training, compliance violations decreased by 60%, saving GHS 300,000 in fines and rework. What is the Benefit-Cost Ratio (BCR)?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(509, 7, 52, 'SINGLE_CHOICE', 'A Manager wants to isolate the effect of training from other factors (new technology, new supervisor). Which evaluation design controls for this?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(510, 7, 53, 'SINGLE_CHOICE', 'An HR Manager receives Level 1 scores averaging 4.9/5 but Level 3 scores showing no behavior change. What should the Manager conclude?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(511, 7, 54, 'SINGLE_CHOICE', 'A Manager is presenting evaluation results to executive leadership. What is the most impactful way to communicate Level 4 findings?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(512, 7, 55, 'SINGLE_CHOICE', 'An HR Manager is evaluating whether to continue a leadership program that costs GHS 500,000 annually. The program has been running for three years. The Manager has data on participant satisfaction, knowledge gain, and behavior change. What additional data is most critical for the continuation decision?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(513, 7, 56, 'SINGLE_CHOICE', 'An HR Manager is designing a leadership competency model for DVLA managers. What is the most valid method for developing this model?', '2.6 Leadership Development & Succession Planning', 1.00),
(514, 7, 57, 'SINGLE_CHOICE', 'A Manager is reviewing the 9-box grid and finds many employees in "high potential, low performance." What is the most appropriate development action?', '2.6 Leadership Development & Succession Planning', 1.00),
(515, 7, 58, 'SINGLE_CHOICE', 'A Manager is implementing a "reverse mentoring" program where junior staff mentor senior leaders on digital topics. What is the strategic purpose of this approach?', '2.6 Leadership Development & Succession Planning', 1.00),
(516, 7, 59, 'SINGLE_CHOICE', 'An Assistant Manager finds that the succession plan is documented but never discussed with candidates. What is the risk of this practice?', '2.6 Leadership Development & Succession Planning', 1.00),
(517, 7, 60, 'SINGLE_CHOICE', 'A Manager is evaluating external leadership development providers. One offers a one-week intensive program. Another offers a six-month blended program. Which is more effective for behavior change?', '2.6 Leadership Development & Succession Planning', 1.00),
(518, 7, 61, 'SINGLE_CHOICE', 'An HR Manager is designing a formal mentoring program for high-potential employees. Which element is most critical for program success?', '2.7 Coaching and Mentoring Program Design', 1.00),
(519, 7, 62, 'SINGLE_CHOICE', 'A Manager is deciding between internal and external coaches for senior leaders. Which factor favors external coaches?', '2.7 Coaching and Mentoring Program Design', 1.00),
(520, 7, 63, 'SINGLE_CHOICE', 'A Manager receives a complaint that a mentor is giving inappropriate advice (e.g., how to avoid work). What should the Manager do?', '2.7 Coaching and Mentoring Program Design', 1.00),
(521, 7, 64, 'SINGLE_CHOICE', 'An Assistant Manager is designing a coaching program for underperforming employees. What is the appropriate relationship between coaching and Performance Improvement Plans (PIPs)?', '2.7 Coaching and Mentoring Program Design', 1.00),
(522, 7, 65, 'SINGLE_CHOICE', 'A Manager wants to train line managers to coach their own teams. What is the most important prerequisite for manager-as-coach success?', '2.7 Coaching and Mentoring Program Design', 1.00)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

INSERT INTO `AnswerOption` (`id`, `questionId`, `order`, `text`, `isCorrect`) VALUES
(1829, 458, 1, 'Keep all positions unchanged and add digital skills to the existing job descriptions as "preferred" qualifications.', 0),
(1830, 458, 2, 'Eliminate half the positions immediately and transfer the remaining staff to other departments.', 0),
(1831, 458, 3, 'Conduct a future-state job analysis to determine the competencies and headcount needed post-implementation, then develop a transition plan.', 1),
(1832, 458, 4, 'Retrain all staff and keep all positions, adding the new digital duties without removing any current duties.', 0),
(1833, 459, 1, 'Remove the phrase from all job descriptions immediately; it is never enforceable.', 0),
(1834, 459, 2, 'Keep the phrase in all job descriptions but add a note that employees may refuse duties outside their job family.', 0),
(1835, 459, 3, 'Allow the phrase only for roles at Senior Officer level and above, where broader discretion is expected.', 0),
(1836, 459, 4, 'Limit use of the phrase and require that any duty assigned under it must be reasonably related to the employee''s role, level, and location.', 1),
(1837, 460, 1, 'Train all existing inspectors; internal development is less costly than external hiring.', 0),
(1838, 460, 2, 'Hire new inspectors with the required skills and redeploy existing inspectors to other roles where their current skills remain valuable.', 0),
(1839, 460, 3, 'Delay the technology rollout for 12 months to allow sufficient time for comprehensive training of all existing staff.', 0),
(1840, 460, 4, 'Conduct a skills gap analysis first to determine how many existing inspectors can realistically be upskilled versus how many new hires are needed.', 1),
(1841, 461, 1, 'Approve the seven-year requirement; raising standards will improve the quality of hires.', 0),
(1842, 461, 2, 'Reject the requirement and keep the three-year standard that reflects current successful incumbents.', 0),
(1843, 461, 3, 'Conduct a validation study to determine whether years of experience actually predict performance in the role before setting a requirement.', 1),
(1844, 461, 4, 'Change the requirement to "seven years of experience or a master''s degree" to provide flexibility.', 0),
(1845, 462, 1, 'Choose the rapid survey to meet the deadline; some data is better than no data.', 0),
(1846, 462, 2, 'Request an extension from the Public Services Commission to allow for the more thorough method.', 1),
(1847, 462, 3, 'Proceed without job analysis and use a generic job description template to meet the deadline.', 0),
(1848, 462, 4, 'Conduct the rapid survey now and schedule follow-up focus groups after the deadline for future revisions.', 0),
(1849, 463, 1, 'Use the external agency exclusively; they have existing relationships with qualified candidates.', 0),
(1850, 463, 2, 'Offer non-salary incentives only; additional leave costs less than salary increases.', 0),
(1851, 463, 3, 'Run the branding campaign only; mission-driven messaging attracts technical talent.', 0),
(1852, 463, 4, 'Combine the branding campaign with non-salary incentives and targeted direct sourcing, while continuing to advocate for a pay supplement.', 1),
(1853, 464, 1, 'Build the pipeline for technical roles; they are harder to fill on short notice than executive roles.', 0),
(1854, 464, 2, 'Build the pipeline for executive roles; leadership vacancies have higher organizational impact.', 0),
(1855, 464, 3, 'Build a pilot pipeline for one executive role and one technical role to test both approaches before scaling.', 0),
(1856, 464, 4, 'Conduct a risk assessment of both role families based on vacancy history, time-to-fill, and business impact, then prioritize accordingly.', 1),
(1857, 465, 1, 'Choose the contingent model; it is cheaper and allows DVLA to work with multiple agencies simultaneously.', 0),
(1858, 465, 2, 'Choose the retained search model; the specialized nature of the roles and tight deadline justify the exclusive, deep-market approach.', 1),
(1859, 465, 3, 'Use the competitive bidding process to select both a retained and a contingent agency.', 0),
(1860, 465, 4, 'Cancel the use of external agencies and require internal staff to perform the work.', 0),
(1861, 466, 1, 'Proceed with the tool; publicly available data is not subject to the Data Protection Act.', 0),
(1862, 466, 2, 'Proceed with the tool but disable the automatic enrichment features for inferred data.', 0),
(1863, 466, 3, 'Do not proceed; the tool''s enrichment features likely violate data minimization and consent principles under Act 843.', 1),
(1864, 466, 4, 'Proceed with the tool only for roles that require security clearance, where inferred data may be relevant.', 0),
(1865, 467, 1, 'Targeted outreach to women''s professional networks to increase the application pipeline.', 0),
(1866, 467, 2, 'Blind CV screening to address bias at the shortlisting stage where the drop occurs.', 1),
(1867, 467, 3, 'Requiring diverse interview panels to address bias at the final selection stage.', 0),
(1868, 467, 4, 'All three interventions simultaneously, regardless of cost.', 0),
(1869, 468, 1, '" Assessment centers are standard practice across all public sector agencies in Ghana; we must follow the norm."', 0),
(1870, 468, 2, '"The higher predictive validity of assessment centers means we are more likely to select candidates who will succeed, reducing costly turnover and performance issues in leadership roles."', 1),
(1871, 468, 3, '"I will reduce the assessment center to one day and cut the in-basket simulation to lower costs while keeping most of the validity."', 0),
(1872, 468, 4, '"Let us pilot the assessment center with five candidates first to demonstrate its value before scaling to 20."', 0),
(1873, 469, 1, 'Approve the stress interview technique for enforcement division candidates only, with a debrief after each interview to explain the technique to candidates.', 0),
(1874, 469, 2, 'Reject the stress interview technique; research shows it has low predictive validity, damages employer brand, and may expose the organization to legal claims of harassment or discrimination.', 1),
(1875, 469, 3, 'Approve a modified version where candidates are asked difficult technical questions under time pressure, but without personal aggression or prolonged silence.', 0),
(1876, 469, 4, 'Defer the decision to the Deputy Director of HR for a binding ruling on the use of stress interviews in DVLA.', 0),
(1877, 470, 1, 'Mandate a one-hour online certification for all panel members, renewable annually, with no exceptions.', 0),
(1878, 470, 2, 'Require that at least one trained panel member sit on every interview panel, and phase in full training over 12 months.', 1),
(1879, 470, 3, 'Eliminate panel interviews entirely and replace them with written assessments and work samples.', 0),
(1880, 470, 4, 'Keep the current process but add a post-hire review to track turnover rates by panel composition.', 0),
(1881, 471, 1, 'Purchase the more complex version; content validity requires matching the full complexity of the job.', 0),
(1882, 471, 2, 'Keep the simpler version but add a written component asking candidates to describe how they would handle complex transactions.', 0),
(1883, 471, 3, 'Conduct a job task analysis to identify the most critical and frequently performed financial tasks, then design a work sample that represents those tasks, even if not the most complex.', 1),
(1884, 471, 4, 'Eliminate the work sample entirely and rely on a structured interview with technical questions.', 0),
(1885, 472, 1, 'Accept the discounted offer; the cost savings justify the risk, and cognitive ability is indeed universal.', 0),
(1886, 472, 2, 'Reject the provider entirely and select a different provider that has validated tools in similar contexts.', 0),
(1887, 472, 3, 'Request that the provider conduct a localized validation study at their own expense before DVLA commits to a contract.', 1),
(1888, 472, 4, 'Proceed with the tools but add a disclaimer in the candidate report that the tools have not been validated in Ghana.', 0),
(1889, 473, 1, 'Hire an external marketing agency to create aspirational messaging based on industry trends.', 0),
(1890, 473, 2, 'Survey current employees across all levels to understand what they value about working at DVLA and what frustrates them.', 1),
(1891, 473, 3, 'Benchmark EVP statements from other public sector agencies in Ghana and adapt the most effective elements.', 0),
(1892, 473, 4, 'Conduct exit interviews with departing employees to identify why people leave, then build an EVP that addresses those gaps.', 0),
(1893, 474, 1, 'Issue a memo from the Director stating that punctuality for interviews is mandatory.', 0),
(1894, 474, 2, 'Include candidate feedback scores (including punctuality and professionalism) in line managers'' annual performance metrics.', 1),
(1895, 474, 3, 'Remove line managers from interview panels entirely and replace them with HR staff.', 0),
(1896, 474, 4, 'Schedule interviews only on days when line managers have no operational duties.', 0),
(1897, 475, 1, 'Combine the technical test, panel interview, and medical exam into a single day in Accra.', 0),
(1898, 475, 2, 'Move the technical test online using a remote proctoring platform and conduct panel interviews via video conference.', 1),
(1899, 475, 3, 'Require candidates to relocate to Accra before the interview process begins.', 0),
(1900, 475, 4, 'Eliminate the technical test entirely and rely solely on the panel interview.', 0),
(1901, 476, 1, 'Issue a public denial stating that the influencer''s account is inaccurate and unsubstantiated.', 0),
(1902, 476, 2, 'Threaten legal action for defamation to deter future negative posts.', 0),
(1903, 476, 3, 'Ignore the post; social media controversies fade within 72 hours.', 0),
(1904, 476, 4, 'Issue a public statement acknowledging the experience, apologizing, and outlining specific corrective actions being taken to improve candidate experience.', 1),
(1905, 477, 1, '"The initiative cost GHS 200,000 but saved GHS 150,000 in agency fees, so the net cost was GHS 50,000."', 0),
(1906, 477, 2, '"The initiative improved offer acceptance rates by 20 percentage points, which represents significant intangible value."', 0),
(1907, 477, 3, '"The initiative cost GHS 200,000. The quantifiable savings in agency fees alone is GHS 150,000, with additional hard-to-quantify benefits from faster hiring and better candidate experience."', 1),
(1908, 477, 4, '"The initiative was too expensive; we should revert to the previous process to save GHS 200,000 annually."', 0),
(1909, 478, 1, 'Approve the MBTI; keeping the Line Manager satisfied is more important than psychometric rigor.', 0),
(1910, 478, 2, 'Politely decline to use MBTI and offer alternatives such as a cognitive ability test and a practical coding work sample, explaining the evidence against MBTI for selection.', 1),
(1911, 478, 3, 'Allow the MBTI to be used but only as a discussion tool, not as a formal selection criterion, and document this limitation in the selection process.', 0),
(1912, 478, 4, 'Escalate the disagreement to the Director of HR for a binding decision on the use of personality assessments.', 0),
(1913, 479, 1, 'The organization will hire only candidates who are smarter than current high performers, improving overall capability.', 0),
(1914, 479, 2, 'The organization will significantly reduce the candidate pool and may have difficulty filling the role, while potentially excluding many candidates who could perform well.', 1),
(1915, 479, 3, 'The cut-off will have no effect because cognitive ability tests are not predictive of job performance.', 0),
(1916, 479, 4, 'The cut-off will increase the diversity of the candidate pool by setting a high standard that favors no particular group.', 0),
(1917, 480, 1, 'Pilot the tool immediately; AI is the future of HR, and 85% accuracy is impressive.', 0),
(1918, 480, 2, 'Reject the tool unless the vendor can provide documented evidence of validation on a diverse African sample and demonstrate compliance with the Data Protection Act regarding automated decision-making.', 1),
(1919, 480, 3, 'Pilot the tool but only for informational purposes, not for formal selection decisions.', 0),
(1920, 480, 4, 'Accept the tool but require candidates to consent in writing to the analysis.', 0),
(1921, 481, 1, 'Administer the proposed assessments to the sample of current managers and compare their scores to their performance ratings (concurrent validation).', 1),
(1922, 481, 2, 'Administer the assessments to a separate group of junior managers and track their performance after promotion (predictive validation).', 0),
(1923, 481, 3, 'Ask current senior managers to review the assessment questions and rate whether they seem relevant to their jobs (face validity).', 0),
(1924, 481, 4, 'Compare the assessment scores of senior managers to those of external candidates (known- groups validation).', 0),
(1925, 482, 1, 'Continue using the test; cognitive ability is universal and not affected by cultural references.', 0),
(1926, 482, 2, 'Request that the vendor replace the culturally specific items with neutral or locally relevant items, or select a different test that has been culturally adapted.', 1),
(1927, 482, 3, 'Administer the test as-is but provide a glossary of American terms to candidates.', 0),
(1928, 482, 4, 'Eliminate the verbal reasoning section entirely and rely only on numerical and abstract reasoning.', 0),
(1929, 483, 1, 'Targeted outreach to underrepresented communities to increase the applicant pool further.', 0),
(1930, 483, 2, 'Blind CV screening to reduce bias at the shortlisting stage where the drop-off occurs.', 1),
(1931, 483, 3, 'Mandatory DEI training for hiring managers to address bias across all stages.', 0),
(1932, 483, 4, 'All three initiatives, prorated to fit the budget.', 0),
(1933, 484, 1, 'Approve the quota policy; addressing historical underrepresentation justifies the approach.', 0),
(1934, 484, 2, 'Reject the quota policy and replace it with a "Rooney Rule" requiring diverse slates of candidates (e.g., at least one woman and one rural candidate in every shortlist) without mandating specific hiring outcomes.', 1),
(1935, 484, 3, 'Reject any diversity initiative; merit should be the only consideration in hiring.', 0),
(1936, 484, 4, 'Approve the quotas but only for entry-level roles, not for technical appointments.', 0),
(1937, 485, 1, 'Allow the local hire policy to continue; community understanding is a legitimate job requirement.', 0),
(1938, 485, 2, 'Modify the policy to require that at least 30% of hires come from outside the region to promote diversity.', 0),
(1939, 485, 3, 'Replace the local hire policy with a qualification-based assessment that includes local language fluency as a competency but does not exclude outside candidates who can learn or demonstrate equivalent skills.', 1),
(1940, 485, 4, 'Eliminate all geographic preferences; hire only based on national qualifications.', 0),
(1941, 486, 1, 'Accept the manager''s concern; team cohesion is important for productivity.', 0),
(1942, 486, 2, 'Ask the manager to identify specific, documented behavioral evidence of the candidate''s inability to adapt, rather than making assumptions based on age.', 1),
(1943, 486, 3, 'Overrule the manager and advance the candidate to the next stage.', 0),
(1944, 486, 4, 'Document the manager''s comments and remove the manager from future interview panels.', 0),
(1945, 487, 1, 'Select Firm A; the cost difference is justified by the need for a diverse slate.', 0),
(1946, 487, 2, 'Select Firm B; the hiring manager''s preference should guide the decision.', 0),
(1947, 487, 3, 'Require both firms to submit a diverse slate as a condition of engagement, then select based on overall quality and cost.', 1),
(1948, 487, 4, 'Cancel the external search and conduct the recruitment internally to control diversity outcomes.', 0),
(1949, 488, 1, 'The comprehensive annual TNA; cost is less important than accuracy.', 0),
(1950, 488, 2, 'The rolling TNA with high-risk and critical roles prioritized in year one, and lower-risk roles in subsequent years.', 1),
(1951, 488, 3, 'The reactive TNA; problems will trigger analysis when needed.', 0),
(1952, 488, 4, 'No formal TNA; rely on manager discretion for training decisions.', 0),
(1953, 489, 1, 'Increase the customer service training budget to purchase a more expensive program.', 0),
(1954, 489, 2, 'Conduct a root cause analysis to identify systemic factors (e.g., understaffing, outdated systems, lack of empowerment) that may be causing customer service issues despite training.', 1),
(1955, 489, 3, 'Eliminate customer service training entirely; it clearly does not work.', 0),
(1956, 489, 4, 'Require all customer service staff to repeat the training annually until scores improve.', 0),
(1957, 490, 1, 'Proceed with the TNA without the department head''s approval; HR has the authority.', 0),
(1958, 490, 2, 'Present the data showing TNA''s impact in other departments and offer to conduct a small pilot TNA for one team to demonstrate value.', 1),
(1959, 490, 3, 'Escalate the issue to the Director of HR to mandate the department head''s compliance.', 0),
(1960, 490, 4, 'Accept the department head''s judgment and skip TNA for that department.', 0),
(1961, 491, 1, 'Proceed with the program as designed; leadership competencies are universal.', 0),
(1962, 491, 2, 'Conduct a targeted TNA to validate which competencies are most critical for DVLA''s public sector leaders before customizing the program.', 1),
(1963, 491, 3, 'Reject the corporate competency model entirely and develop a new model from scratch.', 0),
(1964, 491, 4, 'Pilot the program with one department and evaluate outcomes before expanding.', 0),
(1965, 492, 1, 'An annual comprehensive TNA conducted at the same time each year.', 0),
(1966, 492, 2, 'A continuous TNA approach using real-time performance data, pulse surveys, and regular check-ins with managers.', 1),
(1967, 492, 3, 'A one-time comprehensive TNA conducted when the technology is fully implemented.', 0),
(1968, 492, 4, 'No TNA; rely on employees to identify their own training needs.', 0),
(1969, 493, 1, 'Competency-based model only; it delivers faster measurable results.', 0),
(1970, 493, 2, 'Experiential model only; long-term behavior change justifies the timeline.', 0),
(1971, 493, 3, 'A blended model combining competency modules with experiential projects.', 1),
(1972, 493, 4, 'Neither model; leadership cannot be developed through formal programs.', 0),
(1973, 494, 1, 'Accept the course developer''s position; examples do not affect learning outcomes.', 0),
(1974, 494, 2, 'Remove all examples from the curriculum to avoid any inclusivity concerns.', 0),
(1975, 494, 3, 'Revise the curriculum to include diverse examples reflecting Ghana''s population.', 1),
(1976, 494, 4, 'Add a disclaimer stating that examples do not represent DVLA''s hiring practices.', 0),
(1977, 495, 1, 'Assume all learners are beginners to ensure no one is left behind.', 0),
(1978, 495, 2, 'Assume all learners are experts to avoid boring advanced participants.', 0),
(1979, 495, 3, 'Use a pre-assessment and offer differentiated pathways based on results.', 1),
(1980, 495, 4, 'Provide the same training to everyone and offer remedial sessions later.', 0),
(1981, 496, 1, 'Private sector experience; technical skills transfer across sectors.', 0),
(1982, 496, 2, 'Public sector experience; understanding of government context is critical.', 0),
(1983, 496, 3, 'Lowest price; budget constraints are the primary driver.', 0),
(1984, 496, 4, 'A combination of relevant experience, quality of proposed approach, and cost.', 1),
(1985, 497, 1, 'Require all employees to complete the full four-hour training for compliance.', 0),
(1986, 497, 2, 'Exempt the eight job families from the training entirely.', 0),
(1987, 497, 3, 'Develop role-specific modules so employees complete only relevant content.', 1),
(1988, 497, 4, 'Reduce the training to one hour and cover only the most critical topics.', 0),
(1989, 498, 1, 'Teaching SMEs to memorize slides and read them without deviation.', 0),
(1990, 498, 2, 'Ensuring SMEs dress professionally and arrive on time for sessions.', 0),
(1991, 498, 3, 'Training SMEs on adult learning principles and handling difficult participants.', 1),
(1992, 498, 4, 'Requiring SMEs to have perfect technical knowledge before teaching others.', 0),
(1993, 499, 1, 'Publicly criticize the trainer in front of participants during the session.', 0),
(1994, 499, 2, 'Remove the trainer from all future training assignments immediately.', 0),
(1995, 499, 3, 'Ignore the issue because content accuracy is more important than delivery.', 0),
(1996, 499, 4, 'Use a structured observation tool and offer private coaching on engagement.', 1),
(1997, 500, 1, 'Only the start and end times for each day of the leadership offsite.', 0),
(1998, 500, 2, 'Only the names of participants and their current job titles.', 0),
(1999, 500, 3, 'Only the lunch menu and scheduled break times for both days.', 0),
(2000, 500, 4, 'Learning objectives, timed agenda, activities, debrief scripts, and contingencies.', 1),
(2001, 501, 1, 'Praise the facilitator for being entertaining; engagement is most important.', 0),
(2002, 501, 2, 'Ignore the feedback because participants do not know what they need.', 0),
(2003, 501, 3, 'Rehire the same facilitator and add more entertainment to future sessions.', 0),
(2004, 501, 4, 'Discuss feedback with facilitator and review learning objective coverage.', 1),
(2005, 502, 1, 'The facilitator''s fee is the lowest among all candidates being considered.', 0),
(2006, 502, 2, 'The facilitator is available to start the engagement immediately.', 0),
(2007, 502, 3, 'The facilitator has a colorful, modern website with client testimonials.', 0),
(2008, 502, 4, 'Demonstrated public sector experience and relevant client references.', 1),
(2009, 503, 1, 'LXPs are less expensive than traditional LMS platforms for large organizations.', 0),
(2010, 503, 2, 'LXPs focus on compliance tracking, which is our current priority.', 0),
(2011, 503, 3, 'LXPs offer personalized learning pathways and AI-driven content recommendations.', 1),
(2012, 503, 4, 'LXPs require no administrator training or ongoing maintenance support.', 0),
(2013, 504, 1, 'Ignore the data; dropout rates are normal for e-learning modules.', 0),
(2014, 504, 2, 'Lengthen the module to 60 minutes to cover more content.', 0),
(2015, 504, 3, 'Remove the module from the LMS entirely without investigation.', 0),
(2016, 504, 4, 'Investigate content, length, and engagement at the 10-minute point.', 1),
(2017, 505, 1, 'It guarantees the content will be engaging for all learners.', 0),
(2018, 505, 2, 'It guarantees the content will be cheaper than non-compliant content.', 0),
(2019, 505, 3, 'It guarantees the content will be compatible with any SCORM-compliant LMS.', 1),
(2020, 505, 4, 'It guarantees the content will be completed within one hour.', 0),
(2021, 506, 1, 'Cancel all e-learning for those offices with poor internet access.', 0),
(2022, 506, 2, 'Require staff to drive to Accra for all e-learning courses.', 0),
(2023, 506, 3, 'Use only printed training manuals sent by postal mail.', 0),
(2024, 506, 4, 'Implement offline-capable e-learning that syncs progress later.', 1),
(2025, 507, 1, 'The number of courses available in the LMS library.', 0),
(2026, 507, 2, 'The average age of employees taking e-learning courses.', 0),
(2027, 507, 3, 'The cost of developing or purchasing each e-learning course.', 1),
(2028, 507, 4, 'The names of employees who completed each e-learning course.', 0),
(2029, 508, 1, '0.33 (GHS 100,000 divided by GHS 300,000)', 0),
(2030, 508, 2, '1:1 (GHS 100,000 to GHS 100,000)', 0),
(2031, 508, 3, '2:1 (GHS 200,000 to GHS 100,000)', 0),
(2032, 508, 4, '3:1 (GHS 300,000 benefit to GHS 100,000 cost)', 1),
(2033, 509, 1, 'Smile sheet distributed at the end of the training session.', 0),
(2034, 509, 2, 'Post-test only design with no baseline measurement.', 0),
(2035, 509, 3, 'Simple pre-test and post-test with the same group.', 0),
(2036, 509, 4, 'Control group design or time series analysis with multiple measurements.', 1),
(2037, 510, 1, 'The training was effective; participants just are not applying it.', 0),
(2038, 510, 2, 'Participants enjoyed the training but did not apply it; investigate transfer barriers.', 1),
(2039, 510, 3, 'Participants are lying on their feedback forms to please the trainer.', 0),
(2040, 510, 4, 'Cancel all future training programs immediately based on these results.', 0),
(2041, 511, 1, 'A 500-page technical report with all raw data included.', 0),
(2042, 511, 2, 'A verbal summary without any visual aids or supporting documents.', 0),
(2043, 511, 3, 'Only the participant satisfaction scores from the training program.', 0),
(2044, 511, 4, 'A concise dashboard linking training to business outcomes.', 1),
(2045, 512, 1, 'The number of participants who attended each cohort.', 0),
(2046, 512, 2, 'The names of trainers who delivered each program.', 0),
(2047, 512, 3, 'The organizational results attributed to the program.', 1),
(2048, 512, 4, 'The lunch menu provided during each training session.', 0),
(2049, 513, 1, 'Copy a model from a private sector technology company.', 0),
(2050, 513, 2, 'Ask the Director to write down their personal preferences.', 0),
(2051, 513, 3, 'Use a generic model found on the internet for free.', 0),
(2052, 513, 4, 'Conduct job analysis, interviews with high performers, and stakeholder validation.', 1),
(2053, 514, 1, 'Terminate these employees immediately for low performance.', 0),
(2054, 514, 2, 'Ignore them and focus only on high-high employees.', 0),
(2055, 514, 3, 'Promote them immediately despite their low performance.', 0),
(2056, 514, 4, 'Investigate root causes of low performance and provide targeted development.', 1),
(2057, 515, 1, 'To embarrass senior leaders and assert junior staff dominance.', 0),
(2058, 515, 2, 'To replace all senior leaders with junior staff over time.', 0),
(2059, 515, 3, 'To reduce senior leaders'' salaries based on skill gaps.', 0),
(2060, 515, 4, 'To build digital fluency at senior levels while developing junior staff confidence.', 1),
(2061, 516, 1, 'No risk; succession plans should remain completely confidential.', 0),
(2062, 516, 2, 'Low risk; candidates do not need to know about their own development.', 0),
(2063, 516, 3, 'Moderate risk; candidates may be surprised by their career paths.', 0),
(2064, 516, 4, 'High risk; candidates may leave due to lack of transparent development discussions.', 1),
(2065, 517, 1, 'The one-week intensive program; shorter programs are more focused.', 0),
(2066, 517, 2, 'Neither program; leadership cannot be developed through training.', 0),
(2067, 517, 3, 'The cheapest option regardless of program design or duration.', 0),
(2068, 517, 4, 'The six-month blended program with sustained practice and coaching.', 1),
(2069, 518, 1, 'Mandatory participation for all employees regardless of interest.', 0),
(2070, 518, 2, 'A one-day training session for mentees only, not mentors.', 0),
(2071, 518, 3, 'Replacing all other development activities with mentoring.', 0),
(2072, 518, 4, 'Clear objectives, trained participants, matching guidelines, and evaluation.', 1),
(2073, 519, 1, 'Internal coaches are always more effective than external coaches.', 0),
(2074, 519, 2, 'External coaches are always less expensive than internal coaches.', 0),
(2075, 519, 3, 'External coaches cannot be trusted with confidential information.', 0),
(2076, 519, 4, 'External coaches offer impartiality and no organizational political conflicts.', 1),
(2077, 520, 1, 'Ignore the complaint; mentors have good intentions and mean well.', 0),
(2078, 520, 2, 'Publicly shame the mentor in front of all staff members.', 0),
(2079, 520, 3, 'Remove the mentee from the program without any investigation.', 0),
(2080, 520, 4, 'Investigate confidentially, provide corrective feedback, and terminate if warranted.', 1),
(2081, 521, 1, 'Coaching should never be used with underperforming employees.', 0),
(2082, 521, 2, 'Coaching replaces the need for any formal PIP documentation.', 0),
(2083, 521, 3, 'Coaching is only for high performers; underperformers should be terminated.', 0),
(2084, 521, 4, 'Coaching can support a PIP by helping develop specific skills.', 1),
(2085, 522, 1, 'Managers must have perfect performance reviews themselves.', 0),
(2086, 522, 2, 'Managers must have university degrees in psychology or counseling.', 0),
(2087, 522, 3, 'Managers must have at least 20 years of management experience.', 0),
(2088, 522, 4, 'Managers must have organizational support (time, authority, incentives) to coach.', 1)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

