INSERT INTO `Question` (`id`, `versionId`, `order`, `type`, `text`, `skillArea`, `points`) VALUES
(523, 8, 1, 'SINGLE_CHOICE', 'DVLA has 450 distinct job titles across 16 regions, many of which describe similar work. The Deputy Director of HR is considering a job architecture rationalization project. The Finance Director supports it for cost control. The Operations Director opposes it, citing "regional autonomy." The Public Services Commission has no formal requirement for standardization. What is the most strategic argument in favor of proceeding?', '1.1 Job Analysis & Role Profiling', 1.00),
(524, 8, 2, 'SINGLE_CHOICE', 'The Director of HR is reviewing DVLA''s job analysis practices. Currently, job descriptions are updated only when a role becomes vacant or an employee files a grievance. The Director is considering shifting to a scheduled review cycle (every three years for all roles). Which factor most strongly supports the scheduled review approach?', '1.1 Job Analysis & Role Profiling', 1.00),
(525, 8, 3, 'SINGLE_CHOICE', 'DVLA is introducing a competency-based job architecture to replace its traditional duty-based job descriptions. The change will affect all 3,000 employees. The Director anticipates resistance from managers who are accustomed to task-based descriptions. What is the most strategic change management approach?', '1.1 Job Analysis & Role Profiling', 1.00),
(526, 8, 4, 'SINGLE_CHOICE', 'A board member questions the value of job analysis, stating: "We have been hiring successfully for 20 years without all this paperwork. Why change now?" The Director must respond to secure continued funding for the HR department. What is the most persuasive strategic response?', '1.1 Job Analysis & Role Profiling', 1.00),
(527, 8, 5, 'SINGLE_CHOICE', 'The Deputy Director is designing a job analysis policy for DVLA. The policy must balance rigor with practical constraints. Which statement should be included as the core principle of the policy?', '1.1 Job Analysis & Role Profiling', 1.00),
(528, 8, 6, 'SINGLE_CHOICE', 'The Director of HR is presenting the annual sourcing strategy to the DVLA Executive Board. The strategy proposes transforming the talent acquisition function from a reactive administrative unit into a proactive, market-intelligent scouting unit. The Board Chair asks: "What is the business case for spending more on sourcing when we have never struggled to fill vacancies?" The Director has data showing that while vacancies are filled, time-to-fill for specialized IT roles has increased from 45 days to 120 days over three years, and the agency has lost three qualified candidates to private sector competitors who moved faster. Which response is most likely to secure board approval?', '1.2 Sourcing Strategies', 1.00),
(529, 8, 7, 'SINGLE_CHOICE', 'The Deputy Director of HR is establishing an institutional policy regarding "Talent Poaching Etiquette" for sourcing from other public service commissions and regulatory bodies within Ghana. The Legal Advisor warns that aggressive poaching could damage inter-agency relationships and lead to reciprocal poaching. The Public Services Commission has no formal policy on inter-agency mobility. The Deputy Director must balance the agency''s talent needs with maintaining collaborative relationships. Which policy principle is most appropriate?', '1.2 Sourcing Strategies', 1.00),
(530, 8, 8, 'SINGLE_CHOICE', 'DVLA is establishing a new national data center requiring an entirely new tier of tech executives with experience in large-scale government data infrastructure. The Director of HR must decide whether to build an internal executive search function or retain an elite global executive search firm. The internal HR team has strong networks in Ghanaian public sector but limited connections to international tech executives. The roles are highly sensitive and require confidentiality. The timeline is aggressive: the data center must be operational in 12 months. The budget allows for either option, but not both. What is the most strategic decision?', '1.2 Sourcing Strategies', 1.00),
(531, 8, 9, 'SINGLE_CHOICE', 'A Deputy Director conducts a governance audit of DVLA''s sourcing metrics. The audit reveals that while "Sourcing Cost" has decreased by 40% over two years, the "First-Year Retention Rate" of sourced technical staff has plummeted from 85% to 45%. The sourcing team has been using low-cost job boards and automated screening tools to reduce costs. The team leader argues that retention is an onboarding and management issue, not a sourcing issue. The Deputy Director must decide whether to intervene in the sourcing strategy. What is the most appropriate conclusion?', '1.2 Sourcing Strategies', 1.00),
(532, 8, 10, 'SINGLE_CHOICE', 'The Director of HR is forecasting DVLA''s five-year workforce capabilities and identifies a critical deficit in automation and artificial intelligence competencies. No current employees possess these skills, and the Ghanaian labor market for AI talent is extremely limited. The Director must present a sourcing policy to the Executive Board. The Finance Director proposes a "buy" strategy: hire experienced AI professionals from abroad. The Operations Director proposes a "build" strategy: upskill current IT staff through partnerships with universities. The Deputy Director proposes a "borrow" strategy: contract AI services from external providers rather than hiring. What is the most strategic long-term recommendation?', '1.2 Sourcing Strategies', 1.00),
(533, 8, 11, 'SINGLE_CHOICE', 'The Director of HR is presenting a radical overhaul of DVLA''s executive appointment process to the Board of Governors. The current process prioritizes years of tenure and seniority within the civil service. The proposed strategy shifts selection weights to "demonstrated competency and cognitive agility profiles" based on assessment center results. The Board Chair, a long-time civil servant, expresses concern that "loyalty and experience will be devalued." Two board members support the change. One board member is undecided. The Director has data showing that competency-based selection predicts executive performance with 0.55 validity, compared to 0.15 for tenure-based selection. What is the Director''s most strategic approach to gaining board approval?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(534, 8, 12, 'SINGLE_CHOICE', 'The Deputy Director of HR is designing a macro-level evaluation framework to track the long- term ROI of DVLA''s assessment tools. The current practice is to measure candidate satisfaction with the interview process (cNPS) and the number of candidates who accept offers (acceptance rate). The Deputy Director wants to add predictive metrics. The Finance Director argues that "only financial metrics matter." The Operations Director argues that "only on-the-job performance matters." The Deputy Director must propose a balanced framework. Which set of metrics best represents the long-term business impact of a selection system?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(535, 8, 13, 'SINGLE_CHOICE', 'Following a major corporate governance failure in a parallel state enterprise where a senior leader was appointed without rigorous integrity screening, the Director of HR mandates the integration of "Integrity and Ethical Leadership Simulations" into the selection matrix for all Deputy Director positions. The simulations present realistic regulatory dilemmas where candidates must choose between following the letter of the law, following their supervisor''s directive, or taking actions that benefit the public. The Director of Operations argues that these simulations will "offend senior candidates who have years of unblemished service." The Legal Advisor supports the mandate. What is the Director''s most strategic response to the Operations Director''s concern?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(536, 8, 14, 'SINGLE_CHOICE', 'The Public Services Commission (PSC) queries DVLA regarding potential adverse impact against candidates from under-resourced regional backgrounds in its technical selection tracks. The data shows that candidates from rural regions pass the cognitive ability test at a rate of 30%, compared to 60% for candidates from urban regions. The test vendor argues that the test is valid and that the disparity reflects genuine differences in preparedness. The Deputy Director of HR must respond to the PSC. What is the most appropriate and defensible response?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(537, 8, 15, 'SINGLE_CHOICE', 'In a volatile economic and regulatory landscape, the Director of HR must ensure that candidate assessment frameworks remain future-proof. The current assessment focuses on technical knowledge of existing vehicle registration laws and procedures. The Director anticipates that these laws will change significantly within three years due to digital transformation and new regional trade agreements. The Director must decide whether to revise the assessment framework now or wait until the changes occur. What is the most strategic decision?', '1.3 Candidate Assessment & Interviewing Techniques', 1.00),
(538, 8, 16, 'SINGLE_CHOICE', 'The Director of HR wants to align DVLA''s long-term talent strategy with national civil service reforms that emphasize digital transformation. The Director proposes positioning DVLA''s EVP to attract top-tier Ghanaian diaspora talent with experience in technology and data infrastructure. The Board Chair is concerned that diaspora talent will demand salaries far above public sector scales. The Finance Director supports the initiative if costs are contained. The Director has limited budget for recruitment marketing. What is the most strategic way to position the EVP for this audience?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(539, 8, 17, 'SINGLE_CHOICE', 'The Deputy Director of HR is reviewing governance metrics of DVLA''s talent acquisition framework. The data shows exceptional "Cost-per-Hire" reduction (down 40%) but an internal audit reveals that "Quality of Hire" (measured by first-year performance ratings) has degraded significantly. The recruitment team achieved cost savings by consolidating job boards and reducing candidate communication. The team leader argues that "we met our cost target; quality is a performance management issue." What is the most appropriate executive directive?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(540, 8, 18, 'SINGLE_CHOICE', 'From a macro-organizational risk perspective, the Director of HR wants to elevate "Candidate Experience" to a formal risk management category subject to board review. The Director of Operations argues that candidate experience is "soft HR work" with no measurable business impact. The Director of Finance is neutral. The Director of HR must present a business case. Which argument is most likely to persuade the board?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(541, 8, 19, 'SINGLE_CHOICE', 'The Director of HR is designing a long-term "Internal Employer Branding Policy." The policy aims to align internal HR policies, career development pathways, leadership behaviors, and recognition systems with DVLA''s external brand promise of being "a great place to work where employees can grow." A review of exit interviews shows that 40% of departing employees cite "lack of career advancement" as the primary reason for leaving, despite DVLA''s external messaging promoting advancement opportunities. What is the most strategic first step?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(542, 8, 20, 'SINGLE_CHOICE', 'The Director of HR is reporting to the Chief Executive on the strategic health of DVLA''s talent ecosystem. The Director must present a consolidated view of employer brand health. Which portfolio of indicators provides the most balanced and predictive assessment?', '1.4 Employer Branding & Candidate Experience Management', 1.00),
(543, 8, 21, 'SINGLE_CHOICE', 'The Director of HR is designing a macro-level "Talent Assessment Governance Policy" for DVLA. The policy will govern which selection tools can be used for different role levels. The Legal Advisor warns that using unvalidated tools could expose DVLA to discrimination claims. The Operations Director argues that "any assessment is better than no assessment." The Finance Director is concerned about the cost of validation studies. The Director must balance legal risk, cost, and selection accuracy. Which policy mandate is most appropriate?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(544, 8, 22, 'SINGLE_CHOICE', 'The Deputy Director of HR is analyzing the "Utility Analysis" (Return on Investment) of DVLA''s psychometric testing suite. The suite costs GHS 500,000 annually to administer. The Deputy Director wants to calculate the financial value of using the tests compared to random selection. The following data is available: the validity coefficient of the test battery (r=0.45), the base rate of successful performance (60%), the selection ratio (1 in 5 candidates selected), the standard deviation of job performance value (SDy = GHS 200,000), and the cost of testing per candidate. Which additional variable is most critical to complete the utility analysis?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(545, 8, 23, 'SINGLE_CHOICE', 'The Director of HR introduces "Cognitive Complexity and Learning Agility Metrics" to select candidates for DVLA''s digital conversion task forces. These task forces will redesign vehicle licensing processes for a fully digital environment over the next three years. The current selection process for task forces prioritizes technical knowledge of existing systems. The Director of IT supports the change. The Director of Operations opposes it, arguing that "we need people who know how things work now, not people who learn fast." The Director of HR must defend the new approach. What is the most strategic justification?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(546, 8, 24, 'SINGLE_CHOICE', 'DVLA is accused by an external labor advocacy group of using psychometric tools that discriminate against candidates from under-resourced regional educational backgrounds. The group provides data showing that candidates from rural regions score 25% lower on the verbal reasoning section than candidates from urban regions, despite similar performance on a practical work sample. The Deputy Director of HR must respond to the Public Services Commission. What is the most appropriate and defensible response?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(547, 8, 25, 'SINGLE_CHOICE', 'The Director of HR is considering how to manage the relationship between "Psychometric Selection Data" and "Long-term Institutional Capability Development." Currently, psychometric profiles of hired candidates are archived after onboarding and never used again. The Director proposes integrating these profiles into the Learning & Development framework to personalize development plans. The Legal Advisor raises concerns about data privacy under Act 843. The Director of Learning supports the proposal. What is the most appropriate way to proceed?', '1.5 Selection Tools & Psychometric Testing', 1.00),
(548, 8, 26, 'SINGLE_CHOICE', 'The Director of HR is defending DVLA''s modernized DEI hiring framework before the Parliamentary Oversight Committee on Public Appointments. A committee member argues: "DEI initiatives lower standards and prioritize identity over merit. Public appointments should be based solely on who is most qualified." The Director must respond. What is the most robust, governance-aligned response?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(549, 8, 27, 'SINGLE_CHOICE', 'The Deputy Director of HR is conducting a macro-governance review of DVLA''s leadership succession planning. The review reveals a complete absence of female representation at the Director and Deputy Director levels across all technical divisions (e.g., Engineering, IT , Vehicle Inspection). The Deputy Director has identified a pipeline of qualified female candidates at the manager level who have been overlooked for promotion for the past five years. What is the most appropriate strategic intervention?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(550, 8, 28, 'SINGLE_CHOICE', 'The Director of HR is aligning DVLA''s talent acquisition policies with Article 24 of the Constitution of Ghana and the Ghana Labour Act, 2003 (Act 651) regarding equal opportunities. The Legal Advisor confirms that these frameworks prohibit discrimination based on gender, race, ethnic origin, religion, creed, or social/economic status. Currently, different regional offices have different hiring practices. Some offices require candidates to provide photographs with their applications. Others ask about candidates'' ethnic origins. The Director must issue a compliance directive. Which directive is most appropriate?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(551, 8, 29, 'SINGLE_CHOICE', 'The Director of HR is reviewing macro-talent forecasting models. The data indicates that rapid climate shifts and technological transitions will require DVLA to completely re-engineer its field enforcement methodologies over the next decade. The Director is concerned that the current workforce lacks cognitive diversity - employees tend to have similar educational backgrounds, problem-solving approaches, and regional origins. How does a diverse and inclusive talent acquisition strategy mitigate this long-term risk?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(552, 8, 30, 'SINGLE_CHOICE', 'During an executive board meeting, a director argues: "Tracking diversity and inclusion metrics is a waste of corporate resources. Our job is to register vehicles and enforce traffic laws, not engage in social experiments. These metrics contribute nothing to vehicle licensing operations." The Director of HR must respond. What is the most persuasive evidence-based counter- argument?', '1.6 Diversity, Equity & Inclusion (DEI) Hiring Practices', 1.00),
(553, 8, 31, 'SINGLE_CHOICE', 'The Director of HR is establishing a TNA governance policy for DVLA. The policy will apply to all 3,000 employees across 16 regions. The Legal Advisor recommends documenting all TNA decisions to defend against potential claims that training was inadequate. The Operations Director argues that documentation is bureaucratic and unnecessary. The Director must balance legal risk and operational efficiency. Which policy mandate is most appropriate?', '2.1 Training Needs Analysis (TNA)', 1.00),
(554, 8, 32, 'SINGLE_CHOICE', 'The Deputy Director of HR is reviewing TNA data from across DVLA. The data shows that the Northern Region consistently reports higher training needs than the Southern Region for identical roles. The Deputy Director investigates and finds that the Northern Region manager has a pattern of recommending training for every performance issue, while the Southern Region manager first attempts coaching and process improvements. What is the most appropriate conclusion?', '2.1 Training Needs Analysis (TNA)', 1.00),
(555, 8, 33, 'SINGLE_CHOICE', 'DVLA is implementing a new HRIS that will automate TNA data collection. The system can pull data from performance reviews, employee surveys, and training records to identify gaps. The Director of HR must decide whether to rely on automated TNA or continue conducting manual TNAs. The IT Director supports automation for efficiency. The Learning Director is concerned about the quality of automated analysis. What is the most appropriate decision?', '2.1 Training Needs Analysis (TNA)', 1.00),
(556, 8, 34, 'SINGLE_CHOICE', 'The Director of HR is presenting the annual training budget to the Executive Board. The budget is based on a TNA conducted six months ago. A board member asks: "How do we know these training needs are still valid? The organization has changed significantly in six months." The Director must respond. What is the most credible response?', '2.1 Training Needs Analysis (TNA)', 1.00),
(557, 8, 35, 'SINGLE_CHOICE', 'The Director of HR is benchmarking DVLA''s TNA maturity against international public sector standards. The current practice is reactive: training is delivered only when performance problems are identified. The Director wants to move to a proactive, strategic TNA model. Which capability is most critical to enable this shift?', '2.1 Training Needs Analysis (TNA)', 1.00),
(558, 8, 36, 'SINGLE_CHOICE', 'The Director of HR is establishing an instructional design governance policy for DVLA. The policy will govern how training materials are developed and approved. The Legal Advisor recommends a formal review process. The Operations Director argues that formal review delays training delivery. The Director must balance quality and speed. Which policy mandate is most appropriate?', '2.2 Instructional Design & Curriculum Development', 1.00),
(559, 8, 37, 'SINGLE_CHOICE', 'The Director of HR is reviewing DVLA''s training curriculum against the 70-20-10 model. Current spending is 80% on formal training, 15% on social learning, and 5% on experiential learning. The Director wants to align with the model. What is the most strategic recommendation?', '2.2 Instructional Design & Curriculum Development', 1.00),
(560, 8, 38, 'SINGLE_CHOICE', 'DVLA has invested GHS 2 million in a new Learning Management System (LMS). The current curriculum consists of PowerPoint files uploaded from classroom training. The Director of Learning wants to redesign courses for the digital medium. The Director of IT wants to prioritize system integration. The Director of HR must decide the strategic priority. What is the most appropriate decision?', '2.2 Instructional Design & Curriculum Development', 1.00),
(561, 8, 39, 'SINGLE_CHOICE', 'A board member asks why DVLA cannot simply purchase off-the-shelf training courses instead of developing custom curricula. The Director of HR must respond. Off-the-shelf courses are cheaper and faster to deploy. Custom curricula better address DVLA''s specific regulatory context. What is the most credible response?', '2.2 Instructional Design & Curriculum Development', 1.00),
(562, 8, 40, 'SINGLE_CHOICE', 'The Director of HR is evaluating the effectiveness of DVLA''s curriculum development process. A recent leadership curriculum received excellent participant satisfaction scores (4.8/5) but showed no improvement in leadership behaviors six months later. What is the most appropriate conclusion?', '2.2 Instructional Design & Curriculum Development', 1.00),
(563, 8, 41, 'SINGLE_CHOICE', 'The Director of HR is establishing a facilitation standards policy for internal trainers. The Legal Advisor recommends certification requirements. The Operations Director argues that certification will reduce trainer availability. What is the most appropriate policy?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(564, 8, 42, 'SINGLE_CHOICE', 'A Deputy Director reviews training delivery metrics and finds a trainer with poor participant ratings but strong technical expertise. The trainer''s manager defends them based on content knowledge. What is the most appropriate action?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(565, 8, 43, 'SINGLE_CHOICE', 'DVLA is scaling training delivery across 16 regional offices. The Director must choose a delivery strategy. What balances cost, consistency, and quality best?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(566, 8, 44, 'SINGLE_CHOICE', 'A board member suggests all DVLA training should be delivered online to save costs. The Director must respond. Online delivery reduces costs but may not suit all content types. What is the most appropriate response?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(567, 8, 45, 'SINGLE_CHOICE', 'The Director is benchmarking DVLA''s facilitation quality against international standards. What is the most meaningful benchmark indicator?', '2.3 Learning Program Delivery & Facilitation', 1.00),
(568, 8, 46, 'SINGLE_CHOICE', 'The Director of HR is establishing a digital learning strategy for DVLA. The strategy must serve 3,000 employees across 16 regions. Which foundational element is most critical?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(569, 8, 47, 'SINGLE_CHOICE', 'A Deputy Director is evaluating whether to build or buy an LMS. Which factor should most influence this decision?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(570, 8, 48, 'SINGLE_CHOICE', 'DVLA has multiple learning platforms that do not integrate with each other. What is the most significant strategic risk of this fragmentation?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(571, 8, 49, 'SINGLE_CHOICE', 'A board member asks for the ROI of DVLA''s e-learning investments. What is the most appropriate way for the Director to respond?', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(572, 8, 50, 'SINGLE_CHOICE', 'The Director is benchmarking DVLA''s digital learning maturity against international standards. At the highest maturity level, digital learning should be:', '2.4 E-learning & Digital Learning Platform Management', 1.00),
(573, 8, 51, 'SINGLE_CHOICE', 'The Director of HR is establishing a learning evaluation governance policy. What should this policy mandate for significant learning investments?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(574, 8, 52, 'SINGLE_CHOICE', 'A Deputy Director reviews five years of Level 1 data showing excellent scores but no improvement in organizational performance. What strategic conclusion should be drawn?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(575, 8, 53, 'SINGLE_CHOICE', 'DVLA spends GHS 2 million annually on training. The Board questions the return on this investment. How should the Director respond?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(576, 8, 54, 'SINGLE_CHOICE', 'A Deputy Director is benchmarking DVLA''s learning evaluation against the Kirkpatrick-Phillips framework. At the highest maturity level, evaluation should be:', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(577, 8, 55, 'SINGLE_CHOICE', 'The Director wants to build internal capability for ROI evaluation. What is the most effective approach?', '2.5 Learning Evaluation (Kirkpatrick Model, ROI Measurement)', 1.00),
(578, 8, 56, 'SINGLE_CHOICE', 'The Director of HR is establishing a succession governance policy. What should this policy mandate for critical roles?', '2.6 Leadership Development & Succession Planning', 1.00),
(579, 8, 57, 'SINGLE_CHOICE', 'A Deputy Director reviews executive succession pipelines and finds all candidates for Director roles are over 55. What strategic risk does this present?', '2.6 Leadership Development & Succession Planning', 1.00),
(580, 8, 58, 'SINGLE_CHOICE', 'DVLA is about to lose 40% of senior engineers to retirement within 3 years. What strategic succession initiative should the Director approve?', '2.6 Leadership Development & Succession Planning', 1.00),
(581, 8, 59, 'SINGLE_CHOICE', 'A board member questions whether leadership development is worth the investment, noting that some trained leaders leave DVLA. How should the Director respond?', '2.6 Leadership Development & Succession Planning', 1.00),
(582, 8, 60, 'SINGLE_CHOICE', 'The Director is benchmarking DVLA''s leadership development against the 70-20-10 model. At the highest maturity level, the ratio should be approximately:', '2.6 Leadership Development & Succession Planning', 1.00),
(583, 8, 61, 'SINGLE_CHOICE', 'The Director of HR is establishing a coaching and mentoring governance policy. What should this policy include?', '2.7 Coaching and Mentoring Program Design', 1.00),
(584, 8, 62, 'SINGLE_CHOICE', 'A Deputy Director reviews the coaching program and finds 80% of sessions are cancelled or rescheduled. What systemic issue is likely?', '2.7 Coaching and Mentoring Program Design', 1.00),
(585, 8, 63, 'SINGLE_CHOICE', 'DVLA is considering investing in professional coach certification for internal HR staff. What should the Director consider before approving the budget?', '2.7 Coaching and Mentoring Program Design', 1.00),
(586, 8, 64, 'SINGLE_CHOICE', 'A board member suggests that mentoring is a waste of time because people learn best on their own. How should the Director respond?', '2.7 Coaching and Mentoring Program Design', 1.00),
(587, 8, 65, 'SINGLE_CHOICE', 'The Director is benchmarking DVLA''s coaching culture against international best practice. At the highest maturity level, coaching should be:', '2.7 Coaching and Mentoring Program Design', 1.00)
ON DUPLICATE KEY UPDATE `text` = VALUES(`text`);

INSERT INTO `AnswerOption` (`id`, `questionId`, `order`, `text`, `isCorrect`) VALUES
(2089, 523, 1, 'Standardization will reduce the administrative burden of managing 450 unique job descriptions.', 0),
(2090, 523, 2, 'The Public Services Commission may eventually require standardization, so DVLA should get ahead of the mandate.', 0),
(2091, 523, 3, 'Without standardized job architecture, DVLA cannot conduct equitable pay analysis, identify career progression pathways, or perform meaningful workforce analytics.', 1),
(2092, 523, 4, 'Standardization will allow DVLA to reduce headcount by identifying duplicate roles across regions.', 0),
(2093, 524, 1, 'Scheduled reviews are more expensive but demonstrate compliance with international standards.', 0),
(2094, 524, 2, 'Roles change incrementally over time; waiting for a vacancy may result in job descriptions that no longer reflect actual duties, creating performance management and legal risks.', 1),
(2095, 524, 3, 'The Public Services Commission mandates scheduled reviews for all public sector agencies in Ghana.', 0),
(2096, 524, 4, 'Scheduled reviews will reduce the total number of job descriptions that need to be maintained.', 0),
(2097, 525, 1, 'Mandate the new competency-based architecture for all new hires only, leaving existing employees on the old system.', 0),
(2098, 525, 2, 'Pilot the competency-based architecture in one department first, gather data on outcomes, and use the results to refine the approach before scaling.', 1),
(2099, 525, 3, 'Implement the new architecture across all departments simultaneously to avoid creating a two-tier system.', 0),
(2100, 525, 4, 'Allow each department to choose whether to adopt competency-based or duty-based descriptions.', 0),
(2101, 526, 1, '"The Labour Act now requires job analysis documentation that was not required 20 years ago."', 0),
(2102, 526, 2, '"Job analysis reduces our legal risk by documenting that our hiring criteria are job-related and non-discriminatory."', 1),
(2103, 526, 3, '"Other public sector agencies have adopted job analysis, and we must keep pace with peers."', 0),
(2104, 526, 4, '"The Public Services Commission has placed DVLA on a watchlist for non-compliance with job analysis requirements."', 0),
(2105, 527, 1, 'Job analysis shall be conducted for every role every two years, using a standardized survey instrument administered by the HR department.', 0),
(2106, 527, 2, 'Job analysis shall be conducted for new roles and for existing roles when significant changes occur, using methods appropriate to the role''s complexity and organizational impact.', 1),
(2107, 527, 3, 'Job analysis shall be conducted by external consultants for all roles at Manager level and above to ensure objectivity.', 0),
(2108, 527, 4, 'Job analysis shall be conducted only when a role becomes vacant or when an employee files a formal grievance about their job description.', 0),
(2109, 528, 1, '"Public sector agencies across Ghana are adopting proactive sourcing. We must keep pace with our peers to remain competitive."', 0),
(2110, 528, 2, '"The increased time-to-fill for IT roles creates operational risks. Each day a cybersecurity role remains vacant increases our vulnerability to system breaches."', 1),
(2111, 528, 3, '"The proposed changes will not increase the budget; we will reallocate existing funds from less effective channels."', 0),
(2112, 528, 4, '"I will provide a detailed return on investment calculation showing payback within 18 months."', 0),
(2113, 529, 1, 'A total ban on hiring from other public sector agencies to avoid any conflict.', 0),
(2114, 529, 2, 'Encouraging aggressive, uncoordinated sourcing to secure the best talent regardless of source.', 0),
(2115, 529, 3, 'A permissive policy with no restrictions, allowing managers to source from any agency as needed.', 0),
(2116, 529, 4, 'A transparent, merit-based mobility framework that respects cross-agency postings and includes advance notification protocols with sister agencies.', 1),
(2117, 530, 1, 'Build the internal search function to develop long-term capability and reduce dependency on external firms.', 0),
(2118, 530, 2, 'Retain an elite global search firm for this critical, confidential, and time-sensitive search, while documenting the process for future internal capability building.', 1),
(2119, 530, 3, 'Split the roles: use internal search for mid-level tech roles and external search for the executive director role only.', 0),
(2120, 530, 4, 'Delay the data center launch by six months to allow the internal team to develop the necessary executive networks.', 0),
(2121, 531, 1, 'The sourcing team has met its cost-reduction target; retention issues should be addressed by the Learning and Development department.', 0),
(2122, 531, 2, 'The decrease in retention suggests that low-cost sourcing channels may be attracting candidates who are a poor fit for DVLA culture or technical requirements. The sourcing strategy should be re-evaluated.', 1),
(2123, 531, 3, 'The retention rate is within acceptable range for technical roles; no action is needed.', 0),
(2124, 531, 4, 'The Deputy Director should wait for another year of data before drawing conclusions.', 0),
(2125, 532, 1, 'The "buy" strategy; experienced talent can implement solutions faster.', 0),
(2126, 532, 2, 'The "build" strategy; internal development is more sustainable and cost-effective over time.', 0),
(2127, 532, 3, 'The "borrow" strategy; contracting avoids permanent headcount and benefits costs.', 0),
(2128, 532, 4, 'A dual "build and buy" strategy: hire a small number of experienced AI leads while simultaneously upskilling internal staff and establishing university partnerships.', 1),
(2129, 533, 1, 'Present the validity data and offer to pilot the new process for one executive appointment while keeping the tenure-based process for others.', 1),
(2130, 533, 2, 'Withdraw the proposal and return with a compromise that weights both tenure and competency equally.', 0),
(2131, 533, 3, 'Proceed with the new process despite board concerns; the Director has delegated authority for HR processes.', 0),
(2132, 533, 4, 'Commission an external consultant to conduct a study on executive selection best practices before bringing any proposal back to the board.', 0),
(2133, 534, 1, 'Candidate satisfaction scores and offer acceptance rates only.', 0),
(2134, 534, 2, 'Cost-per-hire and time-to-fill only.', 0),
(2135, 534, 3, 'The statistical correlation between assessment scores and subsequent job performance, retention rates, and promotion velocity, adjusted for the cost of the assessment tools.', 1),
(2136, 534, 4, 'The number of candidates who pass the assessment and the number of hires made each quarter.', 0),
(2137, 535, 1, 'Remove the simulations for candidates with more than 15 years of service; they have already proven their integrity.', 0),
(2138, 535, 2, 'Keep the simulations but make them optional for candidates who object to participating.', 0),
(2139, 535, 3, 'Keep the simulations and explain that integrity is assessed for all candidates regardless of tenure, and that the simulations are designed to evaluate judgment, not to accuse anyone of past misconduct.', 1),
(2140, 535, 4, 'Replace the simulations with a written ethics exam that is less intrusive for senior candidates.', 0),
(2141, 536, 1, 'Accept the vendor''s position; the test is valid, and the disparity is not DVLA''s responsibility.', 0),
(2142, 536, 2, 'Immediately suspend the use of the cognitive ability test pending further investigation.', 0),
(2143, 536, 3, 'Conduct a differential item functioning (DIF) analysis to determine whether specific test items are biased against rural candidates, and if so, replace or modify those items.', 1),
(2144, 536, 4, 'Add points to the scores of rural candidates to equalize the pass rate to 60%.', 0),
(2145, 537, 1, 'Keep the current assessment focused on existing laws; candidates can learn new laws after hire.', 0),
(2146, 537, 2, 'Revise the assessment to prioritize "learning agility" - the ability to learn new information quickly and adapt to change - while reducing weight on current technical knowledge.', 1),
(2147, 537, 3, 'Eliminate the assessment entirely and rely on probationary periods to evaluate candidates after hire.', 0),
(2148, 537, 4, 'Wait until the new laws are enacted, then revise the assessment at that time.', 0),
(2149, 538, 1, 'Offer diaspora talent a separate, higher salary scale approved by the Ministry of Finance.', 0),
(2150, 538, 2, 'Focus the EVP on non-financial value: the opportunity to engineer national-scale digital infrastructure and contribute to Ghana''s development, supplemented by reasonable relocation support.', 1),
(2151, 538, 3, 'Target only diaspora talent who are willing to accept standard public sector salaries without additional incentives.', 0),
(2152, 538, 4, 'Abandon the diaspora focus and recruit locally to avoid salary complications.', 0),
(2153, 539, 1, 'Praise the recruitment team for achieving the cost target and direct the performance management team to address quality issues.', 0),
(2154, 539, 2, 'Mandate that the recruitment scorecard be rebalanced to give equal weight to Cost-per-Hire, Quality of Hire, and Candidate Experience metrics, with regular review by the Deputy Director.', 1),
(2155, 539, 3, 'Return to the previous, more expensive sourcing channels that produced higher quality hires.', 0),
(2156, 539, 4, 'Reduce the cost target further to incentivize additional savings.', 0),
(2157, 540, 1, '"Poor candidate experience damages DVLA''s employer brand, making it harder to attract qualified candidates for critical roles, which directly affects our ability to fulfill our statutory mandate."', 1),
(2158, 540, 2, '"Candidate experience surveys are required by the Public Services Commission as part of our annual compliance audit."', 0),
(2159, 540, 3, '"Competing public sector agencies have better candidate experience scores than DVLA, which creates a competitive disadvantage."', 0),
(2160, 540, 4, '"Improving candidate experience reduces the number of grievances filed by rejected candidates, saving HR time."', 0),
(2161, 541, 1, 'Remove "career advancement" from DVLA''s external brand messaging until internal pathways are improved.', 0),
(2162, 541, 2, 'Launch a new external branding campaign emphasizing other benefits, such as job security and pension.', 0),
(2163, 541, 3, 'Conduct an internal audit of career development pathways, promotion rates, and employee perceptions, then implement improvements before updating external messaging.', 1),
(2164, 541, 4, 'Require managers to discuss career advancement with each employee during quarterly check-ins, without changing actual promotion processes.', 0),
(2165, 542, 1, 'Candidate Net Promoter Score (cNPS) and offer acceptance rate.', 0),
(2166, 542, 2, 'Employee Glassdoor rating and internal engagement survey results.', 0),
(2167, 542, 3, 'Candidate Net Promoter Score (cNPS), Employee Glassdoor/Internal survey ratings, Offer Acceptance Rates (OAR), and Talent Pipeline Velocity trends.', 1),
(2168, 542, 4, 'Number of applications received per vacancy and average time-to-fill.', 0),
(2169, 543, 1, 'Any selection tool may be used as long as candidates are informed of its limitations.', 0),
(2170, 543, 2, 'Only tools that have documented empirical evidence of reliability, job-related validity, and freedom from adverse impact may be used for final selection decisions.', 1),
(2171, 543, 3, 'Validation studies are required only for tools used for executive-level selections.', 0),
(2172, 543, 4, 'External vendor validation is acceptable without internal review for all tools.', 0),
(2173, 544, 1, 'The number of HR staff who administer the tests.', 0),
(2174, 544, 2, 'The number of candidates who refuse to take the tests.', 0),
(2175, 544, 3, 'The average tenure of employees selected using the tests.', 0),
(2176, 544, 4, 'The total number of candidates assessed annually.', 1),
(2177, 545, 1, '"Technical knowledge of current systems becomes obsolete as we digitize. Learning agility predicts the ability to master new systems, which is more valuable than existing knowledge in a transformation context."', 1),
(2178, 545, 2, '"Cognitive complexity metrics are easier to administer than technical knowledge tests."', 0),
(2179, 545, 3, '"The Public Services Commission requires learning agility assessments for all digital transformation roles."', 0),
(2180, 545, 4, '"Candidates with high learning agility cost less to hire than technical experts."', 0),
(2181, 546, 1, 'Defend the test as valid and argue that the disparity reflects genuine differences in preparedness.', 0),
(2182, 546, 2, 'Immediately suspend the verbal reasoning section pending a differential item functioning (DIF) analysis to identify potentially biased items.', 1),
(2183, 546, 3, 'Eliminate all psychometric testing and rely solely on work samples and interviews.', 0),
(2184, 546, 4, 'Add points to the scores of candidates from rural regions to equalize pass rates.', 0),
(2185, 547, 1, 'Proceed with the integration; employee development data is a legitimate use of selection data.', 0),
(2186, 547, 2, 'Do not proceed; psychometric data should only be used for selection, not for development, due to privacy concerns.', 0),
(2187, 547, 3, 'Obtain explicit consent from employees at the time of hire to use their psychometric data for development purposes, and provide an opt-out option.', 1),
(2188, 547, 4, 'Anonymize the psychometric data before sharing with Learning & Development to protect individual privacy.', 0),
(2189, 548, 1, '"DEI initiatives do not lower standards; they expand the talent pool by removing arbitrary barriers so that we can select the most qualified candidates from a broader range of backgrounds."', 1),
(2190, 548, 2, '"The Committee is welcome to review our data showing that performance outcomes have improved since implementing DEI initiatives."', 0),
(2191, 548, 3, '"The Constitution of Ghana guarantees equal opportunity. We are simply complying with the law."', 0),
(2192, 548, 4, '"If the Committee prefers, we can provide examples of qualified candidates who were previously excluded due to unconscious bias."', 0),
(2193, 549, 1, 'Mandate that the next three Director-level vacancies in technical divisions be filled by women.', 0),
(2194, 549, 2, 'Establish a formal "Executive Diversity Leadership Accelerator" with targeted mentorship, sponsorship, and development for high-potential female managers, and require diverse slates for all senior vacancies.', 1),
(2195, 549, 3, 'Conduct an external search for female directors to bypass the internal pipeline.', 0),
(2196, 549, 4, 'Take no action; the disparity may resolve itself over time as more women enter technical fields.', 0),
(2197, 550, 1, 'Allow each regional office to continue its current practices as long as they are locally appropriate.', 0),
(2198, 550, 2, 'Mandate that all regional offices adopt a standardized, legally vetted application process that prohibits collection of demographic data not directly job-related.', 1),
(2199, 550, 3, 'Require that all application materials be reviewed by the Legal Advisor before any hiring decision.', 0),
(2200, 550, 4, 'Eliminate all application forms and rely solely on interviews conducted by trained panels.', 0),
(2201, 551, 1, 'Diverse teams are statistically more innovative and better at complex problem-solving than homogenous teams, which will help DVLA adapt to unprecedented challenges.', 1),
(2202, 551, 2, 'Diversity initiatives improve public perception, which is important for regulatory agencies.', 0),
(2203, 551, 3, 'The Public Services Commission requires diversity metrics regardless of business case.', 0),
(2204, 551, 4, 'Diverse teams are easier to manage because they bring different perspectives.', 0),
(2205, 552, 1, '"Diversity metrics are required by the Public Services Commission; non-compliance could affect our budget allocation."', 0),
(2206, 552, 2, '"Inclusive hiring reduces legal risk by identifying potential discrimination claims early, lowers turnover costs, and improves problem-solving in enforcement operations."', 1),
(2207, 552, 3, '"I will prepare a report showing the correlation between diversity and customer satisfaction scores."', 0),
(2208, 552, 4, '"If you disagree, I can invite you to attend our next unconscious bias training session."', 0),
(2209, 553, 1, 'TNA documentation is optional and at the discretion of each department head.', 0),
(2210, 553, 2, 'TNA documentation is required for mandatory safety and compliance training only; other training decisions may be documented informally.', 0),
(2211, 553, 3, 'TNA documentation is required for all training investments exceeding GHS 50,000 and for all compliance-related training, with a standardized template.', 1),
(2212, 553, 4, 'No TNA documentation is required; verbal approvals are sufficient.', 0),
(2213, 554, 1, 'The Northern Region has genuinely higher training needs; allocate more training budget there.', 0),
(2214, 554, 2, 'The Southern Region is underreporting training needs; require them to conduct more thorough TNAs.', 0),
(2215, 554, 3, 'The TNA data may reflect different manager philosophies rather than genuine differences in training needs. Calibration of TNA practices across regions is needed.', 1),
(2216, 554, 4, 'Training is not effective; eliminate TNA and focus on hiring only.', 0),
(2217, 555, 1, 'Rely solely on automated TNA; it is more efficient and less biased than manual methods.', 0),
(2218, 555, 2, 'Continue with manual TNAs only; automation cannot capture nuanced training needs.', 0),
(2219, 555, 3, 'Use automated TNA as a screening tool to identify potential gaps, then validate findings with targeted manual follow-up for high-risk areas.', 1),
(2220, 555, 4, 'Defer the decision for two years until the automation technology matures.', 0),
(2221, 556, 1, '"Training needs are stable over time; six months is not a significant change period."', 0),
(2222, 556, 2, '"We have a process for validating TNA findings with department heads quarterly. I can present the most recent validation data to the board."', 1),
(2223, 556, 3, '"If the board is concerned, we can cancel all planned training and conduct a new TNA before proceeding."', 0),
(2224, 556, 4, '"The TNA is a legal requirement; validity is not a factor in budget approval."', 0),
(2225, 557, 1, 'A larger training budget to fund proactive initiatives.', 0),
(2226, 557, 2, 'Integration of TNA with strategic workforce planning, performance data analytics, and regular stakeholder feedback loops.', 1),
(2227, 557, 3, 'Outsourcing TNA to an external consultant with private sector experience.', 0),
(2228, 557, 4, 'Mandating that all employees complete an annual self-assessment of training needs.', 0),
(2229, 558, 1, 'No formal review; any employee may develop and deliver training without approval.', 0),
(2230, 558, 2, 'Formal review only for training with budgets exceeding GHS 100,000.', 0),
(2231, 558, 3, 'A tiered review process based on training risk and investment level.', 1),
(2232, 558, 4, 'All training must be outsourced to external vendors with pre-approved materials.', 0),
(2233, 559, 1, 'Maintain the current ratio; formal training is most effective for compliance.', 0),
(2234, 559, 2, 'Shift to 70% experiential, 20% social, 10% formal to match the model.', 0),
(2235, 559, 3, 'Maintain formal training but add structured assignments and peer coaching.', 1),
(2236, 559, 4, 'Eliminate formal training entirely and rely only on on-the-job learning.', 0),
(2237, 560, 1, 'Upload existing PowerPoint files; content is more important than medium.', 0),
(2238, 560, 2, 'Prioritize system integration before redesigning any course content.', 0),
(2239, 560, 3, 'Redesign high-priority courses for digital delivery before full LMS launch.', 1),
(2240, 560, 4, 'Delay LMS implementation until all courses are redesigned for the platform.', 0),
(2241, 561, 1, '"Off-the-shelf courses are sufficient for most of our training needs."', 0),
(2242, 561, 2, '"We will switch to off-the-shelf courses to reduce costs immediately."', 0),
(2243, 561, 3, '"We use off-the-shelf for general skills and custom for regulatory content."', 1),
(2244, 561, 4, '"Custom curricula are legally required under the Public Services Commission."', 0),
(2245, 562, 1, 'Participant satisfaction scores are the most important metric; celebrate success.', 0),
(2246, 562, 2, 'The curriculum failed and should be cancelled immediately.', 0),
(2247, 562, 3, 'Satisfaction measures reaction, not behavior change; add behavior evaluation.', 1),
(2248, 562, 4, 'Blame participants for failing to apply what they learned on the job.', 0),
(2249, 563, 1, 'No standards; any employee may facilitate any training without review.', 0),
(2250, 563, 2, 'A one-hour online course with no assessment or observation required.', 0),
(2251, 563, 3, 'Certification based solely on years of experience regardless of skill.', 0),
(2252, 563, 4, 'Competency-based certification including demonstration and peer review.', 1),
